/* 平成28年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h28.committeeSessions.push(...[{"id":"h28-20161021-10","meetingId":"h28-cm10","date":"2016年10月21日","dateIso":"2016-10-21","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時５５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"先に撮影ということですけれども、本会議でも審議中の写真撮影を認めておりますので、ぜひこの委員会でも、冒頭のみではなくて、委員会運営に支障のない範囲で写真撮影を認めるべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"平成２８年請願第１２号、米軍普天間基地及び米軍北部訓練場内ヘリパッド建設に関し品川区議会決議を求める請願","agenda":"平成２８年請願第１２号、米軍普天間基地及び米軍北部訓練場内ヘリパッド建設に関し品川区議会決議を求める請願","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"申請があったというお話でしたけれども、冒頭に請願者の話を聞くということが、議会としてあるべき真摯な姿勢だと私は思います。ぜひ、冒頭での意見表明を認めてほしいと求めましたけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"たけうち副委員長","kind":"意見","question":"その中では、特に取り立てて全てにおいて冒頭に意見陳述をやるとか、申し出があれば全てそれを受けるべきだという議論にはならなかった。今、いいことは先んじてやるべきだという話だけれども、分科会の中ではそういう議論にならなかったということだけはお伝えしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"意見","question":"この問題に関しては随分議論させていただいた経過がありますけれども、請願の紹介議員もいらっしゃるし、私としては、取り立てて入る前に意見陳述する必要はない、従来どおりで対処していいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"意見","question":"私どもとしても、分科会での議論は先ほど出ましたけれども、一般論としてはこれからの議論は必要だと考えておりますが、先ほどの、そのつどということであれば、今回は従来どおり必要ないと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"須貝委員","kind":"提案","question":"今日こういう提案をされたのですが、今、ここで従来のルールを変えてまでやるのはいかがなものかなと。やるなら、やはり議会できちんと議論して、はっきり１つの方針を決めて進んでいくべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"この間、さまざまな意味で意見を傾聴していく姿勢を明らかにしていくことが最も求められていると思います。ご準備をされている中身をぜひお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"あべ委員","kind":"意見","question":"今、いろいろルール的なものは整備して入れていくのが手順としては妥当かなと考えていますので、ぜひそういった形で進めてほしいと求めました。これは検討会に向けての補足の意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"中塚委員","kind":"提案","question":"私は、よいことは前倒ししていったらどうかと提案させていただいたのですけれども、ぜひ引き続きご議論いただきたいと一言述べたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"防衛に関するこうした意見書を求める請願等、決議を求める請願等々が出ていて、論を待たないところだと思います。県本部、それから党本部のほうで今しっかりと議論を進めていると私も理解しておりますので、区議会としては取り上げる必要はないと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"あべ委員","kind":"意見","question":"ただ、これを品川区議会の決議という形に持っていくかどうかは、まだそんなに条件がそろっていないのではないかと思います。あるいは代表者の意見として決議を上げていくのは、少し違和感がある、今のところはそのように感じていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"須貝委員","kind":"意見","question":"我々、品川区議会が全国的議論に積極的に主体的に参加していくというのは、そこまでは及ばないのではないかと思います。今回の請願に関しては、私の考えでは、意に沿うことは難しいと考えますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"それぞれご意見を伺いまして、ありがとうございました。それぞれご意見を伺いましたけれども、ぜひ賛成をしていただけたらと、改めて訴えたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"飯沼副委員長","kind":"意見","question":"私は２回しか沖縄に行っておりませんけれども、辺野古基地にも参りました。この東京品川からも発信していくことが大事である、今特にそういった時期であると思っていますので、ぜひこの請願の応援をしたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"冒頭でも述べましたけれども、まず、冒頭でやるべきだという点と、審議が終わった後の意見陳述を受け付けないというのは私はとても理解ができません。やはり区議会として請願者の思いにしっかり耳を傾けるというのは当然の姿勢だと思いますので、私はぜひ意見陳述を認めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"須貝委員","kind":"質問","question":"ここに出ている委員の方も皆さん勉強されていると思います。ですから、こういう書面によるご意見をいただいて、それで審議するという従来どおりの形でいいのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-03","title":"平成２８年第３回定例会","agenda":"平成２８年第３回定例会","exchanges":[{"speaker":"あくつ委員","kind":"提案","question":"提案させていただきました会派としても、ぜひ、地方からも声を上げるという点でお願いしたいと思います。ありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"}]},{"id":"topic-04","title":"議長会等の報告","agenda":"議長会等の報告","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"１点だけ、政務活動費に係る対応についてだけお伺いしたいと思います。大きく２つの問題があって、それをそれぞれ改善しようということですけれども、もう少し詳しくご説明を受けたいと思います。","respondent":"原区議会事務局長","answer":"私どももそういう意味では報道の範囲でしか説明ができません。富山、多くの自治体の事務局がそういったことをしているという記事も載っているということで、大きく２点についてご報告させていただきました。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"そういうルールがあるにもかかわらず、今回名前が載っていたというのは、どういうことなのですか。そうすると、一々議長の言うことは聞くことはないということでいいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"鈴木（真）委員長","kind":"確認","question":"というのは、一括して最後まで出られないということではなくて、今日、私も確認をとらせてもらいました。ですから、ご本人としては出席の意思を持った上で、当日に欠席という連絡を事務局にとっています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"そこで、３０分も４０分も我々は言われて、それでおろしました。こんなことをやっていいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問","question":"今回は先に伺って、１回あって、２度目にそういう形をとらせていただいたと思います。委員名簿のところから削除するというのは、それはそれで対応していくべきだと今でも思っていますし、今後もそうするべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"あべ委員","kind":"確認","question":"質問時間の問題もありますし、やはりそこは適正な運用ということを心がけるというか、守っていく必要があると思います。そういうことがあった場合はどうするとか、これは確認のために聞くのですけれども、品川区議会としてはいかがな対応なのか尋ねました。","respondent":"原区議会事務局長","answer":"個人情報ですので、それは当然、秘匿義務がありますので、そういう扱いの中で取り扱います。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひ厳格に運用してほしいと求めました。今後も。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701951?Template=document&Id=5198#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":25104,"voices":101}},{"id":"h28-20161107-6","meetingId":"h28-cm11","date":"2016年11月7日","dateIso":"2016-11-07","committee":"区民委員会","time":"午後 １時００分～午後 ３時１５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)青少年対策地区委員会発足６０周年記念事業","agenda":"はじめに、(1)青少年対策地区委員会発足６０周年記念事業","exchanges":[{"speaker":"いながわ委員","kind":"意見","question":"簡単で構わないので、実施事業で(1)、(2)、(3)とあるのですけど、予算的な部分というのはどういう感じになっているのか。(3)に関しては記念誌は何冊ぐらい作成するのかとの意見を述べました。","respondent":"伊崎地域活動課長","answer":"こちらは予算としましては、６０周年事業として１５０万円です。こちらをどのように配分するかということはこの地区委員会のほうで検討いただいているということで、こちらのほうには報告を受けていないところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"青少年対策地区委員会発足６０年ということで、健やかな成長のこの取組み、これもよい取組みだと考えています。６０周年という節目の年なので、直接のメンバーの中からそういう意見や、どんなふうにお考えかということだけ一言伺いたいと思います。","respondent":"伊崎地域活動課長","answer":"社会に対してどのような訴えかけをしていくかということも重要なことだと考えていますので、この名称が存続しているものと考えております。特に名称について、委員会のほうからご要望が上がったという経緯はございません。","id":"exchange-002"},{"speaker":"中塚委員","kind":"意見","question":"もちろん実際にやっている取組みは子どもと向き合っていらっしゃると思うし、当然、子どもは守られるべき存在だと思いますので、そういう意味では対策なのかなとも思うのですけれども、一言意見だけ述べさせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"藤原委員","kind":"質問・要望","question":"オリンピック・パラリンピック準備課長にお伺いしますけれども、こういうホッケー体験こそ、もっとオリンピックのポスターを張るだとか。「わ」が目立っていたのですけれども、その辺の機運という意味で、その辺についてはいかがか尋ねました。","respondent":"伊崎地域活動課長、濱田生活安全担当課長、小川オリンピック・パラリンピック準備課長","answer":"この子どもイベントを実施するですが、６０周年記念事業をどのようにつくり上げていくかということを検討なさっていらっしゃいます。… 昨年の１２月に区と商店街等が保有する、団体が所有するマスコットと防犯協定を結びました。これが今回のものには… 具体的にポスターを使うにあたっては、それぞれ必ずそのイベントごとに大会組織委員会に確認をとる必要があります。","id":"exchange-004"},{"speaker":"こんの委員","kind":"質問・要望","question":"１点、確認をさせてほしいと求めました。実行委員の方々がどういうもの、横断幕みたいな、そういうものとかというのはどうなっているのかなという状況を説明を求めました。","respondent":"伊崎地域活動課長","answer":"音響等、児童センターの協力をいただきまして、児童センターの完全なるバックアップのもとにイベントのほうは開催するということで予定しております。","id":"exchange-005"},{"speaker":"こんの委員","kind":"質問・要望","question":"お子さんへのいろいろな対策の思いの形をできるだけ区としてサポートしてさしあげていただきたいですし、してさしあげるのがいいのかな。それはそれでありがたいなと思いますので、ぜひ今後とも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"第１７回品川区中学生の主張大会","agenda":"第１７回品川区中学生の主張大会","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"この３番のテーマというのが、これは１７回通して同じなのですかね。今後どういう施策を展開するかというものの判断材料にもなるので、テーマ自体にどう変化があったのかというところを説明を求めました。","respondent":"伊崎地域活動課長","answer":"こちらの事業も、青少年対策地区委員会のほうで実施しております事業です。区が主催ということではございませんので、地区委員会のほうが計画されて、実施しています。開始した時点で、こういった主張する機会を設けることで、先ほど申し上げました目的を達成するというところではあったとは聞いております。","id":"exchange-007"},{"speaker":"いながわ委員","kind":"質問","question":"別にこれをやめろとかそういう議論ではなくて、せっかく子どもたちが５分ですから１,５００字ぐらいのをまとめて発表するわけですから。次は中学生の主張の全国大会とかがあって、そこで優勝するためにもっと文才を磨くというのですか、もし何かあれば。","respondent":"伊崎地域活動課長","answer":"平成１２年の当初は、第６回から、テーマをなくしたです。なかなかこれを東京都のほうにつなげていくという形は難しいと捉えております。","id":"exchange-008"}]},{"id":"topic-03","title":"しながわ旅本の発行","agenda":"しながわ旅本の発行","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"例えば６ページをご覧いただくと、前もたしか申し上げたと思うのですけれども、この８エリアを色分けしているわけではないですか。その辺をどうお考えなのかということと、僕は知らないですけれども、１２ページのドクターイエローというのは行けばずっと会えるのか尋ねました。","respondent":"鈴木文化観光課長","answer":"まずはこの４カ国語にした背景は、それから韓国語に関しては、区の外国語対応は大体この３カ国語を入れてあるということです。それと翻訳に関しては、これは今その手配をしていますので、そこもしっかりと精査して対応したいなということで考えております。","id":"exchange-009"},{"speaker":"いながわ委員","kind":"質問・要望","question":"大使館に関しては、もちろん賀詞交歓会も数年前から大使館の方々もお呼びしてやっているわけですから、その辺は連携をとってほしいと求めました。それぐらいはしっかりやっていただきたいということと、ほかの諸外国の言葉に関しては、ぜひその辺はいろいろ経費とかの見合いでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"もちろんコンセプトは何ですかと聞けば、まずは全体を記したものということなのでしょうか、これ自身のコンセプトが何なのか伺いたいのが一つです。地図は地図なのはわかるのですけれども、取りとめない質問ですけれども、まずはじめてというところは受けとめながらも、伺いたいと思います。","respondent":"鈴木文化観光課長","answer":"どういうものを対象にしているかとかいう考え方なのですけれども、ご説明申し上げましたように、実は取材はこの３倍か４倍ぐらいの情報がありました。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"さっきも前半で言いましたけれども、例えば戸越エリア、１７ページ、細かく言うとあれですけれども、荏原中延のところで切れているではないですか。だからそういう意味において、本当にこれ、完璧ではないと思うのですけれども、どう思いますか。","respondent":"鈴木文化観光課長","answer":"最後に、難しい質問ですが、何点かと。これ単体ではなくて、これからつくるものと組み合わせるという前提ですので、若手の人が一生懸命取り組んだものとしては合格点かなと考えております。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問・要望","question":"密集地域というのは、いわゆる壊していって、新しいものを建てていただくとかいろいろな考えがあるわけではないですか。バランスというよりも、どっちの考えなのか尋ねました。","respondent":"鈴木文化観光課長","answer":"ですから木密地域のほうの解消、安全なまちにするために変わっていくのであれば、それは仕方ないと考えております。現実問題として、あと一、こういうところもあるというイメージとしてはお伝えしてもよろしいのかなということで考えております。","id":"exchange-013"}]},{"id":"topic-04","title":"所管事務調査を議題とします。 本日は、調査項目、中小企業支援","agenda":"所管事務調査を議題とします。 本日は、調査項目、中小企業支援","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"就業支援事業の１ページ目のほうで、確認なのですけれども、これは品川区内の企業で品川区民という限定した部分でいいのかどうなのかというのが１点。ここはどうしましょうと丁寧に教えてくれて記入する形にはなるのですけれども、その確認というか、どうお考えかということ。","respondent":"立木産業活性化担当課長","answer":"就業のほうからご説明します。３階のイベントホール、それで指定管理料を大幅に超える収入がある関係で、利益還元という形でさせていただいているところです。","id":"exchange-014"},{"speaker":"いながわ委員","kind":"質問・要望","question":"さっきの現状のところで、インキュベーションマネージャーの人件費だという話なのですけれども、人件費が高いですかね。こういった歳出・歳入はどうあるべきなのかという理想をもしわかれば教えていただきたいのと、いや、もしお答えできるのであれば説明を求めました。","respondent":"立木産業活性化担当課長","answer":"先ほどの創業支援センターの経費の部分で、ちょっと説明が足りなかった部分がありますけれども、それぞれ創業支援センターは。そういったものについないだりとか、できるところとつなぐ部分と切り分けてやっていくような形を今のところとらせていただいているです。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"来年度、ぜひそれをテーマにしたセミナーの開催を増やしてほしいと求めましたけれども、いかがでしょうかというのが一つです。働いている人だったら今の会社がどうだったり、必要なところに必要な情報が届くのかなと思いますけれども、その点もいかがか尋ねました。","respondent":"立木産業活性化担当課長","answer":"労基法セミナーのほう、こちらのほうのセミナーが年１２回ほど予定している中では、どのタイミングでというのは考えてまいりたいと思います。いろいろポケット労働法のダウンロードの周知ですとか、そういったことも含めていろいろ啓発等、努めてまいりたいと思います。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"なので、事業の説明会ですよね。パンフレットと就業支援事業の説明会というのでしょうか、それの開催、いかがか尋ねました。","respondent":"立木産業活性化担当課長","answer":"ポスターとかそういったもので、どういったものが有効で、さらに必要なのかどうかというところはちょっと見きわめてまいりたいと思います。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"私ももう４０代になりましたけれども、私の同級生、また一回り若い３０代の人と話をしても同じような状況が生まれているというのをよく私も伺います。そういうときに、そうなれば全体像が見えるものがあると背中を押す一助になるのかなと思いますので、ぜひご検討をほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"藤原委員","kind":"質問","question":"就業支援のほうについてお伺いするのですが、行政というか公が入っていこうという、そもそもの考えを教えていただけますかということ。これこれこうなって、こうなるから、こういうふうに一般の区民の方の税金を使っているわけですから、その辺についてお伺いします。","respondent":"立木産業活性化担当課長","answer":"ブラック企業に関しましては、こちらの求人企業支援の部分に関して応募いただくような企業に関しましては、ブラック企業はないと考えております。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"そこが１点と、それとこれだけのお金をかけているわけですから、毎回とはいわなくても、ちゃんとした統計というか結果がどう出ているのか。１００％というのは私も考えておりませんが、そういう結果というのは出てきていると思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"立木産業活性化担当課長","answer":"非常に有益なプランを持っているような方に関しましては、武蔵小山創業支援センターのほうで引き続き支援のほうを継続しているような状況です。そういった中で、そういった方はやはり継続してやっていくことで、かけた分の税金が区内に還元されるものではないかと考えています。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問","question":"これこれこうでと。もう考えるよりも、せっかく今日この場でこういうふうな形でしてくださいとリクエストしたわけですから、どこか区切りで出していただけませんか。","respondent":"山崎商業・ものづくり課長","answer":"どういう形でこの世界、区内の産業にやはり活力なり何らかの刺激なりという角度で我々も数字は把握していく必要があるなと思っています。いらっしゃる間に、区に寄与していく評価指標なりを工夫して、しっかり対応していきたいなと思っています。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"目的が達成されていないということではないですか。だからそこもいろいろ考えて、していただければ幸いなのですけれども、せっかく商業・ものづくり課長、答弁してくれたので、もう一回お願いします。","respondent":"山崎商業・ものづくり課長","answer":"やはり２年、３年たつと、いろいろ工夫して出しています。そうした意味では、そういったものをしっかりつくって、根づいていっていただくような企業を一つでも多くつくってまいりたいなとは考えております。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"若者等就労支援事業のところで、女性のカウンセリングなのですけれども、子育て中の方もカウンセリングされるということで、お子さんを連れていらっしゃった場合の対応を今はどうなされているのかということを説明を求めました。","respondent":"立木産業活性化担当課長","answer":"ちょっとお預かりして、あやしたりとか、そういったような対応をさせていただいているところです。セミナー等も実際やっているのですけれども、そういった場合は託児とかを用意しまして、ご利用いただくというようなことで対応をしています。","id":"exchange-023"},{"speaker":"田中委員","kind":"意見","question":"セミナーのときには託児があるけれども、カウンセリングのときには特に託児というものは設けていないのですよね。なるべく託児ができる、みてもらえるような環境が整ったらいいなと思うのですけれども、そこら辺のところをとの意見を述べました。","respondent":"立木産業活性化担当課長","answer":"当面はそれで何とか対応はできているのかなとは思っていますけれども、例えばそういったものに関しては少し工夫が必要なのかなというところでは、ちょっと研究の部分が必要なのかなと考えています。","id":"exchange-024"},{"speaker":"伊藤副委員長","kind":"質問","question":"引きとめとかはするだろうけれども、それは非常に難しいような気がするのだけれども、いかがでしょうかというのが１点。それがまた別の品川区の施設に移るのはどうなのかなと思うのだけれども、いかがでしょうかという質問です。","respondent":"山崎商業・ものづくり課長","answer":"しょうがないかなと考えていますけれども、難しい領域ですけれども、そういう可能性を高めてまいりたいなと考えております。例えば西大井の創業支援センター、先ほど１人あるいは２人のブース形式のものから、いろいろ形態があります。","id":"exchange-025"},{"speaker":"伊藤副委員長","kind":"確認","question":"そうではなくて、拡大していって、次に広がっていったとなれば多少理解はするのだけれども、いかがでしょうか。その確認を願いします。","respondent":"立木産業活性化担当課長","answer":"業務拡大の中で広いところを求めてというようなところでは、新たな業務拡大の中で移っていくというようなことなので、安易に移っているというようなケースというのは今のところはないということになっております。","id":"exchange-026"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"こちらの要望としては、投入する税金をこれにかけたわけですから、次の創業支援センターへ移っていただく。さらに品川区の雇用を拡大していく方法を、それぞれのタイミングでしっかり確認して対応してくださるようにお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/294647?Template=document&Id=2766#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":42566,"voices":77}},{"id":"h28-20161107-7","meetingId":"h28-cm11","date":"2016年11月7日","dateIso":"2016-11-07","committee":"厚生委員会","time":"午後 １時００分～午後 ２時５６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件整理しています。","topics":[{"id":"topic-01","title":"の１、報告事項の南品川４丁目特別養護老人ホーム（法人立）の整備計画","agenda":"の１、報告事項の南品川４丁目特別養護老人ホーム（法人立）の整備計画","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"どうしても特養ですとか保育園の運営というと、通常の区への期待もある中で、やはり区とは別建てだという線引きはとても大事だと思うのですね。かかわれないものとして、かかわりという観点で地域の方に誤解のないようにというか、そんなところをどうしていくのかだけ説明を求めました。","respondent":"大串福祉計画課長","answer":"先般、その仕組み、こういったルールといった中に参画をしていただくように協力要請を行っていきたいというふうに考えているところです。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"確認","question":"確認です、そのとおりだと思います。質問ではないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"なぜ社会福祉法人が特養をつくるということで買うことになったのか、そういう条例そのものがどうクリアできたのか教えてほしいと求めました。もう１点は、それは法人なりの方針で進むということになるのか、その点についても説明を求めました。","respondent":"大串福祉計画課長","answer":"近隣の土地所有者の方と調整を行い、一定の解決策といったものが見込めるというところで、この整備計画を立てたというふうに伺っているところです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"近隣の土地所有の方との話し合いの中でも、国が社会福祉法人に呼びかけるというのは、全国的に呼びかけるわけですよね。この慈雲福祉会だけが手を挙げたということなのかを１点お聞かせいただきたいのと、保育園と特養ホーム、わかったら教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"売却等々を予定しているのでということでの働きかけ、これは全国規模で行っていると。先ほど申し上げましたように、昭和２２年に保育園事業を開始し、昭和５１年に社会福祉法人の認可を受けております。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここは割と小さな、小さなというほどでもないのかもしれないけれども、そんなにすごく大規模ということではないなと思ったのです。一番初めにお聞きしたのが区への接点、その辺の社会福祉法人の思いというふうなところがわかったら、最後に教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"法人の規模としてどれぐらいかといったところはなかなか判断が難しいかなというところを感じます。それから、法人からは当然、今月に説明会ということになっておりますので、法人からのご挨拶はいただいているところです。","id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/540863?Template=document&Id=3460#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":6890,"voices":19}},{"id":"h28-20161107-8","meetingId":"h28-cm11","date":"2016年11月7日","dateIso":"2016-11-07","committee":"建設委員会","time":"午後 １時００分～午後 １時５７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"エコプロ２０１６への出展","agenda":"エコプロ２０１６への出展","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"日本最大級の環境展示会ということですけれども、これは今までもやられていたことなのでしょうか。これは全部品川区がかかわってやっていることを内容としてあるのかをお聞きしたいのと、実験したりということになるものなのかを伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"その６２市区町村の中の品川区として展示をいたしております。ほかにもエコプロ２０１６のみどり東京６２市区町村以外の部分も、消費生活アドバイザーや、あと日本商工会議所なども集まっております。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"それと(2)ワークショップ、これは品川区がやるのですか。多分、(3)のステージショーは、これも区とのどういうかかわり合いがあってこのステージをするのか説明を求めました。","respondent":"三ツ橋環境課長","answer":"こちらの中で、そもそも品川区として２３区の１区として対応しているものです。(3)のステージショーの朋優学院につきましては、３Ｒが目的なのですけれども、そちらのショーをまたエコプロで行います。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"これは今後のことも関連してくると思うのですけれども、方向づけもある程度できているのか、どうなのかと思ったのでお伺いします。ワークショップ、ステージショーについては、要はこういうのがあるからどうですかと品川区が声をかけたのか。","respondent":"三ツ橋環境課長","answer":"取組みを実施してもらいたいということが大きくございまして、自分たちが何をしなければならないのかという気づきをテーマとして言っております。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問","question":"１点だけお聞きしたいことがあります。そのことだけお聞かせを願います。","respondent":"三ツ橋環境課長","answer":"品川区商店街連合会が対応していますけれども、補助事業として国産間伐材の事業をしておりまして、品川区がつくっております。事業者に委託をしているものではございません。","id":"exchange-004"},{"speaker":"塚本委員","kind":"確認","question":"一応確認なのですけれども、これは６２市区町村共同事業ということですが、基本的には６２市区町村全部が出展しているのかということ。あくまでもエコプロ２０１６にまず参加登録していって、その中でエコプロ２０１６の全体の中にこのブースがあるから、という確認です。","respondent":"三ツ橋環境課長","answer":"委員おっしゃるように基本的にはオール東京６２市区町村がこのブースの中で実際に展示しております。このエコプロ２０１６の大きな中に、みどり東京６２市区町村の部分がありまして、その中の一つの展示ブースが品川区となっております。","id":"exchange-005"}]},{"id":"topic-02","title":"「しながわ環境ミュージカル」の公演","agenda":"「しながわ環境ミュージカル」の公演","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"２２名の区内在住の小・中学生がオーディションで決定されたということなのですけれども、そのうちの２２名になったのかということと、何かつながりのある団体なのかを説明を求めました。","respondent":"三ツ橋環境課長","answer":"こちらは３５名の小・中学生の皆さんがオーディションに申し込んでいただきまして、その中からオーディションで２２名となっております。そちらの団員に実際に出ていただいている状況です。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問","question":"これは前回と同じ場所で今回もということですが、なぜここの場所で今回もというふうにしたのかということですね。例えばより大きな荏原文化センターのホールとか、そういうところは検討されたことがあるのかどうか、その辺のことをちょっと説明を求めました。","respondent":"三ツ橋環境課長","answer":"昨年度、昨年の３月３０日の本当に最後の最後でしたので、これでいいのかどうかという評価がなかなかできていなかったのが実情としています。今回も好評でありましたら、また会場につきましては今後の課題とさせていただきたいと思います。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"これは２回目ですよね。今回２回目ということで、７０周年記念イベントという形の位置づけで、その辺何かありましたら説明を求めました。","respondent":"三ツ橋環境課長","answer":"「環境へのメッセージもしっかり伝わりました」「環境のことを痛切に感じ、少しずつでも実施したいと思います」。は「見る側だけでなく、出ている子や、それを見に来た友人、知人、家族、品川区で一つになってつくっていますね」という感想もございました。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"キャスト、演技者の子どもたちの感想はいかがか尋ねました。","respondent":"三ツ橋環境課長","answer":"それなので、本当にうれしいし、実際にまた演じたいというふうに言ってくれています。地球環境についても、家族の方で一生懸命話してくれて、節電についても実際にしていきますというふうに聞いております。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"継続的に考えていただきたいなというのがあって、子どもたちがミュージカル、多分興味を持つ子が増えてくるのではないかなと思うのです。今回はそれを見通した形での課題を踏まえながらやっていただきたいなというふうに思っていますが、その辺のご意見をほしいと求めました。","respondent":"三ツ橋環境課長","answer":"今回初めて実際に環境ミュージカルの公演をいたしまして、演出等々もこの先生が壮大なスケールで環境について語ってくれました。興味を持ってもらって、広がりがあると思いますので、ぜひ続けていきたいと考えています。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問","question":"一般公募、９月１８日にオーディションをやられたということなのですけれども、この一般公募のオーディションについての周知はどのようにやられたのか尋ねました。","respondent":"三ツ橋環境課長","answer":"オーディションにつきましては、９月１８日にオーディションをするということを広報でお知らせしたのと、あと区のホームページ等でお知らせしております。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問","question":"小学校とか中学校の先生などを通しての周知はやられていない、もしくはやる予定はあるのか尋ねました。","respondent":"三ツ橋環境課長","answer":"全学校にも募集のお知らせはしております、失礼いたしました。","id":"exchange-012"}]},{"id":"topic-03","title":"平成２８年度区内一斉防災訓練の実施","agenda":"平成２８年度区内一斉防災訓練の実施","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"区内一斉防災訓練なのですけれども、呼びかけや訓練の周知に当たり、エリアメールなどを使うご予定などはあるのか尋ねました。","respondent":"黒崎防災安全担当課長","answer":"今も、しなメール等は活用しているのですが、現在のところ、通信事業者が運営しておりますエリアメールの活用は特に今のところは考えてございません。","id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"その理由は何ですか。何か課題というのがあるのでしたら説明を求めました。","respondent":"黒崎防災安全担当課長","answer":"今こちらの３社では、まだ具体的な区としましての働きかけや、そういうところには行き着いていない状況です。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今回、昨年に比べて８カ所避難所が増えたということで、ごくろうさまでした。これからも増やしていっていただきたいと思うのですが、何か今回できないという理由というのは、どのようなところにあるのか尋ねました。","respondent":"黒崎防災安全担当課長","answer":"では自分たちの地区は全ての避難所を同時に開いてみようではないかというところが、平成２５年度から数カ所出てまいりました。そこはまず交代で１カ所ずつ集中的にローテーションでやってみよう、なかなか急に全てのところというふうには行き着いていない実情があります。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"職員の方がこれに出て大変な作業をやるわけですから、一斉にやるのもできるだけやっていただきたいなと、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"このＡ３のほうなのですけれども、初参加というところに丸がついているのですが、これは平成２７年に丸がなくて、平成２８年に丸がある場合で、初参加に丸がないところというのは、平成２７年以前にやりましたよということなのか尋ねました。","respondent":"黒崎防災安全担当課長","answer":"委員がご質問のとおりでございまして、平成２８年度に初参加となっている以外のところで丸がついていないところは、平成２４年から平成２６年の３カ年の間に参加を既に１回しているという避難所です。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"私たちも一斉にやってくださいという要望を出させていただいて、何年かやっていて、その辺はちゃんと伝わっているのかというところ。それと、去年やった課題をどう今年に反映しようとしているのかというところについてお聞きします。","respondent":"黒崎防災安全担当課長","answer":"共通認識を持っていただき、例年７月以降に総合防災訓練の中で地区のいろいろな会議が始まりますので、もしくは反省事項を周知していくです。説明などを行わせていただいて、本年度の初参加４カ所も含めて、一定の成果は出ているのかなと。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"ほかのところとどうコラボレートしながら、実際の訓練をするわけですから、これだけやってくれるのであれば。その辺の何か工夫はないのか尋ねました。","respondent":"黒崎防災安全担当課長","answer":"今回は、まさに委員ご質問があったとおり、１２カ所で同時に立ち上げた場合の連携等、ここでまずやってみて見えてくることがあるだろうと。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"そこの認識をちゃんと深めながら何か確認作業を一つ入れるとか、何かちょっと具体的に行動として入れておいたほうが本当の意味の訓練なのかなと。有効的に皆さんに周知していただける大きなチャンスだと思いますので、ぜひ試行錯誤していただきたいと思うのですが、いかがか尋ねました。","respondent":"黒崎防災安全担当課長","answer":"ただいまご質問いただいた各学校救護所の連携の部分につきましては、相互間の連絡通信なども含めまして、その辺は具体的な訓練の想定の中に入れて進めてやってみたいと考えています。","id":"exchange-020"},{"speaker":"塚本委員","kind":"質問","question":"幾つかちょっとお伺いしたいのですけれども、最初に、４０避難所を今回対象でやられるということで、区の職員が合計３９０名参集しますと。そこをまず最初にお伺いさせてください。","respondent":"黒崎防災安全担当課長","answer":"区の中で事前動員計画というものがございまして、概ね１避難所に対して１０名の職員が参集する計画になっております。今回は、訓練に参加していただく４０避難所それぞれに、実際に指定をされている職員を向かわせるという訓練内容です。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問・要望","question":"では、そこは有事想定をしているというところで確認をいたしました。(2)本部訓練のイで、２４０名ということなのですが、ちょっとそこのところはどういうことをやる想定になっているのか教えていただきたい。","respondent":"黒崎防災安全担当課長","answer":"現在予定している内容では、まず地域センターの職員も自らの地域センターに参集をし、そこで現地対策本部庶務班としての役割を果たします。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"今の庶務班と調査班ですかね、どういうことがなされたかというのは、当然何か報告書みたいな形でまとめられているのか。こういうことが報告されたとか、レポートというか、そういう形でまとまっているということでよろしいか尋ねました。","respondent":"黒崎防災安全担当課長","answer":"災害対策本部へその結果を報告する、やりとりをするという実働訓練は、今年が初めてになります。実働は今年が初めてになりますので、新たな課題の抽出なり、計画の一部見直しなどは今年度の訓練の結果を受けてということになっております。","id":"exchange-023"},{"speaker":"塚本委員","kind":"質問・要望","question":"では、初めてということなので、ぜひ後に活かせるような形で取り組んでほしいと求めましたので、よろしくお願いします。それとあと、この防災訓練を迎えるに当たって、これまでにどういう感じで取り組んできたというようなところがあれば教えてほしいと求めました。","respondent":"黒崎防災安全担当課長","answer":"医療救護所なり、あとは受水施設があるところは、そこもそれぞれ訓練の参加者が確認して回ると。その中で確認にとどめるのか、実際に何かを動かしてみるのかというような話は出ております。","id":"exchange-024"},{"speaker":"塚本委員","kind":"質問","question":"そういうマニュアルを今回この訓練に活かしていくというのは当然のこととしてあると思うのですが、そこのマニュアルの整備やそういったところについては、今回の訓練を迎えるに当たっての各連絡会議での取組みはどんなふうに受けとめていらっしゃるか説明を求めました。","respondent":"黒崎防災安全担当課長","answer":"いろいろ出てきておりますので、その辺を視野に入れながら訓練を実施させていただいて検証し、マニュアルの完成度を高めていく。実際にそれが有事の際に即使えるマニュアルに少しずつでも変更していきたいというふうに思っております。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問","question":"参加予定町会というのが、今回４０避難所で行うということで、この参加予定町会は、この４０避難所の全町会・自治会の参加になっているのか尋ねました。","respondent":"黒崎防災安全担当課長","answer":"現在のところは、それぞれにここに記載させていただいている町会が参加する予定でございまして、それぞれの避難所に指定されている全町会ということでして、具体的には全てで１６３町会という数になっております。","id":"exchange-026"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"これのそういったやられますというような資料は、改めて議会等には出されるのか尋ねました。","respondent":"黒崎防災安全担当課長","answer":"Ｊアラート訓練の内容につきましては、主は国の訓練ですので、今のところ議会等への資料提出などは考えてございません。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/862367?Template=document&Id=4186#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":16753,"voices":74}},{"id":"h28-20161107-9","meetingId":"h28-cm11","date":"2016年11月7日","dateIso":"2016-11-07","committee":"文教委員会","time":"午後 １時００分～午後 ５時１７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を87件整理しています。","topics":[{"id":"topic-01","title":"ひろまち保育園運営事業者","agenda":"ひろまち保育園運営事業者","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"長谷川キッズライフ株式会社が品川区で運営する保育所の名前を説明を求めました。","respondent":"竹田保育課長","answer":"認可保育園が太陽の子南品川保育園、認証保育所が太陽の子東五反田保育園です。","id":"exchange-001"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"幾つか質問させていただきたいのですけれども、前から話題になっていましたが、今のスタッフがどのぐらい残ることになりそうかということ。それで、実際に今度、新しい運営業者が引き継いだときに、看護師の配置は今どういう見通しになっているのかなということに関してお聞きしたいです。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"それをまたひろまち保育園でも実施するです。それから、ホームページ等で広く熱心に求人活動をしておりますので、４月以降は看護師を配置できるというお答えをいただいているところです。 絵本のほうですけれども、ここはまず保育方針の食い違いの１つでもありまして、最初はほんの数冊しかありませんでした。配置しない場合については、ある一定の対応をせざるを得ないということは考えています。","id":"exchange-002"},{"speaker":"鈴木（博）委員","kind":"質問","question":"３ページ目の「５.現運営業者について」というところで、そうしたら、従業員に対するコンプライアンスの徹底というのがどういう意味なのか。その辺、もしも課長が説明できたら、お願いします。","respondent":"竹田保育課長","answer":"大もとの原因は理事長一族にあったのですが、ただ、現場サイドでも気づいていることが多々あったと。そういったことを見逃していた風潮、そういった面を高める必要があるということだと認識しております。","id":"exchange-003"},{"speaker":"新妻委員","kind":"質問・要望","question":"３事業者からの応募があって、どのような方法で３事業者の中からここに決まったのか、具体的な選定の仕方を教えてほしいと求めました。残っていただける方は引き続き採用していただけるということが保証されているのか、確認をさせてほしいと求めました。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"１１月から移管責任者の引き継ぎ準備を週１回程度行い、１月からは移管責任者、サブメンバー引き継ぎ準備を週２回程度行う。具体的にどういうふうに実施するかにつきましては、協議をして進めてまいりたいと考えております。 １つ目に保育の方針、２つ目に管理体制、３つ目は保育の質という３つの大きなテーマがあったと思います。保育の方針の、着る着ないも含めて、話し合いをして決めるというところでお話をさせていただきました。","id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"その上で、安心して保護者の皆さんがお子さんを通わせられるような円滑な引き継ぎもしてほしいと求めました。保育士の確保も非常に大事なところでありますので、そこもしっかりと区が内容を見ていただきながら、進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"あべ委員","kind":"確認","question":"それから、例えばどちらかの施設の中での保護者の評判ですとか保育の内容ですとか、そういったことを改めて確認されているかどうかということ。もといた方がほぼ１年間残るような形で、新年度が始まってからの引き継ぎといったらいいのですか、そこの部分はどのようにお考えか尋ねました。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"詳細については検討中ですが、職員の数が確定次第、詳細を決めていきたいと考えております。十分対応していくのですが、専門的な内容で保育士等で対応できない場合は、万全な体制で臨めると考えております。決算特別委員会の総括で質問されたときに説明不足だったのですけれども、正規の職員だったのは４人、その人たちが中核となっております。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"現在調査中ということだったのですけれども、まだ調査が続いていて、数字が確定できないということなのでしょうか。いつごろ終わるのか尋ねました。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"質疑の時間ですが、質疑の時間も１５分から３０分を予定しておりましたが、実際はその時間を超えての質疑等を行っております。今回ご指摘の内容は、その内容に踏み込んで、疑義があるですので、こちらは納入業者に文書で照会しています。兵庫の警察で一括してやるのか、どこまで調べ切れるかどうかわかりませんけれども、基本的には業者に当たって詳細は確認したいと考えています。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問・要望","question":"前半のヒアリングのほうなのですけれども、時間だけではなくて、事前に確認するようなことも増えている。なので、ぜひ今回のことはきちんと精査をして決着をつけるということをまず第１回としてやってほしいと求めました。","respondent":"竹田保育課長","answer":"今回の経験を十分参考にしまして、何が欠けていたのか、どういう部分に力をより注ぐべきなのか、十分検討しまして今後の園運営等の参考にしていきたいと考えております。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"ひろまち保育園と同じ民間委託でやられているのか、伺いたいと思います。昨年度採用人数が４００人以上と書かれておりましたけれども、東京あるいは関東では何人採用されているのか、伺いたいと思います。","respondent":"竹田保育課長","answer":"それから、４００名を超える採用人数ということですが、全園での採用数です。１園だけ北海道にあるということですので、ほとんど関東、首都圏での園運営となっております。","id":"exchange-009"},{"speaker":"のだて委員","kind":"確認","question":"４月前だとすると、どういった契約といいましょうか、システムになっていくのか、伺いたいと思います。ほかにもあるのか、伺いたいと思います。","respondent":"竹田保育課長","answer":"それから、引き継ぎのシステムですが、具体的な引き継ぎ内容と契約形態については今後検討していく予定です。それから、領収書等ですが、先ほどもご説明しましたとおり、領収書で金額は確認したと。","id":"exchange-010"},{"speaker":"のだて委員","kind":"確認","question":"領収書の件は、確認されているというところでしたけれども、カーテンとか教材以外のものもあったのかというところで、お願いします。","respondent":"竹田保育課長","answer":"そのほかに疑義のあるものはございません。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"引き継ぎの方法については今後具体化していくということですけれども、実際、どれぐらいの方に残ってもらえそうかという見込みというか、感触はいかがか、お聞きしたいと思います。","respondent":"竹田保育課長","answer":"残るか残らないかにつきましては、保育士の個人的なご都合等もありますので、今の時点で軽々に見込みを言うのは不適当だと考えております。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"報告書の中にも２点書かれていることでも挙げられておりますが、区で考えている不履行というのはどういうところなのか、伺いたいと思います。区の連携というところもあるとは思うのですけれども、区が不履行だと考えている点、伺いたいと思います。","respondent":"竹田保育課長","answer":"今時点で明確に言えるのは、看護師の件だけです。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"保育方針のずれも実際５月から出てきたというところで、方針が守られていない、不履行の部分だと考えています。しっかりと全体を明らかにしていく必要があると思うのですが、そういったお考えはあるのか、伺いたいと思います。","respondent":"竹田保育課長","answer":"適切に委託費等のチェックはしてまいりたいと考えております。第三者委員会等の設置は考えておりません。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間、そういったところも検討していってほしいと求めましたし、やはり保育方針を守らせられないというのが業務委託という手法だと思います。だからこそ、事業者交代ということになってしまったと思いますので、区の民営化の方針をぜひ今一度見直してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問","question":"幾つかお伺いしたいと考えていますが、昨年応募の事業者が入っていたのかどうか、そこを１点お伺いします。時間的にも内容的にも十分行ったということなのですが、区の独自の事業者に対する調査を行ったのかどうか、その点をお伺いしたいと思います。","respondent":"竹田保育課長","answer":"所定の膨大な資料を出していただいておりますので、それを１件１件入念にチェックするとともに、経営判断については専門家に委託しております。区が示す３つの子ども像ですが、「自分なりに考える子ども」、こちらも事業者の提案内容とほぼ一致しています。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこを確認させていただきたいのと、この辺は中身的にはどうであったのか、ぜひ教えてほしいと求めました。「７６億円ため込んでいた、もうちょっと丁寧にこの辺を教えていただきたいのと、公設公営と公設民営の違いをどのように理解されているのか。","respondent":"竹田保育課長","answer":"公設公営と公設民営の違いですが、コラボレーションといいますか、よりよい保育を目指していくというのが公設民営でできることだと考えております。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこは本来だったら品川区自身が熱く語って伝えていくべきところであると思っているのですが、そこをぜひ語ってほしいなとい思うのが１点です。人材面において区の要望に柔軟に対応ということの中身がどういうことなのか、教えてほしいのと、この中身を説明を求めました。","respondent":"竹田保育課長","answer":"保育士等で十分対応できない場合には、専門スタッフを派遣して、ひろまち保育園の利用者プラス近隣の方の子育て相談に応じますという内容です。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"確認","question":"確認したいのですが、正規が４人、あとは派遣とおっしゃいましたか。そこをもう１回伺います。","respondent":"齋藤子ども未来部長","answer":"１４人のうち、区の正規の保育士だった人が４人、その他が非常勤と人材派遣のスタッフだったということです。それがひろまち保育園の中核、実働の中心になっている人たちだです。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"安心安全にしていくというお話もあったので、区がここに少し努力してやるべきことはないのでしょうか。私はすごくそこを求めたいと思うのですが、いかがか尋ねました。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"説明会を１１日の金曜日、１２日の土曜日に予定しておりまして、同じ内容のものを２回予定しております。お答えできない、今月中にもう１回やることもあるという話も受けておりますので… 一気になめらかにしゃべってしまったのですけれども、ここはなめらかにしゃべられないところなのです。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いろいろお話を伺ったのですが、１点お伺いしたいのと、品川区はこの結果をどう受けとめているのか。どう受けとめているのかという評価を聞きたいのと、合意の上での契約解除なのですという表現をされるのかどうか、お伺いをします。","respondent":"竹田保育課長","answer":"一委託者・受託者の関係の中ではこういったことは知り得ないことですので、委託を始めるに当たっては調査しておりますが、おのずと限界があるです。それから、今回、この委員会の報告によって指摘された問題につきましては、十分調査してまいりたいと考えています。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、最後のところ、調査を行っていくというのは、品川区のことでですか。とにかく民間委託が１個破綻をしたというところにおいては、しっかり報告書を出すべきであると思っていますが、いかがか尋ねました。","respondent":"竹田保育課長","answer":"区として特に重きを置かなければならないのは、ひろまち保育園についての部分だと考えております。看護師につきましては年度末の精算を考えておりますし、必要があれば警察に相談していきたいと考えております。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"課長は、不正があったかなかったか、さっきは１００万円くらいとか何か言っていましたけれども、区の調査で終わらせるおつもりでしょうか。どういう項目を改善していくのかというチェックリスト、やはり明らかなものを出してほしいと求めましたが、いかがか尋ねました。","respondent":"齋藤子ども未来部長","answer":"説明ぶりからして、子どものことを考えると、合意解除の運びになりました。第三者委員会を設置する以上に、区民の方、お子様のためにとって最良の選択をしたのではないかと考えております。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"チェックリストはどうだったのかということが１つ残っています。","respondent":"竹田保育課長","answer":"今後、公設民営の選定は続けてまいります。そういった点で、どういう点をチェックしているのかというのは、ある意味、私どものノウハウですので、公開は難しいと考えております。","id":"exchange-024"},{"speaker":"高橋（し）委員","kind":"質問","question":"最初に、第一号の民営化が失敗したとおっしゃった委員がいらっしゃるのですが、第一号の民営化というのは既に１０年指定管理でやられている保育所があって、そちらを考えると、少し表現が違うのだと思うのですが、その点はいかがか尋ねました。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"指定管理も民営化の手法の１つだと考えております。 委員ご指摘のとおり、実績を持って着実に民間の活力を活かして保育園を運営しておりますし、今回は破綻するところを破綻しないように調整したものでございまして、破綻というレッテル張りはいかがなものかというのは率直に申し上げます。","id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"質問","question":"それで、こちらとは違う状況なのですけれども、指定管理で進めてきたと。仕組みとして、こういった報告で済むという言い方はあれなのですけれども、そういった業務委託で再びやろうとしたところのお考えを伺います。","respondent":"竹田保育課長","answer":"今回の業務委託の手法そのものには誤りはなかったと思います。結果として業者を変えざるを得ない状況に陥ったことについては反省すべき点があったかと思いますので、今後に活かしていきたいと考えております。","id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"質問","question":"指定管理との違いで、いろいろなメリット、デメリットがあると思うのですが、こちらの保育園に関する事業の状況に関して、報告という形になると思うのですが、今後、どのような形で委員会等で報告しようとお考えか尋ねました。","respondent":"竹田保育課長","answer":"これから４月までの間に保護者説明会等も数回行う予定です。どの時点でどういう内容を報告するというのは申し上げにくいところがありますので、必要に応じて報告させていただきたいと考えております。","id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これは来年度の予算の話になってしまうからあれなのですが、そういった点、いわゆる事業費関係のことについてはどういう状況になっているでしょうか。答えられる範囲でいただけたらと思います。","respondent":"竹田保育課長","answer":"積算の基礎は基本的には一緒ですので、今、来年度の必要な事業費について算定してるところです。","id":"exchange-028"},{"speaker":"あべ委員","kind":"質問","question":"今回、やはり社会福祉法人が適正に運営していてそれだけの内部留保を持つということは、何かあるのではないかということを前提におつき合いをする。幾つかの端緒を感じとって危機を事前に避けるという視点は必要なのではないかと思いますけれども、その辺、お考えとしていかがか尋ねました。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"しっかりアンテナを張りまして、調査できるところはしっかり調査して、委託を進めてまいりたいと考えております。こちらの事業者ですが、会社説明会の際にも経営者の方がコンプライアンスについては大変重要視していますというお話があ… そういった細かいところを見るのが１つと、もう１つは、見ていくと違いがわかるのです。全国で２万事業者あるらしいのですけれども、この機会を捉えて大きく業界も変わっていくし、自浄されていくのだろうなと考えています。","id":"exchange-029"},{"speaker":"あべ委員","kind":"質問・要望","question":"ただ、今、不正検査士ですとか、いろいろな職種の方も増えていらっしゃる。適切な外部の専門家にもご協力いただきながら、ぜひ精度を上げてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"１つだけ聞き漏らしてしまいましたけれども、保育園の運営における人件費比率を説明を求めました。","respondent":"竹田保育課長","answer":"長谷川キッズライフ株式会社の人件費比率ですが、６５.１％と聞いております。","id":"exchange-031"},{"speaker":"沢田副委員長","kind":"意見","question":"先ほどの絵本の話もありましたけれども、新しく、よくなっていくことだと思うのです。本来５年間、変わらずにやっていただくことでいいと思いますけれども、その辺を説明を求めました。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"当初は品川区と保育を十分協力してというお話がありましたけれども、実際には協力してなし得たものはなかったと考えております。保育士が何人残るかということによるところも大きいと思いますので、そういったものを見ながら… 今、保育課長が申し上げたのは、何人やめて、何人来てくれるか、その人数によって変わります、ということです。","id":"exchange-032"}]},{"id":"topic-02","title":"認可保育園等の新規開設","agenda":"認可保育園等の新規開設","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"９５０人より多くなっていて、数字ではということなのですけれども、それぞれ定員は年齢がありますよね。できれば０歳から５歳まで、もし手元にあれば教えていただきたいのと、それぞれの年齢でも計画より多く提供できるのかということも説明を求めました。","respondent":"大澤待機児童対策担当課長","answer":"それから、０～２歳児、３～５歳児に分けて計画と比べましても、全て計画を上回っている数です。不足分と計画数を足したものを、どちらも超えてありますので、計画上はどちらもゼロになるはずでございました。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"（仮称）にじいろ保育園南大井が８月開設ということなのですが、８月になってしまった理由を伺いたいと思います。いかがでしょうかということと、認証保育園が３歳までと２歳までになっているというのはどういった要因があったのか、伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"２００メートルほどのところに、大田区の公園ですが入新井公園がありますので、そちらを使う予定です。この時期から４月には間に合わないということで、平成２９年５月ごろ完成予定ということで、８月開設を目指しています。","id":"exchange-034"},{"speaker":"新妻委員","kind":"質問・要望","question":"今、（仮称）にじいろ保育園南大井の工事と完成の日を教えていただきましたが、それぞれほかのところも、工事にいつ入って、いつ完成なのかというのを教えてほしいと求めました。","respondent":"大澤待機児童対策担当課長","answer":"（仮称）キッズガーデン南大井は１１月中旬、もうすぐ始まって、１月末には完成予定です。（仮称）ユニバースキッズ大森駅前保育園は、１１月、もう工事は始まっていまして、来月中には完成と聞いてあります。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どういった事業者なのか、きちんと調査をしていただきたいなと思っていますが、どの程度の調査を行っているのですか。中身がわかるようにしていただきたいし、どういう調査をしているのか教えていただきたいのと、聞かせてください。","respondent":"大澤待機児童対策担当課長","answer":"３０分から１時間ほどかけて、保育方針ですとかその方の今までの職務の経験ですとかをゆっくりお聞かせいただいて、区の考え方もお伝えしています。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区だけでなくても、初めてなのですか。いっぱい地域から要求が来ているので、何とかしていただきたいと思うのですが、いかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"現状として大変人材不足であることを会社で認識されて、それは、保育所に入れないから皆さん働けないのだということをご認識されたそうで。平成３０年度の開設につきましては、２件は実現できると考えていますので、何とか実現するように支援してまいります。","id":"exchange-037"}]},{"id":"topic-03","title":"学事制度審議会の開催","agenda":"学事制度審議会の開催","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今度から審議会で使った資料を提出してほしいと求めましたが、いかがでしょうかということと、伺いたいと思います。率直にこれは伺いたいのですけれども、2)についてはどういったことを考えて審議事項に挙げていらっしゃるのか、伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"その点、学校の今後の規模等を考えていくに当たって、通常の学級だけではなくて特別支援等のことも踏まえて考えていくべきではないかですとか。学校改築の考え方ですけれども、学事制度審議会で審議項目として今後検討がされていきますので、諮問させていただいているです。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"資料の公開については、資料であれば自由闊達な意見について制限するものはないと思うので、ぜひ資料を出していただけたらと思います。意見の概要はこれから公開するということですけれども、これはいつごろになるか尋ねました。","respondent":"篠田学校計画担当課長","answer":"ホームページへのアップは、現在、概要を整理していますので、できるだけ早くとは考えておりますけれども、手続が終わり次第という形になろうかと思います。","id":"exchange-039"},{"speaker":"あべ委員","kind":"質問・要望","question":"すいません、私、調べてくればよかったのですけれども、委員の方に学識経験者が３名いらっしゃいますが、それぞれ教育分野の方だと思うのですけれども、ご専門というか、どういう学識をお持ちの方なのか、教えてほしいと求めました。","respondent":"篠田学校計画担当課長","answer":"委員長の名和田先生は、３月まで町会・自治会の取りまとめをされていた方でございまして、地域コミュニティに非常に精通されている先生です。樋口先生は、学校の教育の中身の部分、直接的な部分で、今回は品川教育の関係で引き続きご尽力いただいている先生です。","id":"exchange-040"},{"speaker":"あべ委員","kind":"質問・要望","question":"今、構成を伺って、学校というのは今通っている子どもたちのための施設であるということを中心にぜひ考えてほしいと求めました。やはり子どもを育てる場としての学校ということを置き忘れずに、進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"意見交換の要旨、議会にももちろん報告をしていただきたいのですが、教育委員の方々に対しては非公開なのですか。そこのところが１つと、１５人いらっしゃいますけれども、選定の基準とか決まりごとがあるのでしたら説明を求めました。","respondent":"篠田学校計画担当課長","answer":"教育委員への対応ですけれども、その辺は申しわけございません、そういった形での対応になろうかと思います。学校で直接コーディネーターを新しい形で取り組んでおられる方々に、どちらかと言うと今回は地域を重視して選定させていただいた形になっております。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"以前にそういった意見も述べさせていただいたのですが、ぜひ各代表の方々が意見をたくさん吸い上げて参加をしていただけるようにご努力いただきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"校長会代表の先生は、年度で次の方が交代して入るような仕組みになっているのでしょうか。そこだけ確認します。","respondent":"篠田学校計画担当課長","answer":"議論の継続性がありますので、基本的にはこのまま、引き継いでいただく形が一番いいのかなと思っているのですけれども、ただ、役職でやっていただかなければいけない部分もありますので、場合によって、調整が必要になることもあろうかと思います。","id":"exchange-044"}]},{"id":"topic-04","title":"平成２８年度移動教室実施結果","agenda":"平成２８年度移動教室実施結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"以前報告があったのかもしれませんが、中学校が１校だけ長野に行っているのはなぜなのか、伺いたいと思います。教員についても５人減っていたりするので、そういった点、原因は何なのか、伺いたいと思います。","respondent":"有馬学務課長","answer":"そのときに一緒に行けるようにということで、８年生も実施しているということがあります。それを菅平に統一して変更しましょうということで行いまして、予定といたしましては、来年度は磐梯高原に統一していきたいと思っているところです。","id":"exchange-045"},{"speaker":"のだて委員","kind":"確認","question":"２４名だけ見ると、そんなに教員の方が減るということはないのかなと思うのですけれども、確認です。この名残が１件残っているというところでしたけれども、今の安全性の確保はどうされているのか、伺いたいと思います。","respondent":"有馬学務課長","answer":"その関係の若干の増減が出る関係で、この違いが出るとご理解いただければと思います。おおよそ２００カ所ぐらい、そこで安全の確認をしているということで、実施しています。","id":"exchange-046"},{"speaker":"あべ委員","kind":"質問","question":"特別支援学級のお子さんの参加について、よくわからなくて、特別支援学級の児童あるいは生徒というのは必ず特別支援学級枠で行くことになるのですか。それとも、参加可能なお子さんについては、特に６年生と７年生については、こちらの移動教室に参加することもあり得るのか尋ねました。","respondent":"有馬学務課長","answer":"７年生につきましても、基本的には特別支援学級の枠で行くのが原則という形になります。通常学級で十分に行けるよということであれば、それは個別に相談して対応するという形になるです。","id":"exchange-047"},{"speaker":"あべ委員","kind":"質問","question":"本年度のケースで言えば、６年生ならびに７年生で、特別支援学級のお子さんが通常学級のお子さんと一緒に移動教室に参加した例はあるのかどうか。何か配慮をされた部分、対応が必要となった部分があるのか、説明を求めました。","respondent":"有馬学務課長","answer":"７年生は調べていませんけれども、実績としては通常学級で行っているのは今年はないと考えています。特別支援学級の子どもについては、通常学級のほうで行く場合も合同の特別支援学級で行く場合も、教員とは別個に介助員をつけて行っているです。","id":"exchange-048"},{"speaker":"あべ委員","kind":"質問・要望","question":"逆に言えば、お子さんの状態がどうであっても、学校が行くのだと決めれば、学校として通常学級で行くことは可能ということですか。その辺は、親御さんとはどのような話をされているのか尋ねました。","respondent":"有馬学務課長","answer":"基本的には各家庭でご判断をいただくことになってはいます。ただ、要は最終的にみんなで特別支援学級で行こうねという方が多くなりますと、学校でこうしますからこっちですよと決めつけていることはないです。","id":"exchange-049"},{"speaker":"高橋（し）委員","kind":"確認","question":"確認なのですけれども、先ほどの引率の教員数の計算で、クラス数掛ける１.５プラス校長先生と養護教諭、これは東京都の基準なのか、それとも品川区でこの引率数は決まっているのか尋ねました。","respondent":"有馬学務課長","answer":"東京都のほうは確認はしていないのですが、区で持っている基準の引率数という形になっています。","id":"exchange-050"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"その辺は柔軟にぜひ対応していただきたいというのが１つと、１.５という部分で、その間だけ引率につくことも可能だと思うのです。１.５にこだわらないで、プラスアルファの協力体制というのでしょうか、その辺についてはどのようにお考えか尋ねました。","respondent":"有馬学務課長","answer":"その中で、必要に応じて加配はしますということで、一定の対応はしています。今後、外部委員がいいのか、または補助担任みたいな方がいいのかということは、校長会の意見も聞きながら、また検討していきたいと思います。","id":"exchange-051"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひ前向きに検討してほしいと求めました。これは確認なのですが、お話しいただいて、なければ無事に終わったということで。","respondent":"有馬学務課長","answer":"登山の途中でねんざ気味だということで、タクシーで病院までということが１件ありました。発熱したということで保護者の方を現場にお呼びしたことが１件ありましたけれども、お子さんも一緒に連れて帰るということにはならなかったです。","id":"exchange-052"}]},{"id":"topic-05","title":"平成２８年特別区および東京都人事委員会勧告の概要","agenda":"平成２８年特別区および東京都人事委員会勧告の概要","exchanges":[{"speaker":"あべ委員","kind":"意見","question":"固有教員なのですけれども、あわせて給与改定されるということなのですが、固有教員の管理職については、今、制度上、どうなっているのでしたか。課題として以前積み残しがあったような気がするのですけれども、今後の見通しなども含めて、お教えほしいと求めました。","respondent":"熊谷指導課長","answer":"固有教員の管理職でありますが、副校長までは管理職として配置することが可能です。という一文がありますので、今後また国とやりとりをして、改善を図っていくことが必要であると考えています。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問","question":"４ページの勤務環境の整備等について書かれているところで、昨年もこの報告があったので質問したときに、どのような整備がされているのか。その辺を説明を求めました。","respondent":"熊谷指導課長","answer":"支援センター、それから庶務課、指導課、３カ所に窓口を設置しておりまして、対応を行っているところです。働き方の是正等について、今後も管理職に指導、助言していきたいと考えております。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"担当の方を教えていただきたいのと、どう改善されようとしているのか、説明を求めました。","respondent":"熊谷指導課長","answer":"電話であったり、直接お会いしたりという体制は整っております。勤怠が私どものほうでわかるようになっておりますので、そういったことも加味しながら、各学校に助言をしていっているところです。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問","question":"学校の先生もタイムレコーダーを使っていますよね。９時半とか遅くまで残っていて、記録が残らないと伺ったのですが、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"エラーにはならないです。は反対に、タイムカードで打刻されない方も中にはいらっしゃるのだと思いますが、エラーになることはないです。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問","question":"勤怠の管理は全てタイムカードでされているということか尋ねました。","respondent":"熊谷指導課長","answer":"勤怠の管理につきましては、全てタイムカードで行っているところです。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、土日に出勤して形が残らないということは、その方がタイムカードを通していないという理解でよろしいか尋ねました。","respondent":"熊谷指導課長","answer":"そのとおりです。","id":"exchange-058"}]},{"id":"topic-06","title":"「平成２７年度保護者アンケート」、「平成２７年度児童・生徒アンケート」の結果","agenda":"「平成２７年度保護者アンケート」、「平成２７年度児童・生徒アンケート」の結果","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"例えばどういう本を推奨するとかというようなことをしていたり、もう生意気ですから、そういう子。親が言っても子どもは聞かないということは当然あると思うので、単純に小学生と比較できないと思うのですが、その辺のことはいかがか尋ねました。","respondent":"熊谷指導課長","answer":"３６.２％、３６.２％、と変わっていないのです。仕掛けづくりをしていくことが重要だと思いますし、また、地域図書館との連携も引き続き重視していきたいと考えております。","id":"exchange-059"},{"speaker":"あべ委員","kind":"質問","question":"多岐にわたる質問をされておりますが、結局この質問をして、どう分析して、何に役立てようとされているのでしょうか。今後、分析をされようとしているのか、説明を求めました。","respondent":"熊谷指導課長","answer":"その中で、さまざま見とった上で、学校としてそれぞれの子どもたちにどういう対応をしていくかということを見ていくことが必要だと思います。","id":"exchange-060"},{"speaker":"あべ委員","kind":"質問","question":"せっかくこれだけのアンケートをするのですから、少ないですねというだけで終わってしまうのでは、労力がもったいないのではないかと。そういう問題意識は多分内部でも若干お持ちではないかと思うのですが、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"保護者が平成２４年度から、児童が平成２５年度からということで、この段階ですぐにがらっと変えるのは難しいだろうという意見が内部でもありました。ですので、今回の結果を踏まえまして、次年度のアンケートに向けて、また検討を進めていきたいと思います。","id":"exchange-061"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひ現場の先生がどういうことを知りたいか、どこに課題意識を持っているかということも組み合わせて、少しずつ深めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"議論もぜひしてほしいなと思うのが１点で、朝食も、子どもたちの様子を見ながら議論をしていただきたいなと思うのが１点です。この設問は昨年と全く同じなのか尋ねました。","respondent":"熊谷指導課長","answer":"ここにありますように、平成２５年度から児童・生徒となっておりますが、そのときとやはり経年変化を見たいということで変えてございません。大もとになっているのは、平成１９年度に文部科学省から調査依頼がございまして、そのときのものを踏まえて作成してきた経緯があります。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"児童・生徒の１日の生活というところを見たときに、テレビとか、一体どこで子どもたちは自由な時間を過ごしているのかなと。この見方というのも今の子どもたちにとって大事ではないかと思って、ぜひそういった調べ方をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"これから中身については今後も引き続き検討していきますので、そういった視点も踏まえながら、設問項目等を考えていきたいと思います。","id":"exchange-064"},{"speaker":"高橋（し）委員","kind":"質問","question":"朝食を食べていないのが小学生で約４％あって、これは人数で言うと６００人ぐらいで、こういう話が出てくると思うのです。ですから、そちらでの活用等もぜひお考えいただければと思うのですが、に減ってしまうということについてのお考えをほしいと求めました。","respondent":"廣田子ども家庭支援課長、熊谷指導課長","answer":"現在のプロジェクトの中で、教育委員会等でやっているものも含めまして、ほかの調査についても、関連にあるものについては参考にさせていただきたいと考えています。教科書を使ってというような、またテストも難しくなってまいりますので、苦手だなという意識を持ってくる子どももいると思います。","id":"exchange-065"},{"speaker":"のだて委員","kind":"質問・要望","question":"逆に、楽しくないとか、やはり楽しく過ごせていない児童が引きこもりになったりということもあり得ると思うのです。いかがでしょうかというところと、回答率を高くしていってほしいと求めましたが、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"各学年ごとにグラフの結果も出ておりますので、見とって、そして対応していくことが重要だと考えております。前半につきましては、以上です。","id":"exchange-066"},{"speaker":"新妻委員","kind":"質問・要望","question":"子どもたちのほうは９５％と高いのですが、そこら辺はどういうふうに見られているのか、教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"今ご指摘があったとおり、さまざまなお考えがあるかと思います。具体的にどういう状況で出されなかったのかというのは把握していないところであります。","id":"exchange-067"},{"speaker":"新妻委員","kind":"確認","question":"確認はされていないということだったのですが、どういう保護者かというのは確認されていることと思いますけれども、しっかりまた手を打っていただけるようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"}]},{"id":"topic-07","title":"平成２８年度全国学力・学習状況調査の結果","agenda":"平成２８年度全国学力・学習状況調査の結果","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"６０から７０のところ、その解釈というのはいかがなのでしょうかというのが１つと、受験する子は逆にあまりやらないと思うのです。その辺、品川区の解釈はどうなのか尋ねました。","respondent":"熊谷指導課長","answer":"先ほどの児童・生徒アンケートで、家庭でどんな勉強をしていますかといったときに、児童・生徒の８０％は宿題をやっていると答えているのです。そこがさらにもう一歩伸びる大きな境目だと思いますので、そこについてはまたそれぞれ各学校で検討していく必要があると思います。","id":"exchange-069"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、必ずしも非常にネガティブな、要するに勉強がわからないとか勉強が嫌いだからやらないという人だけではないと解釈するということでよろしいか尋ねました。","respondent":"熊谷指導課長","answer":"委員ご指摘のとおり、ネガティブな意味で、例えば勉強が嫌いだからといってやらない子もいるかもしれませんけれども、それだけではないと感じております。","id":"exchange-070"},{"speaker":"あべ委員","kind":"質問","question":"これはそもそもどこの県が１番だとか、より手厚く理解を促していくというようなことがたしか目的で始まったものであろうかと考えています。これを学校の中でどうフィードバックをしているか、さらに細かくできるものなのか、そこを説明を求めました。","respondent":"熊谷指導課長","answer":"この回答も、回答累計ということで、ここのところでつまづいたというのがわかる回答になっております。そして学年で組織的な対応をしていると聞いておりますし、学力向上委員会を学校で立ち上げて、これについて検討しているという話も聞いております。","id":"exchange-071"},{"speaker":"あべ委員","kind":"質問・要望","question":"６番の思考を深めるとか、非常に求められている教育活動の１つが、かなり低い数字に見えるのです。区教委としての分析、見方を教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"ですので、よくご覧いただくと多いのですけれども、「当てはまる」とはっきり答えられた先生方が少なかったという結果ではあると思います。これからも重要なところであると思いますので、引き続き、これについては指導していきたいと考えています。","id":"exchange-072"},{"speaker":"あべ委員","kind":"質問・要望","question":"８番の「課題が見られる問題」、国語のところで、要は自分の言葉にまとめて書くところで無回答率が高いというお話だったと思います。各教室で力を入れていただきたいなと思いますが、区教委として、この結果を受けて何かさらなる働きかけは考えていらっしゃいますか。","respondent":"熊谷指導課長","answer":"問題も公開されておりますので、それぞれどこが品川区の子どもたちが苦手とするのかということも含めて、校長連絡会等でも説明をしてきたところです。","id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問・要望","question":"詳しくお伺いしたいのは、このテストは４月に行われて、返ってくるのが秋口ですよね。子どものストレスを減らしていただきたいなと思う見解が１個あるので、そのことについてお伺いしたいのと、わかったら教えてほしいのが２点目。","respondent":"熊谷指導課長","answer":"ですので、全国学力・学習状況調査の調査分析委員、問題作成分析委員がおりますので、その委員会で１年半ぐらいかけてつくっているものです。ですので、予算については、印刷代ですとか配送料はあるかと思いますけれども、それについては私どものほうでは特に把握しておりません。","id":"exchange-074"},{"speaker":"沢田副委員長","kind":"意見","question":"品川区もプラン２１で小中一貫教育を進めていく中の一丁目一番地はやっぱり学力の向上だと思うのですが、区としてどういうふうに考えられているのか。９年間の一貫教育で中学校の成績がなかなか上がらない、どう考えられているのか、というのを説明を求めました。","respondent":"熊谷指導課長","answer":"「漢字ステージ１００」で身につけてきた成果であると考えています。ですので、失敗したところを繰り返さないように、それぞれの学校でもう一度確認していくことが大事ではないかと捉えております。","id":"exchange-075"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"こういった学力状況調査や、都や区でやられている調査は大変意義があると思っています。どう教えていくかとかというところを、ぜひさまざまな調査を現実のカリキュラムや授業内容の参考にしてほしいと求めました、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"}]},{"id":"topic-08","title":"平成２８年度東京都児童・生徒体力調査の結果","agenda":"平成２８年度東京都児童・生徒体力調査の結果","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"１つだけ質問します。学校名は具体的に書いていないのですけれども、単独校と義務教育学校で差とかというのは何かあるのか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"特に大きな違いは見られませんでした。","id":"exchange-077"},{"speaker":"あべ委員","kind":"質問","question":"要は、これは小・中学校でこの分母を持っているわけですけれども、やっぱり発達段階に応じて伸ばしたい力はそれぞれあると思うのです。そういったことはベースにしつつ、品川区ではいろいろなスポーツの強化といったらいいのですか、対策を考えていると思ってよろしいか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"昔のように、放課後とか、公園でみんなで遊ぶという機会がなかなか少ない。個人に応じて、運動についてはその子の将来の部分もありますので、高めていくような取り組みを進めていこうと考えています。","id":"exchange-078"},{"speaker":"あべ委員","kind":"質問・要望","question":"もちろん一方では、ただスポーツテストの項目が上手になればいいというものではないということはぜひ押さえながらやってほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問","question":"低い学校の共通点は見られないというお話だったのですが、そうすると、まだ分析段階ということでしょうか。やっぱりそういったことも必要だと思うのですが、伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"各学校に応じてどういうような取り組みが今後、また、高めるためにはどんなことをすればいいのかということについては進めていこうと考えています。","id":"exchange-080"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どういう感じで配置をされているのか教えていただきたいのが１点と、特に中学生ですか、何か特徴的に最近の傾向とかあるのですか。例えば遊び方とか休み時間の過ごし方とか、そういった面で男女の違いとかが見えているのかどうか、教えてほしいと求めました。","respondent":"村尾教育総合支援センター長","answer":"２つ目の女子の体力が低いという結果について、昨年度、その前も、全体的に中学校の女子が低いというのはずっと継続しているところです。全体的に運動するのを敬遠するような女子が多いのかなというところで、これについても対応していこうと考えています。","id":"exchange-081"},{"speaker":"飯沼委員","kind":"質問・要望","question":"低くて問題がありそうな子どもたちの体力をどう高めていくのか、やはりその辺を具体的に、心を砕いて取り組みを行ってほしいと求めました。とにかく自由に遊べる環境と時間を子どもたちにどうつくってあげたらいいのかなというところにいくのですが、ぜひご努力を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"}]},{"id":"topic-09","title":"品川区立図書館広報誌の創刊","agenda":"品川区立図書館広報誌の創刊","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"これは予算としてお幾らぐらいの経費であるのかというのを教えてくださいというのが１点と、それから、図書館に来た人に紙媒体で配るというのでは。その辺の検討はされているのか尋ねました。","respondent":"木村品川図書館長","answer":"おっしゃったように、果たしてその人たちがとるかというところでは、ちゃんとそこを検討しようよというところでスタートしています。そういう形で、おつき合いのあるところだとか、そういうところに置かせてもらうような形でこれから取り組んでまいりたいと思っています。","id":"exchange-083"},{"speaker":"あべ委員","kind":"質問","question":"いろいろと攻めていっているようで、いいなと思います。ＳＮＳのほう、また動きがあれば教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"高橋（し）委員","kind":"意見","question":"というのが１つと、ちょっと思ったので、その点との意見を述べました。","respondent":"木村品川図書館長","answer":"実際にお手にとりやすいフリーペーパー的な紙質のものあたりは、実際にこれを出した当初から次は検討させるような形で進めています。それから、写真のほうは、申しわけございません、今ご指摘で、なるほどなですので、また気をつけてまいりたいと思います。","id":"exchange-085"}]},{"id":"topic-10","title":"品川区立図書館年末開館の中止","agenda":"品川区立図書館年末開館の中止","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"すいません、何点か確認させてください。とりあえず２つ。","respondent":"木村品川図書館長","answer":"返却ポストへの返却は可能です。〔１１月２９日に「返却ポストへの返却はできません」と答弁訂正あり〕 それから、サービスコーナーはお休みの期間になっております。","id":"exchange-086"},{"speaker":"あべ委員","kind":"質問","question":"１点、こういう理由ですから、これは本年度限りの対応で、来年はまた復活するということで基本的に考えてよろしいか尋ねました。","respondent":"木村品川図書館長","answer":"はい、そのようなご認識で間違いございません。","id":"exchange-087"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/462438?Template=document&Id=4898#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":73065,"voices":224}},{"id":"h28-20161107-5","meetingId":"h28-cm11","date":"2016年11月7日","dateIso":"2016-11-07","committee":"総務委員会","time":"午後 １時００分～午後 ５時４８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件整理しています。","topics":[{"id":"topic-01","title":"平成２８年職員の給与に関する報告及び勧告の概要","agenda":"平成２８年職員の給与に関する報告及び勧告の概要","exchanges":[{"speaker":"南委員","kind":"質問","question":"そういうこともあってＩの１の（４）の２つ目のところに、新２級職等の新たな職の位置付けや、それはそれとして問題だと思うのですね。品川区としては、その点についてはどのようなふうに認識をしているのか、その辺をちょっと伺いたいと思います。","respondent":"米田人事課長","answer":"その中で、それから新たに仕事が増えているところにはつけていくというようなことで、可能な限り適切な人事配置を行っているところです。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"その辺の認識も一つ伺いたかったので、ぜひどういうふうに見ているのかというところを教えてほしいと求めました。今課長が指摘されたところのほうがむしろ私の質問に沿う表現なので、そういうふうに思っているのでちょっとつけ加えておきたいと思っています。","respondent":"米田人事課長","answer":"今後も適宜適切な配置には努めてまいりたいと思いますが、２３区全体で、係長昇任選考ということで実施して。こういうようなことを踏まえつつ、係長のなり手を増やしていくということの必要があるだろうと考えています。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"波及する問題として、今品川区の公務員の人数を改めて伺うつもりはないのですけれども、非常勤の配置がすごく増えてきていますよね。この非常勤が多用されている、改めて今回は正規職員の給与の改定の問題なのですけれども、そのことも要望としてつけ加えておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"勤労者はほとんどですか、１００％近い方が給与は上がってない、所得が下がっている。なぜだというのは、やはり民間が大変だという実態があらわれていると思うのですが、それに人材の確保が必要だとここでうたっていいのかどうか。","respondent":"米田人事課長","answer":"２５年ぶりに３年連続の引き上げということになりましたが、この間ずっと給料表の引き下げということを行ってまいりました。それから、本当にこの辺のところをゆったりと構えていては有能な人材を必要な時に確保できないということでは危機感を持ってあります。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"皆さん区民にかわって区政をおさめられて、我々も監視・監査していくわけですが、そうすると余りにもかけ離れたままでいっていいのでしょうか。このような給与実態というのは、ちょっとあり得ないと思うのですが、身近な自治体としての区の考え方としては、これは疑問に思わないのか尋ねました。","respondent":"米田人事課長","answer":"品川区に限ってということはできませんけれども、特別区域内に事業所のある企業から具体的な数字をいただいたものを集計して積み上げたものです。これを職員の給与と比較してということですので、それを踏まえた勧告というものが特別区人事委員会より出されているものです。","id":"exchange-005"},{"speaker":"須貝委員","kind":"意見","question":"これ以上議論してもあれなのですが、一応今の実態とかけ離れているということと、産業別、職種別、企業規模別で私はそういうのをしっかり出して都民に開示して、こういうふうになりましたということをやはり私は出すべきではないかと申し述べておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これがなかなかつかないから、これはずっと前から言われていて、そこの部分に差をつけていこうという話はどこまで行っているのかというのが１つ。それの効果がどういうふうになってきているのかというのをどう捉えているのかを教えていただきたいのと、その３つをお聞きしたいなと。","respondent":"米田人事課長","answer":"指名制ですが、方向性なのでこういうことで検討しているということなのですが、その前段階できちんといわゆる係長を補佐する役割として昇任し。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"今の昇任選考受験率の低下ということなのだけれども、私の思っているのは課長はまだ試験があるではないですか。その効果が出だしているのかというところだけ最後に説明を求めました。","respondent":"米田人事課長","answer":"その中で管理職の選考制度自体をあらかじめ前に倒して、択一試験だけ突破するような制度があります。今若手の申込の状況というのは、昔と違って伸びているということを私は肌で実感しておりますので、これは変わっていると思ってあります。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"タイミング的にどうなのかと思うのですが。なぜその小林牧場に行かなければいけないのか、その意味がわからないのと、その点についてどういうご見解なのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"我々、ここで競走馬を確保してここで競走馬用施設として利用されていくというところをなぜ見に行く、その趣旨が違うのではないのですか。競走馬を出しているわけではないのにここに行かなければいけないのですかという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701406?Template=document&Id=2060#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":12199,"voices":35}},{"id":"h28-20161108-14","meetingId":"h28-cm11","date":"2016年11月8日","dateIso":"2016-11-08","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ３時５４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件整理しています。","topics":[{"id":"topic-01","title":"本日は、調査項目のうち、国家戦略特区に関することを取り上げ、この間の国家戦略特区諮問会議を踏まえた国や都の動向や本区における検討状況","agenda":"本日は、調査項目のうち、国家戦略特区に関することを取り上げ、この間の国家戦略特区諮問会議を踏まえた国や都の動向や本区における検討状況","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。もう少しこの内容を教えていただきたいと思うのですが、また品川区のかかわりというところを教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"これを直接、ワーキンググループというのが実際のところの規制緩和に関する具体的な検討をするチームですね、国家戦略特区のワーキンググループ。","id":"exchange-001"},{"speaker":"新妻委員","kind":"提案","question":"今後またここができたことで、そういうことも可能であるということでしょうか。今までよりも早く進み、またそれが形となっていく可能性があると捉えていいということか尋ねました。","respondent":"柏原企画調整課長","answer":"区といたしましても、こういったところを活用といいますか、うまく連携をすることによってより進められるのではないかと思ってあります。新たな提案であったりそういったところは積極的にこういった機関を使いながら区も進めたいと思ってあります。","id":"exchange-002"},{"speaker":"あべ委員","kind":"質問","question":"引き続きこの共同事務局について伺いたいのですけれども、共同事務局ができると、一旦はこっちを通すという形になるのでしょうか。その辺いかがなのか尋ねました。","respondent":"柏原企画調整課長","answer":"国家戦略特区の今までやってきた流れといたしますと、まずは先ほど申し上げた東京都の専門の部隊といいますか部署があるのです。ただ、もう少し見きわめたいというところはありますが、今のところはそういう期待感を持って動きたいです。","id":"exchange-003"},{"speaker":"あべ委員","kind":"意見","question":"都内の自治体にとってどういうことになるかというのは、ちょっとまた共同事務局の動きを見定めながらということになるのかなと思います。","respondent":"柏原企画調整課長","answer":"例えば、新たな特区の使い方というのは、今我々のほうでも検討しています。品川区の特徴をどう活かすか、そういった面も頭に入れながら、この使い方というのはもう少し幅広な形で考えていきたいと思ってあります。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問・要望","question":"国から出てくるメニューの中で何が使えるかを考えるのも大切なことだと思います。ぜひ私は必要だと思いますので、品川としてどういうまちをつくっていくのか、何で力をつけていくのかということをぜひ考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"３点お伺いしたいのですけれども、区の土地だけれども、これは国家戦略特区だからこういったやり方になっているのかというところが１点目です。伺いたいと思います。","respondent":"柏原企画調整課長","answer":"例えば１０年間ならいいですよとか、そういったのは占有の考え方で若干あるのですけれども、この国家戦略特区の規制緩和の中で規制を緩和したと。先ほど申し上げたように、年内、もしくは年明けぐらいに開いてもらうような方向性で今調整をしているという状況です。","id":"exchange-006"},{"speaker":"のだて委員","kind":"確認","question":"これは学童クラブですけれども。プロポでやっていくというところも区の土地だから貸し出す相手として区が選定しているということでいいのか尋ねました。","respondent":"柏原企画調整課長","answer":"いずれにしても、民が入るというのが一つ基本になっていますので、そこの考え方は、要するに民間活用ということでは変わってないかと思います。それから、すみません、後段のご質問が……。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"プロポのところでは、先ほどのお話だと区の土地なので貸し出す相手として区が選定していくと受けとめたのがいいのかというところなのですけれども。そして、公設民営のところは、仕組み上は公設民営も可能だということも改めて確認をさせてほしいと求めました。","respondent":"柏原企画調整課長","answer":"土地そのものは区のものですから、それに対してどういった事業者が適切かということで何社か手が挙がる中から選ぶというのをやっているです。もう一点が、考え方として公設民営というところは制度といいますか、それを規制するものではないと考えています。","id":"exchange-008"},{"speaker":"のだて委員","kind":"意見","question":"区の教育方針をやってもらうということではない中で、どういった選定をしていくというのか。ちょっとよくわからないのですけれども、もう少し説明してほしいと求めました。","respondent":"柏原企画調整課長","answer":"直接的に国家戦略特区でそこを何かするよということではありませんので、それからこちらでつくる保育園、それは事業者を選ぶという考え方は同じです。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"港など３つのプロジェクトが例示されておりますけれども、こうした形での特区活用というのですか、考えているのか伺います。改めて、このサービスアパートメントというのも入っているのですけれども、西品川一丁目の計画の直近の状況はどうなっているかをあわせて伺います。","respondent":"柏原企画調整課長","answer":"西品川の部分につきましても、実際西品川で動いている開発については、多分これは具体化する話にはならないのだろうと今考えてあります。今申し上げたとおり、西品川の部分では動いておりませんので、これは虎ノ門のところでこういった動きがあるというのをお示しをしたです。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"これからこういった形で品川区としては特区の活用を考えているのかどうかというのはちょっとお伺いしたので、答えてほしいと求めました。私はやはり保育課と連携をしっかり図った上で、国家戦略特区を動かす所管のお考えとしてはどうかというのをお伺いします。","respondent":"柏原企画調整課長","answer":"新しい提案を含めて特区は活用していきたいと考えていますので、もろもろ、中身を検討して特区は活用していきたいと思ってあります。それから、都市公園における保育園設置計画の検討ということで、検討は所管部門で今も継続的に行っているです。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"連携していないとは言ってないのですけれども、連携した上で地域需要をつかんだ上での計画にしてほしいということで言いましたので、すみません。やはり私は武蔵小山駅周辺、こちらは要望したいのですが、区のお考えはいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"連携等を図りながら待機児童対策というのは喫緊の課題ということで我々も一番重点の項目と思ってありますので、いろいろな手法を使いながら検討ということで、さらに前に進めるような形でいきたいと思ってあります。","id":"exchange-012"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、またこの開設期間１０年を経過した後は更新することはできるのかということと、できるとしたらその更新の要件は緩やかなものなのかどうかということをお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"ですので、１０年間で一旦は切れるというのが基本的な考え方です。保育園をやるという考え方と同じなのですけれども、更新をする際に、更新という手続を一定程度踏んでできるものと理解はしています。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問・要望","question":"女性の活躍推進のために保育園を設置するということになれば、これはいずれ何とかならないかということはぜひ問題提起をしてほしいと求めました。一応お答えを伺っていいですか、現段階での区のお考えを。","respondent":"柏原企画調整課長","answer":"資料は、すみません、これは東京都と国がつくった資料をそのまま出してしまいましたので、私も配慮が足らなかったのかどうかというところはあります。","id":"exchange-014"}]},{"id":"topic-02","title":"意見書（案）","agenda":"意見書（案）","exchanges":[{"speaker":"若林委員","kind":"質問・要望","question":"もう一つ、これは要望事項が２つありますけれども、１回目の意見書ではたしか「品川区と連携を密にとること」ということで。これについて、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"この新ルートについて国と話し合う場というのがあるのかどうか、ちょっとお伺いしたいのですけれども。一番今回の新ルートで最も被害を受ける区の１つということですから、これもぜひ正副案のとおりに残していただきたいという思いがあります。","respondent":"中村都市計画課長","answer":"区といたしましては、これは公の場という中で今まで達成してきたものではなくて、それ以外の調整の中で果たしてきた成果だと認識をしております。事実としては、「協議の場」は現在ございません。","id":"exchange-016"},{"speaker":"安藤委員","kind":"意見","question":"今回は１時間に、４時間とはいえ、その間は４４機飛ぶわけですよね。いろいろな積み残された課題、やはり話し合いができると思いますので、私は出発点として「協議の場」というのは非常に大切だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"あべ委員","kind":"提案","question":"すみません、前半のほうは、つまりこの削除というのは「このまま」から始まるこの一文の削除のご提案ということでよろしいでしょうか。成田空港でも近隣の８自治体と成田空港、「協議の場」をつくるということも提案の内容としては私は不適切とまでは言えないだろうなとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"若林委員","kind":"意見","question":"基盤になるということですので、「この会議の参加は２３区からは区長会会長」云々、それから今先ほど申し上げた「すすめることは遺憾である」と。で、例えば、「一方、品川区に関連する方策が」ということで、いわゆる事実に基づいた客観的な文面にはなるかなと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"渡部委員","kind":"確認","question":"改めて、逆に今の議論も少し伺っている中で申し上げすると、今回のこの正副案で基本的にはこれでオーケーというような話し合いはしています。その確認を私どもの会派としても至急行政部局にもお問い合わせをしたところ、私どもが了承していないという、７月２８日でよかったのでしたっけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"渡部委員","kind":"確認","question":"ただ、この文章を確認といいましょうか見た中で思うのは、私どもとしてはこれはこのままでもいいのかなと実は思いました。ただ、私の中ではマスコミ報道だけによりますけれども、ここは事実ではないかなという判断を実は自民党はしていたのですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"渡部委員","kind":"意見","question":"ただ、そこに関しては削除がいいのかどうなのかというのを今すぐにはというところはあるのですが。いま一度といいましょうか、もし少し何かいじれて出せるような形になるのであれば、それがいいのかなと考えますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"こんの委員","kind":"確認","question":"私たち品川区が理解してないのですから、了承してないのですから、空港に視察に行ったときにもたしかこのことは直接国交省にも確認をしたらば。いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問","question":"ここは削除をしてしまうと逆に流れとして誤解を招くので、ここをもしいじるのであれば、やはり文言修正という形になるかと思います。いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"その予算措置というのはイコール新ルート実施のための予算ですから、私はこれは別に的外れでもないし不正確でもないとは思います。ぜひ残していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"渡部委員","kind":"質問","question":"ですから、その文言のとり方だと思うのですよ。ですから、この私たちが話を進めている中で、進めているというか議論をしていく中で考えていたところであって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"あべ委員","kind":"提案","question":"ご提案なのですけれども、この一節を削除することによって改善というか、双方の思いは……。ここを……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"あべ委員","kind":"質問","question":"ことによって、双方の意見を歩み寄らせることはできないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"あべ委員","kind":"意見","question":"これ全体がやはり地元自治体の理解について背景から説明している部分ですので、ここを切ることによって大きく言いたいことが変わるわけではなくて、歩み寄りができるかなとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"渡部委員","kind":"質問・要望","question":"事実に関しては前段でしっかり触れてあるわけですよね、前文ですし、あくまでも。この１番、２番でいわゆる要望をしっかりしているわけですから、そのような形の意見書で十分なのかなと思うのですが、どうでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"こんの委員","kind":"確認","question":"すみません、確認ですが、今おっしゃったのは、ここの「このまま国土交通省」云々から「遺憾である」を抜いてということということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"こんの委員","kind":"質問","question":"私たちはそういうところでいいかなと思ったのです。その次にどうやって続けるのというところでは、「一方、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"こんの委員","kind":"質問","question":"そうすると、あべ委員と渡部委員とのご意見でいくと、いわゆるここの文章の「地元自治体の理解を得たとして」のここだけを抜いてというところですか。いかがか尋ねました。","respondent":"鈴木（ひ）委員長","answer":"この意見書を今日の委員会の中でぜひまとめていきたいということで、正副で検討をさせていただいて皆さんのところに示した案だったわけなのです。その中でもまたちょっと検討しながら、本当は今日提案したいと思って… このまま国土交通省、進めないでくださいよという意味を込めたということで下に続くわけなのですけれども。そういうことでの意見書だということでの提案として出させていただきました。","id":"exchange-033"},{"speaker":"こんの委員","kind":"意見","question":"正副案で決めていただいたことなので、基本、私たちも早く決めて出すということは気持ちの上では同じです。ただ、特にこの特別委員会で出すこの意見書として、この「理解」という文言は事実は違うということは認識されたほうがいいかなと思いましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"こんの委員","kind":"質問","question":"だから、ここだけを削除する、「事業をすすめることは遺憾である」。そこだけはやはり委員長がおっしゃるように外せない部分、いわゆる外さないといけない部分だと思いますので、どうか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"安藤委員","kind":"提案","question":"提案としては、ここまではどうかなというのがあります。「協議の場」のところですが、やはり意見書を国が予算措置を計上したという段階で出す意見書ですから、現状より１歩でも２歩でも前進していくとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"あべ委員","kind":"意見","question":"問題になっているのは、そういうことではなくて、「得たとして」というところがまずいのだと思うのですよね。得なかったら進めないのだということではないわけなので、「得たとしてすすめる」というところが多分引っかかっているところだと思うのですよとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"あべ委員","kind":"提案","question":"今のご提案の修正だと、そこが予算になったり事業になったりしても、余り課題になっているところがクリアされないのではないかなと私は感じましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"あべ委員","kind":"意見","question":"すみません、この「地元自治体の理解を得たとして」というここを削除すると、多分一番シンプルに歩み寄りやすくなるのかなと。皆さん、１００％になっているかどうかわかりませんけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"渡部委員","kind":"意見","question":"これはどういう言い方がいいのかというのは本当にわからないのだけれども、どういう言葉遣いなのかというところもちょっと何とも言えないような。あべ委員が言っていることはそのとおりで、僕もさっき言っていたのだけれども、ちょっと休憩をとりませんかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"こんの委員","kind":"質問","question":"要するに、この「遺憾」というのは期待したようにならず心残りであると、こういう意味ではないですか。ここはどういうふうに使われていたのかなというのが実はあったので、ここも抜いたらどうなのかという意味も含まれていたところだったわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"若林委員","kind":"質問","question":"委員長のご認識のお答えがない中で、そういう問いかけであれば、「残念である」とかそういう表現は当てはまるかなというのが一つ。もう一つ引き続きいいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"若林委員","kind":"提案","question":"委員長の正副案ということですので、もう他の会派のご意見は伺わないでいいと思いますけれども、もう一回そこの確認をさせてほしいと求めました。","respondent":"鈴木（ひ）委員長","answer":"財産にまで影響を大きく与えるというふうなものですから、そこのところで検討していくという場というのは絶対必要なものではないかなというところで。","id":"exchange-043"},{"speaker":"若林委員","kind":"質問・要望","question":"私たちも求めていかなければいけない。議会として「協議の場」という公式の場を求めることが、前に進むことになるのか、そうでないのかというところを私は非常に心配をしているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問","question":"「遺憾」でも許容だとは思うのですけれども、何かいい言葉がないかなと、さっきからずっと考えていたものですから。何かこの部分でよりよいアイデアがある方がいらっしゃればいいなと思っているのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"渡部委員","kind":"意見","question":"ただ、語彙力のあるあべ委員が言葉が出てこないのだから私は当然出てくるわけがないのですけれども。「残念」というのも、さきほどぽろっと「残念」と言ったのだけれども、「残念」というのも何か……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"渡部委員","kind":"質問・要望","question":"そう言われてしまうと私たちが求めている、例えば連携を密に取ってもらうということがまず大事なわけでしょう、どっちにしたって。本当にここは「連携を密にとって十分協議すること」というふうに直していただければ十分通じるのかななんて思うのですけれども、どうなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"安藤委員","kind":"意見","question":"「協議の場」というのはいろいろな会派の方も含めて、まず第一歩として、「協議の場」のあり方というのもいろいろあると思います。正式なというか、本当に苦労に苦労を重ねてここまで来ておりますので、ぜひこういった形で決めていければなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"こんの委員","kind":"質問・要望","question":"だから、以下、下を要望するよという文章にしたらどうかということで考えてみたのですけれども、いかがでしょうか。この「要望する」の２行上の「具体的な対策が明らかになっていない状況である」の次に、以下の事項を強く要望する」という文章はいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"やはりこのまま進められてはどうかという思いがあるわけで、例えば「よって」の前の段落の、「品川区に関連する方策が」というこの３行ですね。あ、やっぱり遺憾ですよねというふうになるかなと思いますけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"あべ委員","kind":"質問","question":"ただ、それをやるということであれば皆さんの合意の上にそういう文章をつくり直してみるというのもありかなと、意見書は皆さんの合意の産物ですから。私の意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"筒井委員","kind":"提案","question":"「遺憾である」ではなくて、「問題であると感じる」などに言い換えを行ってみてはいかがかなと思うのですけれども。一つ私の提案としてとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"渡部委員","kind":"質問","question":"どうなのでしょうか。「遺憾」とかではなく、「このまますすめることに不安を感じる」、だから意見書を出すのだというつなぎだとここの文章を残せるのですかね。","respondent":"鈴木（ひ）委員長","answer":"では、正副で検討して、次回に。ちょっと大体詰まってきたと思うのですけれども、ここら辺の表現の仕方ということで、もうちょっと正副で……。","id":"exchange-053"},{"speaker":"こんの委員","kind":"質問・要望","question":"「遺憾である」のかわりの言葉を考えてくださっているのは、確かに下の文章にも不安も、それから危惧するということもかかってくる。要望として上げたいことがまだまだ不安がたくさんあるのだよということにつながるのかなと思うので、今、おっしゃったような言葉でも。","respondent":"鈴木（ひ）委員長","answer":"次回の第４回定例会開会中のところでの行革委員会に提案をして、そういうことで正副預かりにさせていただいてよろしいでしょうか。","id":"exchange-054"},{"speaker":"あべ委員","kind":"質問","question":"何か「協議の場」というのは積み残しではなくて、もう決まりなのでしょうか。ただ、次回でまたここでもめてまた持ち帰りになると、ちょっと予定に間に合わなくなるものですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"若林委員","kind":"質問・要望","question":"要望、そういうものが必要なのではないでしょうかということを再三にわたり申し上げておりますので、そこを踏まえて正副でご検討してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"入れていただきたい大事な点だと考えていますが、第一歩としては非常に大切なことだと思いますので、そこは改めて意見を述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"あべ委員","kind":"意見","question":"あるのであれば、例えば１対１の「協議の場」ということになるのか、「地元複数関係自治体」と幅を持たせたような表現になるのか。そこは特にこだわらずに、そこのところはちょっと配慮してご検討いただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/858443?Template=document&Id=6018#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":43726,"voices":132}},{"id":"h28-20161109-18","meetingId":"h28-cm11","date":"2016年11月9日","dateIso":"2016-11-09","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ３時４７分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そういう要望をぜひ受けとめていただきたいと思っています。ですから、質問という形では、私は準備はしてこなかったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"果たしてどうなのかというところの意見を言って、品川区議会の要望を伝えるということが、とりわけ大事なのではないかと思うのです。ですから、知り得た情報の中で、区議会の思いをしっかりお伝えしていく。","respondent":"渡辺委員長","answer":"競技場等の問題については、推移を見守って、そして、最新情報を得たところで審議をしていく、そういうふうに考えています。必要な情報があって、必要な審議の時間があれば、とってまいりますので、よろしくお願いします。","id":"exchange-002"},{"speaker":"南委員","kind":"意見","question":"こちらでやるために２００億円も下がるなんて、どうなっているのだということが、大きな関心になっているわけです。そういう点について、はからっていくべきだと思っているので意見を言ったので、品川区の狭い範囲のことだけの議論ではないはずだと私は思っていますとの意見を述べました。","respondent":"渡辺委員長","answer":"必要がある場合にはもちろん取り上げますが、基本的には、年度当初からの調査事項に沿っていきたいと考えています。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/158474?Template=document&Id=6504#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":6852,"voices":17}},{"id":"h28-20161111-10","meetingId":"h28-cm11","date":"2016年11月11日","dateIso":"2016-11-11","committee":"議会運営委員会","time":"午後 １時００分～午後 １時１１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"地方議会議員の厚生年金への加入を求める意見書の提出等","agenda":"地方議会議員の厚生年金への加入を求める意見書の提出等","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"意見書（案）と要望書（案）は、ここを１点伺いたいのと、あと２３区議会の状況というのでしょうか。発送はそれぞれこの日時だとは思うのですけれども、２３区議会の状況もわかりましたら教えてほしいと求めました。","respondent":"原区議会事務局長","answer":"２３区の関係ですけれども、どんな状況かというのは数区には聞いてみたのですけれども、まだこれからだというところで聞いているところです。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701951?Template=document&Id=5200#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":4243,"voices":13}},{"id":"h28-20161122-10","meetingId":"h28-cm11","date":"2016年11月22日","dateIso":"2016-11-22","committee":"議会運営委員会","time":"午前１０時３０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件整理しています。","topics":[{"id":"topic-01","title":"地方議会議員の厚生年金への加入を求める意見書の提出等","agenda":"地方議会議員の厚生年金への加入を求める意見書の提出等","exchanges":[{"speaker":"あくつ委員","kind":"意見","question":"都道府県のほうも４７都道府県の中で二十数道県しか出していないという状況がある中で、これは慎重を期すべきではないかなと。全国市議会議長会のほうがどういう意図だというところも正直まだわかっていないところもありますので、このような状況でありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"お二人の意見も伺いましたけれども、第４回定例会にこだわらず、そういう話なのかなと考えています。まずは住民合意を丁寧に把握すべき検討だと思いますし、今二会派からご意見ありましたけれども、これを今出すという必要性はないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"あべ委員","kind":"意見","question":"やはり半分は議員の場合は税金ということになってしまうということを考えると。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"この対応を地方議会として議長に、やはり全国市議会議長会のほうに改善するような要望をしていくということが私は賢明だと思います。今、国民も大変な状況の中にいるわけですから、今回この提出に対しては、私はやめるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701951?Template=document&Id=5202#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":11085,"voices":38}},{"id":"h28-20161128-6","meetingId":"h28-cm11","date":"2016年11月28日","dateIso":"2016-11-28","committee":"区民委員会","time":"午前１０時００分～午前１１時２８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)品川・ジュネーヴ友好憲章締結２５周年 ジュネーヴ市公式訪問報告","agenda":"はじめに、(1)品川・ジュネーヴ友好憲章締結２５周年 ジュネーヴ市公式訪問報告","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"全然違う視点で質問させていただきたいのですが、６１ページにジュネーヴ市交流事業の派遣と受入数という表があるのです。その辺を少し教えていただきたいです。","respondent":"河内協働・国際担当課長","answer":"可能であれば、もちろん増やしていきたいという考えはございまして、国際友好協会のほうともいろいろ話し合っているところです。ホームステイの成果の一番大きなところは、やはり草の根交流の信頼感、友情の醸成にしっかりとつながっていると考えております。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"長い人生のうちの１コマの経験を、せっかく行き来があるわけですから、やっていただきたいなと思います。もし何か一言あるのであれば。","respondent":"河内協働・国際担当課長","answer":"語学力が備わっているか、あるいは相手の国に対してしっかりと認識があるかの面接試験を通じまして、選考しています。両区市をつなぐ大事な役目というところもありますので、一定の語学力も含めまして適任者を送りたいというところで、面接試験も実施しています。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回、友好交流についてのコミュニケ、ちょうど２ページでお名前の確認ということでありますけれども、これに基づいて少し伺いたいのです。今回を通じて、どんな共通認識が得られたのか、この点を１つ伺いたい。","respondent":"河内協働・国際担当課長","answer":"２０年ぶりというところで、それから対応につきまして、大変しっかりと確認できたこと。もっとお付き合いするべきものという認識が育まれた点につきましては、将来の子どもたちに残してあげる財産になったのではないかと認識しています。","id":"exchange-003"},{"speaker":"中塚委員","kind":"確認","question":"いろいろな議論がある中で、お互いの世界平和を促進する共通認識というものが、今回の事業を通じてどのように確認されたのか。今後どのように品川区に持ち帰って具体化をしていくのか、その点を１点伺いたいと思います。","respondent":"河内協働・国際担当課長","answer":"ジュネーヴの歴史もご説明いただいたのですが、ジュネーヴという地で、フランスやオーストリアなどからのいろいろな戦争を経験している国家です。非常に認識を深めたところにおきましては、今回の訪問につきまして、大変有意義だったと考えています。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど説明がありましたけれども、改めて、当初の計画と今回実施されたもので、どこがどのように削減されたのか。経費は最小限にすべきだという意見が多数の会派から出たと思いますので、その点だけ、改めて個別にほしいと求めました。","respondent":"河内協働・国際担当課長","answer":"エコノミー運賃につきましては、委員のご指摘のとおりでございまして、見積り当初よりも安い運賃のチケットがあったというところで下がったものです。私どもが削減に励んだところでは、乗合バスに切りかえまして、成田空港への送迎をしたというところが主なものです。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ具体化していただきたい。社会情勢も踏まえて、節約に努めるという視点が改めて大事だと思いますので、ひとつ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"公式訪問団に部長が行っているわけです。せっかくの報告書なのに、何で行かれた部長が報告しないのか尋ねました。","respondent":"堀越地域振興部長","answer":"ジュネーヴの２５周年記念訪問の事業の全体とあわせて報告ということで、担当する課長から報告させていただきました。私もこの委員会に出席しておりますので、そういう意味では、私からも答弁をするつもりでおりますので、どうぞよろしくお願いいたします。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問・要望","question":"一部の方ではなくて、どことどこと、ちゃんと答えられるほどわかっているのでしょうか。それともう一つ、少し伺いたいのは、文化スポーツ振興部長がすごくお好きな大森貝塚。","respondent":"河内協働・国際担当課長","answer":"私のほうから、これだけで読めるのかという答えになっていないかもしれませんが、そういった形でご説明させていただいているというところです。現在、友好都市ということで、５年に１回のスポーツ交流とホームステイを実施しています。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"最後に、公式訪問団で行かれた部長に質問なのです。実際に行かれた部長に総括的な答弁をいただきたいのですけれども、。","respondent":"堀越地域振興部長","answer":"先ほどご質問がございましたけれども、友好関係があるということと、その目的として、後ろに共通認識という部分がございました。５６ページに友好憲章がございまして、こういう共通認識のもと、お話をすることができたということです。","id":"exchange-009"},{"speaker":"こんの委員","kind":"質問","question":"すばらしい交流を結ばれているということが、今、部長と課長のお話で、これまでの品川区、品川寺とジュネーヴとのご縁でというご説明を伺いました。これまで文化的な交流でどんなことをされてきたのか、そこら辺を、まず参考までに。","respondent":"河内協働・国際担当課長","answer":"オンディーヌという大変有名な音楽学校がございまして、１０周年のときにはパレードも行いました。お互いが尊敬し合うもの、またいろいろな機会を持てるようにということで取り組んでまいりたいと考えているところです。","id":"exchange-010"},{"speaker":"こんの委員","kind":"質問・要望","question":"限られた予算の中で、最大限に交流が図られるように頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"子どもたちへの教育でも、そういうことに触れられているのかなというのが１つお聞きしたい部分です。区民の方たちも、これはもっと知るべき歴史なのではないかなと思うので、その周知方法を説明を求めました。","respondent":"河内協働・国際担当課長","answer":"１月の歴史館での展示ですが、改めて区民の方にしっかりとそのようなところの周知を促したいということを、まずはやっていきたいと思っています。そのほか、折を見つけて周知に励みたいと今考えているところです。","id":"exchange-012"}]},{"id":"topic-02","title":"品川区制７０周年記念 平成２８年度 永年継続事業所顕彰事業","agenda":"品川区制７０周年記念 平成２８年度 永年継続事業所顕彰事業","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"１点か２点か３点、お伺いしたいのです。その辺を教えていただきたいです。","respondent":"山崎商業・ものづくり課長","answer":"実は昨年度から開始しまして、すでに条件の創業１００年以上で区内履歴７０年以上の会社というのは、一定程度の数がありました。当面は３年ということで考えております。","id":"exchange-013"},{"speaker":"いながわ委員","kind":"提案","question":"品川区としては、表彰した人たちに対して何を求めるのか。これは提案になるのかとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"今、実際に産業系で区内で創業を継続するために、いろいろ苦労したり、課題がある事業所があります。そういう意味でも、委員のおっしゃられた資料のご提供など、可能なところでいろいろな可能性を模索してまいりたいなと考えています。","id":"exchange-014"},{"speaker":"いながわ委員","kind":"質問・要望","question":"最後に、ぜひ品川区の産業の中心になる人たちなので、逆に言えば「産業事始」というのを、今、歴史館でやっていますけれども、この２０所だけで１つのイベントが組めるぐらいの資産があると思うので、今後もしっかり取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"その点を伺いたいです。１００年といいますと、考えてみますと共産党もまだ創立１００年はもう少し先ですから、本当に敬意を表したいなと思う会社なのです。","respondent":"山崎商業・ものづくり課長","answer":"ケーブルテレビなどの貴重なＰＲの媒体といいますか、手法といいますか、そういったもろもろの工夫をして、繰り返しになりますけれども、区民の方々に私たちのまち品川の誇りだと思っていただくような形で、ＰＲをしっかりさせていただけたらなと考えています。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"そのときに受け取った２２事業所の方たちの感想などを聞かせていただきたいです。ほかのときでも、それでは報告の場としてちゃんとできないので、ここのところをよろしくお願いしますということです。","respondent":"山崎商業・ものづくり課長","answer":"品川区への地域貢献など、そうしたプラスアルファの部分で頑張って、末永く継続していきたいということが総括でくくれるかなです。説明前に気がつきまして、差替えをさせていただきたかったのですが、口頭の説明で大変申し訳ございませんでした。","id":"exchange-017"},{"speaker":"こんの委員","kind":"質問","question":"どうしたら、これだけ区内で、しかも１００年以上のところが何社もあって、１世紀続けてくるのは大変なことだったと思うのです。１年でも長くお仕事を継続していただくためのアドバイスというか、ノウハウをいただけるようなことは考えられないのでしょうかというのが１点です。","respondent":"山崎商業・ものづくり課長","answer":"先ほど、今回の永年継続の事業所のノウハウなどをつなぐといいますか、活用するということは、区としても大変重要なことだと認識しております。","id":"exchange-018"},{"speaker":"こんの委員","kind":"質問","question":"そうすると、今ご検討ということで、セミナーの講師でと、そういった角度を考えていらっしゃるという感じなのですか。さまざまな事業承継のノウハウを何か銘打ってするようなセミナーがいいのか、どうなのかということですけれども、どうか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"セミナーといいますか、長年つないで、やはり生で聞いていただくようなことが一番基本的には必要かなと考えています。そうした付加価値のような部分も、現経営者の方々などとの交流を通じてつないでいけたら、あるいは聞いていただけたらと考えています。","id":"exchange-019"},{"speaker":"こんの委員","kind":"質問","question":"そういう交流の中で、できればデータ化するというか、こういう企業の場合はこうでといういろいろな事例とともに、データ化して調査みたいなものができれば、そうしたノウハウを１つのものにまとめるような形にしていかれるのもいいのかなと思うのですが、最後にいかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"そうしたこともやって、蓄えといいますか、情報としてつかんでおります。あるいはホームページにアップするなり、そのようなことを通じて、区民の方々にもＰＲさせていただきたいなと思ってあります。","id":"exchange-020"},{"speaker":"こんの委員","kind":"質問・要望","question":"今考えていらっしゃることを進めていただきながら、事業承継もその方たちのさらなる継続も含めて、品川区としてサポートしていく。そうではない、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"いわゆる職人の方たちの中においては、その道一筋で７０年以上やっている方も多くいらっしゃると思うのです。いずれですが、事業所という枠組みではなくして、人に対して、そういう形で区として何かやっていく可能性はあるのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"来年も約２０事業所という形で見込んでいますので、トータルで６０事業所が、今回あたってくるのではないかと考えています。そういう意味では、委員のご質問のような面も含めて、情報を集約して、それをわかりやすくＰＲすることに努めてまいりたいと考えております。","id":"exchange-022"}]},{"id":"topic-03","title":"今定例会の一般質問にかかる所管質問ですが、今定例会の一般質問中、区民委員会にかかわる項目","agenda":"今定例会の一般質問にかかる所管質問ですが、今定例会の一般質問中、区民委員会にかかわる項目","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"１点だけ伺いたいのですが、ふれあいの「あい」はラブの「愛」ではなかったでしたか。愛というか、ラブ。","respondent":"河内協働・国際担当課長","answer":"大変似通った言葉でして、「ふれあい」と「支え愛」というものがございまして、ふれあいサポート活動につきましては平仮名の「あい」でございまして、「支え愛」につきましては、ラブのほうです。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"よろしいでしょうか。多分ビーチバレーだと思うのですけれども、この担当理事者の中で、誰かわかる人がいたら教えていただけないか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"２人のビーチバレーボール選手がビーチバレーをやっている絵面で、お一人の顔が抜かれていて、そちらに顔を出せるような状況になっております。区といたしましては、こういったイベントごとに、今後も活用していきたいと考えているものです。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問・要望","question":"答弁の中で、お子さんたちが喜んでいたという形で効果があるわけですから、もっとアピールしていただきたいと思っているのです。その辺について、もっと積極的にアピールしていっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そちらのパネルにも２０２０年オリンピックのときに品川区内で開催するビーチバレーボールだということで説明も入れさせていただいているところです。適切な場所に、適切なタイミングで置けるように、今後も検討してまいります。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/294647?Template=document&Id=2768#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":26203,"voices":71}},{"id":"h28-20161128-7","meetingId":"h28-cm11","date":"2016年11月28日","dateIso":"2016-11-28","committee":"厚生委員会","time":"午前１０時００分～午後 ０時１０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"たけうち委員","kind":"確認","question":"１２月１日からかな、募集開始というのがもう出ていると。我々からしてみると、その辺のところというのは何か担当のほうからきちんとお話をされているのかどうか、そこをちょっと確認したいのですけれども。","respondent":"大串福祉計画課長","answer":"これは避けたいというところで、職員の募集については早目に採用活動をやってほしいということは法人のほうにお願いをしていた経緯があります。入所者、また第三回定例会で設置条例等で決まっているところもありますので、こちらのほうとしては認識をしているといったところです。","id":"exchange-001"},{"speaker":"たけうち委員","kind":"質問","question":"我々のほうの議会スケジュールなども絡んでくるわけですから、万が一、スケジュール感も含めてやってもらいたいなというのが１つあるのです。何かいろいろな形で我々にも身近になるような取り組みをやってもらえると非常にいいなと思うのですけれども、その前段のほうと２つお願いします。","respondent":"大串福祉計画課長","answer":"それからこの法人の実際の運営活動とのタイムラグというか、そういったところの整合性については、今後ちょっと気をつけていきたいと考えております。","id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"こういう生かし方というのですか、１つの事例が区全体でサービス提供につながるような、法人のカラーによってそこどまりだともったいないことだなと。区全体で波及していくような、そのようなところはどうかなというので、１点だけご質問です。","respondent":"永尾高齢者福祉課長","answer":"ですので、その他小規模多機能の連絡会などでも、先頭で引っ張って認知症のケアについていろいろなアドバイスをしていただいているところです。今後とも新しい法人が来たときには、それぞれの特色を生かして区のケアの向上が図れるように努めていきたいと考えております。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それをきちんと、改めて統一した提供資料の基準のようなものがあるのか、ちょっとそこら辺も教えていただきたいのが１点です。指定管理者というのは議会の議決になるわけですから、それに沿って品川区としては検討されているわけですから、何というのか尋ねました。","respondent":"大串福祉計画課長","answer":"先般、新規施設の設置条例というところで、あわせて運営予定の法人ということでご説明はさせていただいた経過はあろうかと考えています。その点についてまた検討させていただければと考えています。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１つは、私もいろいろとお聞きしたのですけれども、夜勤は１人体制なのかということを１つ確認させていただきたいのと。研修体制がどうなっているのか、また人件費比率とか何かも、わかったらちょっと教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"１人は確実におりますけれども、その状況に応じては複数、２人から３人といったところも法人のほうでは考えているです。研修につきましては、何回やっているなどというところでの細かい数字はちょっと手元にありませんけれども、法人のほうから受けているところです。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私も新生寿会はいろいろと話を伺っていて、新人のときは４月から岡山のほうに行って、ここのグループホームが１８名定員ですよね。それともう一つ、基本１７万円ということで９月のときにも言われましたが、基本１７万円の内訳というのもちょっと教えてほしいと求めました。","respondent":"大串福祉計画課長、永尾高齢者福祉課長","answer":"一応今のところ、先般ご答弁した１７万円ですけれども、家賃については６万５,０００円、あと食費が３万９,０００円を考えております。は共益費、あるいは光熱水費といったところになってこようかと思います。委託ということではなくて助成金として、生活相談員の助成金として４４８万円、毎年区のほうで行っているところです。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私、以前ありすの杜に伺ったときは、ここの施設ではどういうふうな計画がされているのかということをお聞かせほしいと求めました。前回の委員会で貯留槽があるけれども何トンかわからないということだったのですが、そこはわかったら、確認できたら教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"こちらの個人情報についての認識、これを徹底し、取り扱う際の学習とマニュアルを職員全体で実践していくと。こういったものの漏えいにも留意をするというところで、それに付随した形での研修等も検討しているといったところです。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この新生寿会も多分、これだけ大きな法人なのであるのではないかと思うのですが、そこを１点確認させてください。それともう一つ、社会福祉法人制度の改革というので、それはちょっと具体的にどうなるのかということについてもお聞かせほしいと求めました。","respondent":"大串福祉計画課長","answer":"当然そういった形で、この法人についても対応していくです。各法人については、その評議委員の設置に向けて今準備を進めているです。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"住民の代表とか、そういう評議員の設置には区も一緒になって、どういうふうに設置していくかというような所にかかわることはあるのでしょうか。それとも法人が独自に評議員を選んで独自にやるということになるのか、その点だけ説明を求めました。","respondent":"大串福祉計画課長","answer":"お答えからしますと、指導をしているところですので、ご相談は受けします。あるいは評議員、例えば何人設置しなければならないとか、それはあくまで法人のほうでお考えになって決めていただくという流れになっているものです。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"選定基準に基づいてちょっと伺いたいのですけれども、この点でも職員体制がどうなっているのか、これもお聞かせほしいと求めました。それと、この特養ホームについては出されることになるのか、出されるとしたら幾らぐらいになるのかということについても伺いたいと思います。","respondent":"大串福祉計画課長","answer":"それからまた、クリニックを併設するということで、医療サポートの対応をしていくというところ。こちらもやはり委託料というのは、区のほうからはないです。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もうちょっと具体的にイメージできるような中身があったらお聞かせほしいと求めました。例えば住民税非課税世帯で本人の年金が８０万円以下、介護保険料でいえば第２段階の方で、あわせてお聞かせいただけたらと思います。","respondent":"大串福祉計画課長","answer":"２４時間のコール体制、これを整備するというところで、急変時の緊急対応に備えるというところです。看取りやターミナルケアといったところで、今申し上げたような２４時間の緊急対応も行っていけるです。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１４万円から１５万円ということで、要介護４の場合ということで、ちょっと試算して持っていただきたいなと思うのです。多分７万円とか、７万幾らとかと言う形になるのかなと思うのですけれども、そこら辺のところはぜひ試算して持ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"安藤副委員長","kind":"質問","question":"全体的な選考基準についてちょっとお伺いするのですけれども、先ほどから人件費率等の質疑があるのですが。この中の選考基準の中に項目として具体的にのぼって、そこを考慮して選考されるものなのか、そこら辺ちょっと１点お伺いしたいと思います。","respondent":"大串福祉計画課長","answer":"何といいますか、接し方、これを余り感じないような形でお過ごしになられているなという印象を私のほうでも持ったといったところです。","id":"exchange-013"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"その程度のところをお伺いしたいのと、あとこれは要望なのですが、こういった指定管理の指定の議論に当たっての資料の話がありましたけれども。小山地域密着型多機能ホームのほうですが、こちらは区からの委託料というのが幾ら入るのかという、そこら辺をちょっとお伺いしたいと思います。","respondent":"大串福祉計画課長、永尾高齢者福祉課長","answer":"全国平均としては大体２２％が平均というふうになっておりますので、そういったところを含めても、この法人を選考したです。そういったところにも着眼点を置いて、選考を行っているです。 先ほどの助成金という形で出しています。介護報酬については全部その法人のほうに入るような仕組みになっているため、その中でやっているということになっております。","id":"exchange-014"},{"speaker":"安藤副委員長","kind":"質問","question":"すみません。委託料は入っていないということで、あと助成金は幾らなのかだけ説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"助成金については４４８万円になっております。","id":"exchange-015"},{"speaker":"松永委員","kind":"確認","question":"ちょっと私から確認なのですが、どういったところを努力されているのかというのを、もし詳しい内容がわかりましたら教えてください。縮減されることによって、この福祉サービスを安定的に提供できるのかどうかということの確認です。","respondent":"大串福祉計画課長","answer":"加えて小さいところですけれども、利用者の処遇に影響しない範囲での節電ですとか、そういった形での縮減努力をしているといったところです。","id":"exchange-016"},{"speaker":"浅野委員","kind":"質問・要望","question":"こちらのほうについてちょっとお伺いしたいのですけれども、5)なのですが、協定が締結できない。審議というのでしょうか、どういった形でされるのかということを１つ教えていただきたいのと、教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"緊急に指定管理者を指定する必要がある場合といったところで欠格事由、あるいは協定が締結できないという不測の事態です。次のご質問ですけれども、今までそういった事態というのは、私どものほうでは発生はしていないです。","id":"exchange-017"},{"speaker":"浅野委員","kind":"質問・要望","question":"5)があるのですけれども、4)については、その体制について教えてほしいと求めました。5)についても、公募することが適当でないと認められた場合ですけれども、これについても同じような形で教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"なかなかぱっと今、やはり我々行政ではなかなか対応が難しい領域のもので、こういったものがあった場合といったところを想定しているものです。そういったことで、この２番の5)を採用させていただいているといったところです。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その上の２の(1)のところの、施設の適切な維持および管理が図られるものであるかというふうな基準については何をもとにしてこういった判断するのかということをお聞かせいただきたいのと、その点についても説明を求めました。","respondent":"大串福祉計画課長","answer":"それに基づいて、その選考基準に合致するかどうかというところで選考をさせていただいているところです。最大の眼目としてこれまでもやってまいりましたし、今後ともそういった姿勢で指定管理の選定については取り組んでいきたいと考えているところです。","id":"exchange-019"}]},{"id":"topic-02","title":"通所系サービス施設として、(4)第１０８号議案 指定管理者の指定","agenda":"通所系サービス施設として、(4)第１０８号議案 指定管理者の指定","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"補助金というのは同じ額出ているのかということが１つ、それ以外は介護報酬と利用料でされているのかということを１つ確認させていただきたいのと、それから人件費率もお聞かせいただけたらと思います。","respondent":"永尾高齢者福祉課長","answer":"それで離職率ですけれども、平成２７年度の離職率は１２.４％となっております。すみません、人件費率についてはちょっと手元にございません。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"９月のときにこのモニタリングの報告がされましたけれども、利用率が２６年より２７年が若干下がっているような状況というのがあるのですが、そういうところがありましたらお聞かせいただけたらと思いますとの意見を述べました。","respondent":"永尾高齢者福祉課長","answer":"もともとの定員が少ないので、１人、２人で大きく利用率が変わってきてしまうということがあります。直近のでいくと９１.３％になっておりますので、魅力あるようなプログラムをつくるように区としてもモニタリング等で指導しています。","id":"exchange-021"}]},{"id":"topic-03","title":"住宅施設として、(5)第１０９号議案 指定管理者の指定","agenda":"住宅施設として、(5)第１０９号議案 指定管理者の指定","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"大井林町の高齢者住宅ですが、この施設の職員体制がどうなっているかを改めてお聞かせいただけたらと思いますとの意見を述べました。","respondent":"松山高齢者地域支援課長","answer":"こちらの施設長を含め、生活相談員を含めて４名の体制で行っております。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どういうことで配置されているのかというのを教えていただきたいのと、どういうことをさくら会のほうに改善として求めているというのがありましたら、お聞かせいただけたらと思います。","respondent":"松山高齢者地域支援課長","answer":"近隣の保育園との交流も行っております。９０戸の世帯なものですから、男性向けの何かそういったような行事を企画するようにということで、今回改善のほうを提案させていただきました。","id":"exchange-023"},{"speaker":"松永委員","kind":"質問","question":"清掃とかを一緒にされたこともあるのですけれども、そうした中で、まずこの加入促進方法というのはどのような感じでやっているのか。今さくら会の、大井林町のほうでは、大体何割ぐらい町会に加入されているのかだけ伺いたいと思います。","respondent":"松山高齢者地域支援課長","answer":"そこから町会にご参加いただくような、自然な形で交流を進めて、町会への加入を促進しているような形をとっております。町会への加入率なのですが、３分の２の方が町会に入っているという報告を受けております。","id":"exchange-024"}]},{"id":"topic-04","title":"第９４号議案 平成２８年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第９４号議案 平成２８年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"たけうち委員","kind":"確認","question":"確認ですけれども、国籍等は関係なく住民登録があれば、いわゆる外国人の方で品川区の住民登録がある方も対象かどうかということと、それから申請期間が３月から９月と長いのですけれども、随時申請受け付けた方から、支給は一斉ではなくて随時ということでよろしいのか、説明を求めました。","respondent":"大串福祉計画課長","answer":"平成２８年の１月１日現在に住民登録ある方が対象になってくるです。そのやり方、手法につきましては、今年やっているものと同じ形をとるというところでやっていきたいと考えています。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"制度についてちょっと確認をさせていただきたいのですけれども、この５万１,０００人の住民税非課税者というのは、高齢者だけということではなくて品川区民全体の中で支給要件に該当する人ということか、ちょっとそこだけ確認をお願いします。","respondent":"大串福祉計画課長","answer":"６５歳以上の方ということでやりましたので、そちらは年齢要件が入ってまいりましたけれども、こちらも年齢要件は入っておりません。あくまでも住民登録がある方で非課税の方、この２つです。","id":"exchange-026"}]},{"id":"topic-05","title":"平成２８年請願第１６号 安心・安全の医療・介護の実現と夜勤交替制労働の改善を求める請願","agenda":"平成２８年請願第１６号 安心・安全の医療・介護の実現と夜勤交替制労働の改善を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"大変な緊張を求められて労働環境が大変になることはあっても、何というのですか、そういうふうなことにはなっていないというのが実態だと思うのです。どう思われるかということでの、そこら辺のところを皆さんにも伺いたいと思うのですけれども、いかがか尋ねました。","respondent":"渡部委員長","answer":"請願の内容ですので、それに対して説明もいただきましたから、質疑等あればお願いいたします。何かありますか。","id":"exchange-027"},{"speaker":"松永委員","kind":"質問","question":"３番目の「患者・利用者負担を軽減する」、また４番の「この病床削減は行わず」というもの、ちょっと伺いたいなと思います。","respondent":"川島健康課長","answer":"請願項目の部分です。それから保険者のほうの負担等にもいろいろと影響が出てくるのではないかと、この文章からでは推測されるところであるとは思っています。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それとあとは医療とか、介護にしても、需要はどんどん増えているので、自然増というのが８,０００億円から１兆円というふうに言われているのです。だけれども、病院の経営者だけに看護師の増員ということを任せても、なかなかそれはできないというのが実態なのではないかなと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"単価などの改善の要望も出されているわけですけれども、そうした今の医療現場の大変な実態というのを伺うわけなのです。どのような場面でそうした実態をつかむ機会があるのかお伺いしたいと思います。","respondent":"川島健康課長","answer":"なかなか直接の仕事の中で、具体的に反応をつかむなどというところが、今のところ余りないというのが現実です。病院の院長先生とお会いしてそういったお話というのは、私が直接話した中で話題になったというところは、今のところないというのが現実です。","id":"exchange-030"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"ぜひそれはいろいろな場面でつかむ努力をさらに一層していただきたいということで、要望させてほしいと求めました。大もととなる医師、医療スタッフの増員を柱とした改善の意見書を上げていくというのが必要なことだと思いますので、意見を述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"渡辺委員","kind":"確認","question":"再確認で、看護職に限らず課題と捉えているのは、私ども会派でも十分捉えています。それをひとつ例に、把握は難しいだろうなと思うのですけれども、その点だけ説明を求めました。","respondent":"川島健康課長","answer":"今私ども、医療連携会議という会議体を持っておりますので、その中で、医療の中での勤務される方の勤務条件のことですとか、課題等ありましたら、実態把握にそれが使えるのかなと今ちょっと思ったところです。","id":"exchange-032"},{"speaker":"渡辺委員","kind":"意見","question":"この品川区として、各論のこの案件において制度だとか、規制について個別での見解をどうこうという検証については難しいのかなという気がしています。ちょっと意見が先走りましたが、そのような見解ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"たけうち委員","kind":"質問","question":"今、渡辺委員からもありましたけれども、私どもは前回の、昨年の６月ですか、のときのものも議事録を読ませていただきました。それから３番、４番についても、今１つの考え方として出すというのはなかなか難しいのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そして夜勤の低減とか、そういうふうな形でも意見書が上げられないものかなと思うのですけれども、いかがでしょうか。ちょっと区のほうに伺いたいのですが、１回当たり何時間の勤務になっているのか、その介護の現場の実態もあわせてお聞かせいただけたらと思います。","respondent":"永尾高齢者福祉課長","answer":"介護の現場のほうですけれども、その運営法人のほうの裁量の中で動いているというのが実際のところになるかと思います。経営上の努力の中で回しているというのが実態になっておりまして、施設によってかなりその実態というのは幅があるというふうに認識しています。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"課題がどういうふうなところにあるのか、またそれを解決するためにどうしたらいいかというところでは、ぜひ検討してほしいと求めました。東京都にもできたと思うのですが、これができて実際どう変わったのかというあたりがわかりましたら、ちょっとお聞かせいただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"渡辺委員","kind":"意見","question":"東京都なり、国なり、取り組んでいるし、それの推移を見守り、情報を集めるといいますか、注目すべきことだと思います。あるいは自治体として意見書を最終的に根拠を持って上げるかどうかというところは難しいという判断でおりますので、不採択という形だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"たけうち委員","kind":"意見","question":"今いろいろな形で動いている、しっかりこれがどのような形になっていくのか、私たち推移を見ていくことは大事かなと。渡辺委員からあったとおり、余り細かいところで出していくというのは、自治体としてどうかなと思うので、不採択との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"この５局長通知が出されたのも平成２３年ですし、もう５年以上たっているにもかかわらず、全然改善をされていないという状況があります。それと、社会保障費の自然増に対して既に今、そういうところの大もとを変えていくというふうなところも必要だなと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"松永委員","kind":"意見","question":"この課題に関しては我が会派としても認識しておりますけれども、労働時間の明確な数値等、個別の自治体が示すことは困難だと思います。基準についても意見書を出すのは難しいのではないかということで、以上のことから不採択にしたいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/540863?Template=document&Id=3462#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":39466,"voices":144}},{"id":"h28-20161128-8","meetingId":"h28-cm11","date":"2016年11月28日","dateIso":"2016-11-28","committee":"建設委員会","time":"午前１０時００分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)第１０１号議案 品川区廃棄物の処理および再利用に関する条例の一部を改正する条例","agenda":"はじめに、(1)第１０１号議案 品川区廃棄物の処理および再利用に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"現行手数料と廃棄物処理原価との乖離を解消することを目的としてということですけれども、これは乖離するのはなぜなのか。それで、その乖離を解消していくのがなぜ必要なのか伺いたいと思います。","respondent":"小林品川区清掃事務所長","answer":"動物の死体処理は少し性格が違うところがあるかもしれませんけれども、そういうふうに考えてあります。東京２３区につきましては、この受益者負担の原則に従って料金設定をすることが必要であるということで、ご理解いただきたいと思います。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"収入減というところが続いている中で、こういった値上げがされるというのは、結構な打撃なのではないかなと私は思うのですけれども。そういったものの、中小、また商店街、商店の実態というのは、ごみに関してですけれども、どのように把握されているのか伺いたいと思います。","respondent":"小林品川区清掃事務所長","answer":"原則は一般処理業者・許可業者への委託が原則だというふうにご説明をしましたけれども、量にかかわらず、一般処理業者・許可業者は設定できません。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"事業コストも下げる努力というふうに今おっしゃったのですけれども、事業コストというのはどういうふうにしていくと下がっていくものなのでしょうか。その事業コストというものを下げる努力というのは、どのような努力を、どこをどのようにしていくことなのか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"４分の３はもう既に雇上車、一番手っ取り早いのかもしれませんが、これはできません。ちょっと分野が違うわけですけれども、資源のリサイクルを進めていく等の努力をしてまいりましたし、今後もしてまいりたいと考えています。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"４点目は、多分、区民の方が見つけて保健所等々に連絡をした場合にお金をどうするのですか。２５kg以上、猫で２５kg以上というのはないと思うのですけれども、そういう、２５kg以上になった場合はどういう算定になるのか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"１０月実施でというお話でしたけれども、１０月１ヶ月間は、併用して使えるようにしております。したがって、残りの４分の３は、委員ご指摘の野良猫、野良犬、あるいは所有者の特定できないものと、これらについては公費で負担をしております。","id":"exchange-004"},{"speaker":"西本委員","kind":"確認","question":"契約するところが、いや、３５円でできますよと言ったら、３５円のほうが安く済むではないですか。そういうやりとりはあるのか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"その４０円、それを業者のほうへすることはできませんので、自らコスト削減をしていくしかないです。それには動物愛護センター等の連絡先をご紹介して、ご連絡、対応を区民の方にお願いしていることになります。","id":"exchange-005"},{"speaker":"塚本委員","kind":"質問","question":"そういうものとは違う、何かこう、複雑なものなのかという、そこのところをお伺いしたいのですけれども。そこのところをお伺いします。","respondent":"小林品川区清掃事務所長","answer":"それを見込んで収集車両を減らし、その幅で１台を減らせないので、ごみ量との関係ではあります。そのような状況で維持しています。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問","question":"ある程度予測ができるという、乖離していくような仕組みになっているというか、できるのですかね。４年後もまた乖離ということは、乖離しないということでつくられているのかというところが、お聞きしたいのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問","question":"当初の予測よりも大きく経費として膨らんだ結果というようなことが、一番の今回の改定の要因と、４年間においてですね。そういう捉え方として収めておけばよろしいのか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"全体の費用構成としては、おっしゃるとおりです。今回の３円５０銭について言いますと、それから車両等の物件費、主に収集関係の費用が乖離の要因となっているというふうに理解しております。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"人件費と、物品は円安とかいろいろなこともあって、物価が上がっているというところもあるのでわかるのですけれども。人件費もそういうことで、社会の情勢において、当初よりも上向いているというところで判断して、ということで理解すればよろしいか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"ところが、過去、おととしぐらいまでの増加分というのは、明らかに年齢構成に伴う人件費負担だというふうに分析をされているところです。いわゆる施設改修等の費用がかさんでいる等も、小さいものを積み重ねると結構な負担としてコスト増につながっている状況も合わせてあります。","id":"exchange-009"},{"speaker":"高橋（伸）委員","kind":"意見","question":"職員の方がシールを張ってくださいという旨のお知らせはおそらくしていると思うのですけれども、まず、そのことをしているかどうかが１点。平成２７年度、平成２６年度でもいいのですけれども、そういったケースがあったかどうかをお知らせくださいとの意見を述べました。","respondent":"小林品川区清掃事務所長","answer":"しかしながら、この手を緩めますと、町の中、排出場所ではない所に出てきてしまいますので、引き続き対応してまいりたいと考えています。これについては、先ほどご説明しましたように、業者の紹介ということで対応しています。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先ほど、手数料と区長会という話があって、東日本大震災のときに変えなかったと伺いました。ちょっと自分の記憶が曖昧なのですが、前にこの手数料、品川だけ下がっていたときがあったのは、これではなかったか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"前回の平成２５年の改定、その平成２０年当時上げなかった分の差額を２円ずつ足し増しをして、解消をしていきたいと思います。今回の改定がお認めいただけますと、２３区統一の水準に品川区も追いつくという状況にあります。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう１件、動物死体処理のところで、先ほど収集と保管の費用のお話があったのですけれども、収集は別料金でとっているということですか。そこをもう少し説明を求めました。","respondent":"小林品川区清掃事務所長","answer":"上がってきた後の時間で、動物の死体の収集に当たっているので、動物の死体対応のための職員というのはいない。全て公費で、廃棄物総体の中で捻出しているです。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ちょっと意見を言わせていただきたいのですが、こういったごみ処理の手数料のところでも上げる状況ではないのではないかというふうに思っています。やはりそういうところに支援こそ、今、必要なときだと思いますので、この議案には反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"第１０２号議案 品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","agenda":"第１０２号議案 品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"定期利用料金を２,５００円にするということなのですが、あと、利便性が向上するなどを勘案して２,５００円とするということなのですが。２,５００円の所というのはあるのでしょうか、なぜここの大森駅水神口の自転車駐輪場は地下式にしたのか、そこをちょっと伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"もしくは駐輪場を増設したりして対応してきたところでありますけれども、今回、一気に３基の地下駐輪場を増設する。今後の需要予測等もありまして、そういった経緯があってつくっているところです。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"要は自転車は２,５００円が上限で、場所の状況によって２,５００円以内で駐輪場の料金を決めているということなのですが。それを考慮したと書いてありますけれども、そこだけでの２,５００円なのかというのを、ちょっともう１回伺いたいと思います。","respondent":"桑波田交通安全担当課長、安井土木管理課長","answer":"そこをまだ、そこまで使った駐輪場は、区内の中では１つもありません。盗難等の恐れもありませんので、そういったことを勘案しまして、条例の範囲内でそのようにさせていただいたです。こちらの地下式の駐輪場を設置し料金を考えるに当たって、そういったものが、単価の設定を上げさせていただいているというところであります。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問","question":"障害者であるという事情を考慮してもいいのですが、区民の方の利用があまりにも妨げられるのはよろしくないのかなと考える点もあるのですけれども。ちなみに、この障害者の区民以外、区民以外の障害者の方は何人ぐらいいらっしゃるのか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"障害者の方ですけれども、これは区民以外の方、９名いらっしゃいます。全体、区内合わせますと７３名の方がいらっしゃるということで、そのうちの９名が区外の方ということになっております。","id":"exchange-016"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、この大森駅水神口自転車等駐車場は、何名入れるのでしたか。","respondent":"桑波田交通安全担当課長","answer":"地下式駐輪場につきましては、７６５台の車両を収納することができます。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"ということは、区民以外の障害者の方が９名ということで、その程度の利用者数でしたら、区民の方の利用は、今、特に問題にならないという点でよろしいか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"区内全体で９名ですので、対応は十分可能です。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"確認","question":"それで、この受付の方法なのですけれども、施行規則改正のアのほう、優先順位は、手続き的にどういうふうにやっていくのでしょうか。そこが、先ほどの説明と、ちょっとどうなっているのかという確認です。","respondent":"桑波田交通安全担当課長、安井土木管理課長","answer":"受付を実施していくように、来年以降、実施してまいります。料金の関係ですけれども、すみません、私、先ほど自転車だけを中心に考えてお話ししてしまいましたが、こちらについては、バイクの料金の表示です。 第１と第２、第２のほうは、このような形になっております。括弧書きで３,３００円と、別の駐輪場になっているので、このような表示になっております。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"意見","question":"それから優先承認関係を１カ月前からやっていく中で、では、区民の方が申込みをしたときに、すぐ４月１日から使えますよという形になるのか。例えば２週間前に決定しましたとか、そういう作業がどうなるのかなという、手続きがちょっとわからなかったのですがとの意見を述べました。","respondent":"桑波田交通安全担当課長","answer":"途中で４月１日で切らないで、利用期間までは使っていただくというふうにしておりますので、４月１日で全てが入れ替わるというふうにはなりません。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"意見","question":"それが、５月なら入れますよという意味にとればいいのか。その辺、申し込むとき、今もう空きがないのは申込み順でしたけれども、その辺の作業の問題が、今の流れがよくわからなかったのですがとの意見を述べました。","respondent":"桑波田交通安全担当課長","answer":"申込みを受けまして、区民以外の方がもうその時点で契約がなくなれば、その月からはお使いいただけます。５月から、６月から、区民の方はそのときから入っていただくようになる流れです。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"意見","question":"水神口の申込み手続きと、その順番づけみたいなのはどういう形になるのか。それで、いつ頃から、いつの時点でここが入れますよと決まるのかなと、日にちがわかればと思うのですがとの意見を述べました。","respondent":"桑波田交通安全担当課長","answer":"まず７６５台できますので、今の見込みですと、申込みされた方は入れるようになっております。カード等の料金につきましては、これは２,５００円の中に入っておりますので、別に取ったりすることはございません。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問・要望","question":"まず今、品川区内で区民以外が利用している数というのがどれぐらいなのかと、もしわかっているのであれば教えていただきたい。基本的に２３区、こういうことが１つの共通的な考え方となっているのか、そこの確認をお願いします。","respondent":"桑波田交通安全担当課長","answer":"区民以外の方なのですけれども、区内全体で見ますと、概ね１６％の方が、区外の方が区営の駐輪場を使っているという状況です。他区のほうでも実施しているところがありまして、こういったところで、区民の優先等を取り入れている状況にあります。","id":"exchange-023"},{"speaker":"塚本委員","kind":"質問・要望","question":"現状を今お伺いしたのですが、今後の１つの方向性としてどういう方向なのか。この辺の見通しをどのように見ていらっしゃるか、お伺いします。","respondent":"桑波田交通安全担当課長","answer":"千代田区でありますとか、新宿区、文京区、荒川区であったりとか、ほかの自治体でも数カ所実施しているところがあります。安定的に使える、当日のほうに行っていただくということで、お互いの入れ替わりという感じにさせてまいりたいと考えております。","id":"exchange-024"},{"speaker":"西本委員","kind":"確認","question":"すみません、先ほど説明があったのですが、確認をしたいのですけれども、大森駅水神口のほうですけれども、利用者識別カード５００円、札が７００円という１,２００円は、２,５００円の中に入っているということでいいのですね、というところを。","respondent":"桑波田交通安全担当課長","answer":"カードの再交付のお金は示しておりますけれども、２,５００円以外で取ることはございません。入っております。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"申込みをして利用していました、でも１年間休みます、それでまた再度するという場合はどういう流れになるのですか。多くなった場合の、使っていくといろいろなパターンが出てくると思うのですが、それはどういう整理の方法を使えるようになっているのか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"同じ単価で実施しているところですけれども、その単価の中で変動があった場合に変えられるようにして、ちょっとにらんで変えているところです。受付しますと最大で６カ月まで更新ができますので、続けていけば、そのまま継続できます。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"値段の上下するということでの設定とは何ですか。ですから、そういうニーズというか、変動というか、心情的なところも含めて、それをどう考えられているのかなというふうに思うのですね。","respondent":"桑波田交通安全担当課長","answer":"何年か後にまた増設といったことも考えられますので、再交付のお金をもらうというふうに決めたいということで、そういうふうに変えていくところです。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"その中で、そうなったときにどう対処していくのかということは、これは準備を進めていっていただきたいと思うのです。そこは、区としてはきちんと考えていただきたいなと思うのですが、それについてのご意見をお伺いしていいか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"地下のほうへ３台増設という、そういうことを見込んで、地下のほうへ増設というふうになったところです。地下だけではなく、地上のほうの駐輪場のほうも残っておりますので、そういったところを活用しながら進めていきたいと考えております。","id":"exchange-028"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、(3)６カ月間と書いてあるのですけれども、という理解でよろしいのでしょうかということ。区民以外の方が、それは規則の第１７条の継続手続のところでそういった整理を行っていくということでよろしいでしょうか、という２点です。","respondent":"桑波田交通安全担当課長","answer":"利用期間については、申込みをされた方が自分で、１カ月間、３カ月間、自分で決めて申込みしていただきます。定期のほうは区民が使っていただいて、常設のほうの空きがなければ、当日のほうを区外の方は使っていただくというような流れになります。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"現在、区民以外の方も定期利用されている方はいらっしゃるのですよね。１つの誘導方法としては、区民以外の方の継続をお断りして、当日利用に行っていただくということでよろしいのか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"４月１日以降は１カ月というふうになりますので、継続的には１カ月やって、翌月からは区民の方が使っていただくというふうにしていくところです。それ以外であれば、また当日のほうをお使いいただくというふうな流れになっております。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それが２,３００円だとほかも下げてという議論になってくるとおっしゃられていたのですけれども、私はほかも下げていっていただきたいぐらいです。より低廉に使えるということは当然だと思いますので、この定期利用料金を２,５００円にするという、ここに反対したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"塚本委員","kind":"質問","question":"いろいろな指定管理期間中ですかね、そういう意味で、これまでの経験を持った事業者が継続してやることが望ましいということだと思うのですけれども。再委託先はどういうところであって、どういった業務内容を委託しているのかという、現状について教えてほしいと求めました。","respondent":"今井住宅課長","answer":"何か、的確に速やかに対応できるというのが、地元の施工業者との今までの連携の中では優れている点だというふうに考えております。区民住宅の年２回の募集に合わせますと、なかなか指定管理者、この辺を注意しながら対応しています。","id":"exchange-032"},{"speaker":"塚本委員","kind":"質問","question":"は委託先についてご説明いただいたのですけれども、その辺というのは、こういうところに資料として示していただいたほうがいいのではないかと。指定管理の議案として上げていただくに当たっては、やはり見える化ということの１つとして、その点についてどのようにお考えか説明を求めました。","respondent":"今井住宅課長","answer":"組織として対応している部分もありますので、この選定理由のところにわかるように書き込むべきだったというふうなご指摘と受け止めております。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"もう１つの、選定委員会の構成は、1)から5)、ありますけれども、これはこういうものなのですかね。選定理由も方々とりつつ、選定するときの理由の中に、いろいろな項目を入れればいい話なのかなと思うのですけれども、それはいかがなのか尋ねました。","respondent":"今井住宅課長","answer":"３月、４月で切ることは、なかなか途中では難しいだろうというふうに判断したのが１つになります。表面にまいりまして、区内の職員の中で行うことで、適切に運用されているところだというふうに理解しております。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、そしてこれからどうしていくのかということを考えると、今までのような状況でいいのでしょうかということも当然議論に入ってくると思うので。次のところに、次の時代、どうやって変えていくかというのを見据えた形で準備等を進めていただきたいなというふうに思っています。","respondent":"今井住宅課長","answer":"今後、区民住宅の借上満了後の指定管理者の選定に当たりましては、きちんとこの辺を踏まえて対応していきたいというふうに考えております。","id":"exchange-035"},{"speaker":"筒井委員","kind":"意見","question":"３の(1)で、要は公募プロポーザル方式で選定した業者数と、このただし書きの特別な理由がある場合の特定の事業者の選定。わかる範囲でとの意見を述べました。","respondent":"今井住宅課長","answer":"そして区民住宅ですけれども、もう１つ、ファミーユの西五反田、西館と東館の指定管理業務というのが、ほかの区民住宅です。こちらにつきましては公募型でございまして、来年度が公募型のプロポーザルを迎える時期です。","id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区民の皆さんの利用するこの区営住宅と区民住宅というところで、ちょっと改めて、この役割を教えてほしいと求めました。","respondent":"今井住宅課長","answer":"所得の低いなど、住宅に困窮する低所得者向けの公営住宅というのが、私どもが考える区営住宅です。中堅所得ファミリー層の定住化を図るために行っているものというふうに理解しておりまして、国の特優賃制度などを活用しています。","id":"exchange-037"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、私たち、以前からずっとこうした区営住宅、区民住宅というのは、区が直営で進めるべきだということを求め続けてきているわけです。株式会社ということなので、ここでも従業員数、また、その方々の平均賃金など、そういうところはわかるのでしょうか、伺いたいと思います。","respondent":"今井住宅課長","answer":"区内の不動産事業者が５名ほど、全ての住宅、現在２２住宅を運営しています。それぞれの適切な法に基づきまして、給料を支給しているというふうに認識しております。","id":"exchange-038"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり株式会社ですので、そういった中でも、この２２棟ある中これだけの人数で管理していくというのもなかなか大変なことだなというふうに思います。今後の区民住宅、区営住宅の管理をしていくというところは、どのように考えられているのか伺いたいと思います。","respondent":"今井住宅課長","answer":"もう１つは、こちらの区営住宅、そして区民住宅につきましては、株式会社品川宅建管理センターということでお願いしています。宅建管理センターを公募の例外ということで対応しておりますけれども、指定管理者の選定方法の原則である、改めて検討していく予定です。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"１つ意見を、この間ずっと区の直営でということを求め続けています。区民の安心な住まいをというところでは、区の直営で進めていっていただきたい、株式会社はなじまないというふうに思いますので、反対します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]},{"id":"topic-03","title":"建設委員会を再開いたします。 引き続き、議案審査、(5)第１１２号議案 指定管理者の指定","agenda":"建設委員会を再開いたします。 引き続き、議案審査、(5)第１１２号議案 指定管理者の指定","exchanges":[{"speaker":"西本委員","kind":"質問","question":"ちょっと５のところで気になるのが何点かあって、自社努力はありがたいのですけれども、どういう意味なのでしょうか。工事費とかいろいろかかると思うのですが、そういうのをどういう考え方で、この自社努力という表現になっているのか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"駐輪場単独で大田区のほうでは実施しているのですけれども、そういったものの費用を考えますと、今回は辞退したということでございました。大きい自転車等に対応できないところも少しずつスペースを確保して、そういった簡易なものについて、自分たちで考えてやっていきますです。","id":"exchange-041"},{"speaker":"西本委員","kind":"提案","question":"いや、私はいいのです、そういう改善提案はあるのだけれども、でも現在できているというふうな、自分で評価をしているとするとどうなのかなと。しているのか、していないのか、その辺はいかがか尋ねました。","respondent":"松代防災まちづくり部長、桑波田交通安全担当課長","answer":"これが続くようであれば、もうこれは申し訳ありませんけれども、代えていただく、もしくは何らかの対応を強制的にやると。この１社しかないときに、そういった指定管理者制度を進めていきたいと、このように考えているところです。 必要な経費については、今後、指定管理者のほうと、いろいろな改善等があれば連携をとりながらやっていきますので、今後また連携を図りながら、出すものは出すということでやっていきたいと考えております。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"先ほどちょっと答弁の中で、要はこのダイナミクスのほうからシルバー人材センターに頼んだりとかしているのですか。その人材センターから派遣されてきている、その派遣された人に対しても、接遇の対応をどういう仕組みでやられているのか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"管理人等をシルバーの方に、ＮＣＤのほうからお願いして派遣していただいているところです。こういった方々に、研修会等の実施と、あと場長等を通じてのいろいろな教養等をやるような仕組みになっております。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"ということは、そういう委託をしても、委託されたＡさん、仮にですね、Ａさんに対しても、きちんと研修はされていますという認識でよろしいのか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"委託された方について、基本的にはやっているです。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"もう少し現場を見ていただいて、きちんと配慮されているのかどうかという評価をしっかりしていただきたいと思うのです。それに対してのご意見を伺います。","respondent":"桑波田交通安全担当課長","answer":"その辺はまた新しい指定管理者に決まりましたら、そういったところもまたお話しして、よりサービス向上できるように進めてまいりたいと考えております。","id":"exchange-045"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"夜間とかそういったときに、平成２７年度でも構わないので、件数ですとか、それでどういったことがあったのか、わかる範囲で教えていただきたい。あれば、件数を説明を求めました。","respondent":"桑波田交通安全担当課長、安井土木管理課長","answer":"その防止のために、それ以外にも、防犯カメラの設置だとかといったことを各駐輪場のほうにやっているです。過去に、駐輪場の近くでちょっと火災等があって、そのときに出動したというのは、プレゼンのほうで聞いております。 警備会社はセコムを呼ぶような形です。","id":"exchange-046"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これはセコムが警備をするということだと思うのですけれども、その辺もわかっておられれば、そこを教えていただきたい。２４時間やっているということで、２４時間、もう少しその辺を詳しく教えてほしいと求めました。","respondent":"桑波田交通安全担当課長","answer":"その日にあったトラブルだとか、いろいろな事件等があったのは、報告をいただいているところです。そういったものの対応ということで、主な対応としては、今のところ実際にある対応ということで聞いているところです。","id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問","question":"１社だけというところで、やはり１社というのはおかしいというか、どういいものをつくっていくかということだと思うのです。この２３ある施設の中で、このシルバー人材の方を使われているのか、伺います。","respondent":"松代防災まちづくり部長、桑波田交通安全担当課長","answer":"いち早く、この自転車管理にコンピューターシステムというのを独自に取り組んで、それをさらに毎年グレードを高めてきたという実績がある。常に、またそういったことを含めて… 人員の関係ですけれども、場長を入れまして９１名の方が従事されております。そのうち、シルバーの方は３３名の方が、管理人として勤務しています。","id":"exchange-048"},{"speaker":"石田（ち）委員","kind":"質問","question":"１社に絞ろうとして１社にしているのですか、それとも何社かあっていいかなというふうな思いもあるのでしょうか、それを伺いたいと思います。この９１名の方の働く意欲にもつながっていく賃金というのはすごく大事だと思うのですけれども、その辺の把握はされているのか尋ねました。","respondent":"松代防災まちづくり部長、桑波田交通安全担当課長","answer":"いろいろと検討していただいて、また利用者が喜んでいただけるような提案をしてもらう業者を、ぜひ複数の業者から選びたい。こういう姿勢で臨んでいるところです。 シルバーの時給の関係ですけれども、こちらは区のほうでお願いしているわけではありませんので、指定管理者のほうでやっておりますので、それは企業とそちらのほうの契約となっておりますので、区のほうでは把握してはおりません。","id":"exchange-049"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"勝ち目ないなというふうに思われてしまったらどうにもならないと思いますので、そういった姿勢もぜひ見せていってほしいと求めました。やはり働く意欲につながらないと思いますので、その辺の把握を求めますけれども、いかがか尋ねました。","respondent":"桑波田交通安全担当課長、安井土木管理課長","answer":"公募につきましては、それぞれ段階を経まして実施しておりますので、とりあえず１社だけにこだわるということでは、全くございません。やはり企業と区との契約ではありませんので… その辺に不備がないのかどうかというのを、そちらのほうにお任せするということで、直接我々がその内容に関与するということは致しておりません。そういう形で担保されていると考えております。","id":"exchange-050"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり１社独占というのは、それにしてもやはり１社独占というのは、この指定管理にも合っていないのではないかなというふうに思います。こういった理由を含めて、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"}]},{"id":"topic-04","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"この委員会でこうした損害賠償についての専決処分の報告を受けるのですけれども、いろいろなご事情があるとは思うのですが、この再発防止策は具体的にどのような形で行っているのか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"年に２回ほど、安全確保のご協力、研修会を開催しているところです。基本的には１週間以内に、ケースとして学んでいただくということで、教訓を生かすために周知を図っているところです。","id":"exchange-052"}]},{"id":"topic-05","title":"区営住宅入居者募集","agenda":"区営住宅入居者募集","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"３人以上ということですけれども、募集の状況というのは単身者と比べてどうなのかというのを伺いたいのと、伺いたいのですが。","respondent":"今井住宅課長","answer":"平成２８年７月につきましては、１７戸に対して、大体３５倍の倍率という形になっております。は独立して一定の血族、今、こちらのほうの夫婦別姓という形でのお申込みというのは受け付けていない状況です。","id":"exchange-053"},{"speaker":"石田（ち）委員","kind":"質問","question":"税とかの状況が証明できればということだったのですけれども、住民票上は、未届の妻、未届の夫というふうになって、保育料とか保険料とかは合算して、世帯の収入として算定されるみたいなのですけれども、そういう場合は大丈夫ということですかね。","respondent":"今井住宅課長","answer":"は血族、または直系姻族が証明できること、そのいずれかが条件として必要になっております。先ほど申しました税法上の扶養関係が示されれば私どもも受付けいたしますけれども、それ以外のところでは、親族という形で確認しております。","id":"exchange-054"}]},{"id":"topic-06","title":"１の議案審査に戻りまして、残っておりました(6)第９４号議案 平成２８年度品川区一般会計補正予算（建設委員会所管分）","agenda":"１の議案審査に戻りまして、残っておりました(6)第９４号議案 平成２８年度品川区一般会計補正予算（建設委員会所管分）","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"要望も出ていたということもあって、この理由づけが、何となく唐突な感じがするのですね。それから２つ目が、これは早期に着手というこの意味が、どういう意味で早期着手に至っているのかということを説明を求めました。","respondent":"溝口公園課長","answer":"追加種目５種目ある中で、何ができるかというのを考えた中で、スケートボードということで選定をさせていただいたものです。そういったことが必要であると考えまして、今回、債務負担行為という形での補正予算を組ませていただいたものです。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問・要望","question":"もうちょっと、何となく、ちょっと分析がどこまでできているのか教えてほしいのですが。この追加、補正の財源のところなのですけれども、どこかリンクしているかどうかというところを教えてほしいのですが。","respondent":"溝口公園課長","answer":"これについては引き続き、来年度、補助金の要望等をしていく中で確保できるように努めていきたいというふうに考えているものです。そこをいかに多くの方が利用できる、引き続きよりよい施設になるように努めていきたいというふうに考えているものです。","id":"exchange-056"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"こちらからの要望もありましたし、区民からの声もありましたので、いい結果が出たなと。４カ所ぐらい置いていましたけれども、大体どのぐらいの人数が一度に使えるのかなというのがよくわからないので、想定はどのぐらいなのか尋ねました。","respondent":"溝口公園課長","answer":"多分、１０名とか１５名ぐらいが、やはり一番安全に使えるようなところになってくるのだと思います。楽しめるようにしていきたいというふうには考えておりますが、使いながら、進めていきたいというふうに考えているところです。","id":"exchange-057"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"駐車場も今度セットしてもらっていますけれども、やはり一番気になるのは、本当に混んだときに駐車場は大丈夫なのかなというのが心配です。となるようなことがないようにその辺、その辺の管理も十分注意してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"筒井委員","kind":"質問","question":"周辺の音の問題も出ましたけれども、利用時間は何時から何時までになっているのか尋ねました。","respondent":"溝口公園課長","answer":"今、実際、スケートボード場の運用につきましては、スポーツ推進課と最終的な協議をしていますが、今この八潮北公園にあります野球場・テニスコートと同じように、朝９時から夜９時までを今想定しているものです。","id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問","question":"あまり近隣にないと、近隣区のスケートボード場というものの整備状況というのは把握しているのかどうかということ。トリック台と言うのですか、こういうものを設置してほしいとか、そういうふうにして進めていくのか尋ねました。","respondent":"溝口公園課長","answer":"競技する、または自分の技量を磨いていく、そういったものになっています。どういった形でつくっていけばいいのかというのを検討していますし、改修しながら、よりいいものにしていきたいと考えているものです。","id":"exchange-060"},{"speaker":"塚本委員","kind":"確認","question":"一応、この債務負担行為の理由というところでは、工期が２カ年にわたり、分割契約が困難なためということで、こういうことは結構あるのでしょうか。こういうのは結構特殊な話なのか、よくある話なのかというところで、ちょっと確認をさせてください。","respondent":"溝口公園課長","answer":"４月から工事をするのではなく、そういった考えのもとに、２年にまたいで工事を進める。そういったふうに考えて、今回、補正予算という形で、議案を上げさせていただいたものです。","id":"exchange-061"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"南恵子議員の八潮のまちづくり、タイトルはちょっとあれですけれども、八潮の問題の件ですね。家賃助成をという質問があったのですけれども、要は子育て世帯の入居支援ということを求めたのですけれども、実施状況を聞きたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/862367?Template=document&Id=4188#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":60798,"voices":210}},{"id":"h28-20161128-9","meetingId":"h28-cm11","date":"2016年11月28日","dateIso":"2016-11-28","committee":"文教委員会","time":"午前１０時００分～午後 ２時４７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を93件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"すみません、制度の確認なのですけれども、これについては医療費というのはどういう扱いになるのでしょうか。将来的に養子縁組を前提としない養育家庭についての医療費の扱いはどうなっていますか。","respondent":"廣田子ども家庭支援課長","answer":"規則で定められているのですが、その方については児童相談所で発行する都の医療制度に全てのるものとなっておりますので、区の医療制度からは外れるです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"時代的な背景とか、国でどんな議論がされていたのか、わかる範囲で教えていただきたいのが１点です。文言のところで、「６条の４第１項」を「６条の４」に改めるという、この中身自体の説明をしてください。","respondent":"廣田子ども家庭支援課長","answer":"法改正の里親の部分の変更の趣旨につきましては、里親支援の一貫した業務について、都道府県の業務として法の中で位置づけたということです。今までは６条の４の第１項の中で、６条の４全部で語られている里親について、６条の４を全部引用しに行くというものです。","id":"exchange-002"}]},{"id":"topic-02","title":"第１００号議案 品川区立保育所条例の一部を改正する条例","agenda":"第１００号議案 品川区立保育所条例の一部を改正する条例","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"ここについてはいろいろ伺っておりますけれども、暫定５年間で決まりということで、５年で閉園ということなのでしたか。現状でのお考えを確認させてください。","respondent":"佐藤保育施設調整担当課長","answer":"保育園の開設期間なのですが、品川駅南地域の再開発の状況で、１年ずつどうしていくかというのを見極めていきたいと考えております。現時点では、５年間は保育園として利用するということは決まっております。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問","question":"その場合の、これからまだ１年延びますというような判断というのは、いつごろにされるものなのでしょうか。いつごろの判断にしていくのか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"再開発の状況にもよると思うのですけれども、関連部署と連携を密にして、できるだけ早い段階で情報を受けまして、速やかに混乱がないように、事前に申請者の方にお伝えしたいと思います。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今のとも関連して何点かお伺いしたいのですけれども、１年ずつの判断ということなのですが、不都合があったらまた契約の解除があり得るのかどうか。","respondent":"佐藤保育施設調整担当課長","answer":"履行されないようなことがないように、定期的に事業者と連携をとりながら、保育園の運営をしていきたいと考えております。その確認は当然いたしますし、月に一度は保育園長会等を実施しますし、随時連携をとるような打ち合わせも行いますので。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どういうところが改善されているのか、重点なのかということで、当然やはりここのところは委員会が知るべきことだと思うのです。本来だったら項目を挙げて、こういうところをチェックしていきますというのが出されるべきであると思っているのですが、そこはいかがか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"２点目の中身の調査ですが、指導監査については子ども・子育て支援法の施行により、適宜都と連携して立ち入り検査を行う権限は持っております。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"民設民営の保育園よりも、区の権限が強いので、都のところのかかわりがほかの民設民営よりも区立の民営化だと薄いような印象を私は受けているのです。この点、とても重要であると思うのですが、いかがか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"人件費比率、運営役員等の構成等も確認して、やっていきたいと思っています。今現在も確認はしておるのですが、そういった中身も今まで以上によりきめ細かく適切に状況を確認していきたいと考えております。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味で、ぜひ公設民営でやっていく。報告をぜひしてほしいと求めましたが、最後ですが、お伺いします。","respondent":"佐藤保育施設調整担当課長","answer":"委託する金額の項目ごとに、その辺にどういったものを歳出しているかという報告書を出すように委託書に盛り込む予定です。その辺で全ての支出が明らかになるといいますか、そういった報告書を求めて調整を進めております。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面でどこまで議会に報告できるのかというところは、ぜひ今後の課題として検討してほしいと求めました。これはお願いをいたしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"高橋（し）委員","kind":"確認","question":"すみません、確認なのですけれども、５年で契約をしていて、１年１年協定を結んで更新していくという理解でよろしいでしょうか。そこら辺を確認したい。","respondent":"佐藤保育施設調整担当課長","answer":"契約は１年１年の委託契約になるのですけれども、基本協定というのを結んでいまして、５年間施設の運営をお願いしますということで、細かい項目等が書いてあるのですけれども、そういう形で行っております。","id":"exchange-010"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、５年というところが基本協定の中に入っているということの理解でよろしいか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"５年というのは基本協定の中に入っております。","id":"exchange-011"},{"speaker":"あべ委員","kind":"確認","question":"先ほどのやりとりで一応確認したいのですけれども、こちらの事業者、人件費の比率というのはどの程度になっているのか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"既存の運営をしている園に関しては、５０％から６０％の間と聞いております。公設民営ですので、施設整備費がかからない関係もありますので、７割以上は人件費比率に割きたいというふうに業者から確認をとっています。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問・要望","question":"新設のときにこれはお伺いすれば数字が出てくるので、秘密にしなければいけないということではないと思っています。もちろん行政にとっても大きな目安になると考えていますので、ぜひその方向もお考えいただきたいと思うのですが、いかがか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"公設民営保育園に係る人件費比率のご紹介、お知らせについては検討させていただきたいと思います。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"求めてきた問題ですので、本条例が通れば、新たに６０名の定員拡大となります。そして、１年ごとの契約ということなので、ぜひ委託は１年でやめて直営にすることを強く求めて、賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"あべ委員","kind":"意見","question":"そこについてはぜひ努力をしていただいた上で、運営そのものについては、本議案については賛成しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"賛成です。先ほどほかの委員からもありましたけれども、夢工房の形にならないようにぜひチェックを充実させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"人事委員会勧告に基づくものですので、この所定の内容については異論はないのですが、何点かお伺いしたいと思います。給与以外の、例えば、研修などに係るところというのはどういうことになっているのか説明を求めました。","respondent":"熊谷指導課長","answer":"区費負担の学校教育職員の給与制度につきましては、東京都の教育職員との均衡を考慮して改定等を行うことが適当であるという記載があります。２点目の研修につきましては、都の教職員と同様の研修の機会があります。","id":"exchange-017"},{"speaker":"あべ委員","kind":"質問・要望","question":"同じ考え方で、研修も、もちろん都費の方と同じ研修はぜひ受けていただきたいのですけれども、せっかくずっと区にいてくださるわけです。例えば、固有教員は都費の教員よりおもしろそうだと思う応募者を増やすことにもなるのではないかと思うのですけれども、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"ですので、現在のところでは、それに基づいて行っていきたいと考えています。現在もオークランドへの派遣等も行ったりもしておりますけれども、また改めて今後の研修については改善を図ってまいりたいと思います。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"第１１４号議案なのですが、前に伺ったのですが、議案書を１ページめくって、１級から２級、３級、４級とありますが、どういう立場の方に該当する級なのかを教えていただきたいのと、あと、中程のページに「再任用職員以外の職員」という欄があるので、これは一体何なのか説明をしてください。","respondent":"熊谷指導課長","answer":"１級が教諭、それから主任教諭、それから副園長級、それから４級で園長級ということで、上がっていっているところであります。それから、再任用以外といいますのは、これはそのとおり、一般の教職員のことを再任用以外という言い方をしております。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"初任給というか、学校を出たばかりの方というのはどこに位置をするのか。給料が一番上がってどのぐらいまで行っているのか教えていただきたいのと、どうしてこうやって変わってくるのか、もとのところを説明を求めました。","respondent":"熊谷指導課長","answer":"実際に影響で増えている額なのですけれども、非常に若い方に関しては３万３,６９１円、これが今回の改定に伴って上がってくる額です。初任給につきましては……。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"特別区の人勧と東京都の人勧の内容で、大もとのところが何で違ってくるのか、大もとのところをお伺いします。","respondent":"熊谷指導課長","answer":"特別区では特別区管内の事業所ですけれども、東京都では多摩地区の事業所もその調査対象となっておりますので、差が出ているところです。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"制度の話になってしまうのかもしれませんが、今回、学校教育職員のほうが０.０２％差で、極めて小さいということで、アップはされないということですけれども、これは今度また差が出たときに、この分というのは積み上がっていくのか、それともまた一からということになるのか、伺いたいと思います。","respondent":"熊谷指導課長","answer":"それにつきましては、そのときの格差ということになりますので、積み上がるということではございません。","id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"質問","question":"歳出額のほうがもしわかれば、全部でどれぐらいになるのか。賃金が上がるわけですので、全体として対象となる先生方が何人いて、幾ら上がって、全体の歳出は幾らになるのかということを教えて下さい。","respondent":"熊谷指導課長","answer":"７１万９,１１４円です。合わせまして、２４３万７,４５２円ということになっております。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問","question":"一言だけ。東京都と都労連の協議にて妥結をしたと伺ったので、労使協議を尊重して、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-03","title":"第９４号議案 平成２８年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第９４号議案 平成２８年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"鈴木（博）委員","kind":"意見","question":"１枚目のほうなのですけれども、よくわからないのですが、新の都制度で、平成２４年４月１日以降の新規開設園が対象だということで、開設後５年間と書いてあるということは、平成２４年４月に開設した場合は、平成２９年までしか補助が受けられないのかとの意見を述べました。","respondent":"竹田保育課長","answer":"委員ご指摘のとおり、平成２４年から５年間ですので、残存期間のみとなります。","id":"exchange-025"},{"speaker":"あべ委員","kind":"質問","question":"制度が変わることによって、この仕組みでいくと逆に負担が増える事業者もあるのでしょうか。どういう感じなのか、把握されていますか尋ねました。","respondent":"竹田保育課長","answer":"今回、助成するのは、全て都の新制度を利用したものとなる予定です。区の負担、歳出額が８,１００万円、区の単独補助で行った場合が１,５００万円ということになっております。","id":"exchange-026"},{"speaker":"あべ委員","kind":"質問","question":"すみません、やはりよくわからなかった。８分の６も足した８分の７で、区からは８,１００万円出すけれども、そのうちの８分の６の分は都からお金が来ていると考えていいのか尋ねました。","respondent":"竹田保育課長","answer":"委員おっしゃるとおり、区の単独補助の場合には区が全額補助しておりまして、こちらが約１,５００万円、それから、都の新制度の約８,１００万円は、これは都の補助を含む８分の７の金額です。","id":"exchange-027"},{"speaker":"あべ委員","kind":"質問","question":"ということは、新制度のほうは都から受け取った分を差し引いた１,０００万円ちょっとが、純粋なる区の負担分と考えていいのか尋ねました。","respondent":"竹田保育課長","answer":"おっしゃるとおりです。区が支出する８分の７のほうが８,１００万円で、従来の制度の単独補助が１,５００万円なので、その差額が……。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、期間が今月１１月から平成３３年３月末までとなっているのですが、この期間になっている理由を教えてほしいと求めました。月額８万２,０００円の中で、本当に積み上がってしまうということになるのか、伺いたいと思います。","respondent":"竹田保育課長","answer":"ですので、来年４月の新規採用に効果が出るようにということで、礼金を別枠にしたものだと考えております。月額８万２,０００円が上限ですので、管理費等が対象となりますので、前月分というのは翌月に積み上がるということはございません。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"８万２,０００円よりも、更新料が発生したときに８万２,０００円の上限に達してしまうということになるのか、伺いたいと思います。４年半ぐらいになっていくというところで、どうしてそうなったのかというところを聞いたので、都から聞いていれば教えてほしいと求めました。","respondent":"竹田保育課長","answer":"更新料等を足した金額で８万２,０００円までを上限とするですので、月によって変動があったとしても、上限は８万２,０００円です。当面、こちらの期間ということで打ち出されたものですので、今後の動向を見て決めていくものだと考えております。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"更新料が発生するときも８万２,０００円で上限だということなので、更新料のほうも別枠にしていただけないかというところで、都に求めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"質問","question":"個人が契約した場合に、そこに補助してもらえるということではなくて、あくまで事業者が用意したところに入らない限りだめということなのですか。だから、例えば７年目の方が今どこかに住んでいて、自分で借りている場合は、この支援を受けられないという解釈でよろしいか尋ねました。","respondent":"竹田保育課長","answer":"既に個人で住んでいらっしゃって契約されている部分については、契約変更によって事業者が借り上げたものというふうに契約を変更すれば、引き続き同じ場所で居住することが可能な制度です。","id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、契約を変更しなければいけないということですね。そういった使い勝手がいいように都のほうに言っていただけると、少し改善していただけるといいと思うのですが、その辺はいかがか尋ねました。","respondent":"竹田保育課長","answer":"現在のスキームですと、保育士が何人利用していても、事業者に一括して該当金額を振り込むという形になります。それぞれの保育士に振り込むような形になろうかと思いますので、その辺はなかなか対象人数が増えてくると難しいかと考えております。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それが１つと、１つの建物で、１カ所で１人というのでも可能なのかどうか。その点も教えていただきたいのと、額を教えていただきたいのと、その金額がどう動くのかも説明を求めました。","respondent":"竹田保育課長","answer":"それから、お一人が１つの建物の中にいることでばらばらに点在するのかということなのですが、そういう状況が生まれると思います。従来の区の制度ですと、最高が月額で６７万円ほど、最低は自社ビルですと０円等があります。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"意見","question":"すみません、新制度、下の制度になったときにこれがどういうふうになるのか、わかったらとの意見を述べました。","respondent":"竹田保育課長","answer":"すみません、正確な金額は今ご用意していませんので、お答えできかねます。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問","question":"では、わかった時点で教えていだたきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"あべ委員","kind":"確認","question":"拡充分での今、人数を出していただいているのですけれども、今、受けている方と合わせると、何園で何人の方が補助の対象になるのでしょうか。家族でも利用できる制度だったかということを確認したいのと、事業者が給与天引きとかいう形で保育士から家賃を徴収することは可能な制度なのか尋ねました。","respondent":"竹田保育課長","answer":"それから、事業者が家賃を徴収することについても、特段定めがございませんので、可能かと思います。それから、現在の人数ですが、認可保育園ですと利用した人数が３９人、地域型が２２人、認証が１８人、昨年度ですが、以上のようになっております。","id":"exchange-037"},{"speaker":"あべ委員","kind":"確認","question":"８万円のところに前から自分で住んでいる人がいると、その人は８万円払い続けて、そういう形になるのでしょうか。要は、事業者の負担分を超えて、事業者が保育士から家賃を家賃分として取ることも制度上可能ということなのか尋ねました。","respondent":"竹田保育課長","answer":"更新時期しか利用できないのかということですが、そういった要綱上の規定はございませんので、更新以外の時期も利用できます。オーナーの考え方によっては、敷金等を求める方もいらっしゃるかもしれませんので、そういった場合はなかなか難しいのかと考えております。","id":"exchange-038"},{"speaker":"あべ委員","kind":"質問・要望","question":"事業者としてもどう考えるかというのは、いろいろ想像するところですので、ぜひ把握してほしいと求めました。あるいは要望を受けているかどうかということと、把握してほしいと求めましたが、いかがか尋ねました。","respondent":"竹田保育課長","answer":"実質的な負担についても、同様です。よりよい、使いやすい制度になるように、制度の趣旨が活かせるように今後検討してまいりたいと考えております。","id":"exchange-039"},{"speaker":"新妻委員","kind":"質問・要望","question":"今の質問にかぶるかもしれませんが、各園の中で職員の皆さんにどう説明がされていて、要望の声というのはすぐに出てくるかと思うのです。こうしていきましょうとか、何かそういう具体的なところというのは、話が出ている園というのはあるのか尋ねました。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"今回、資料に記載してあります１１園１８人に関しては、各事業者に調査をした結果、こういう要望があるという数字です。具体的に、各事業者がどのように説明しているかというのは… 税金を充てていろいろな対応をしているのですけれども、先ほど私の説明、これはないように必ずします。","id":"exchange-040"},{"speaker":"沢田副委員長","kind":"確認","question":"先ほど高橋しんじ委員の質問の中で、確認したいのですけれども、どういった形でお金を出されているのか。直接１年間分出すのか、どういった形で出されているのか。","respondent":"竹田保育課長","answer":"公定価格については、毎月月額で計算して支給しております。区の単独補助の分につきましては、物によっては年２回で支給しているものもあります。","id":"exchange-041"},{"speaker":"沢田副委員長","kind":"質問","question":"区が単独でやられているのは、給与の上乗せ分というのは、事業者にはどういう形で出されているのでしょうか。それが半年ということか尋ねました。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"区の単独補助の分については、物によって毎月のものもございまして、年２回のものもあります。宿舎借り上げについては、年２回という形でやっております。 年に２回、いついつどの期間かを確認してお支払いをしておりますので、家賃自体は後払いになります。実績払いとなりますので、実績報告書というのをもらっています。","id":"exchange-042"},{"speaker":"沢田副委員長","kind":"質問","question":"物によっては半月だったりとか１カ月ごとに、物によって何カ月ごとに１回だったり、毎月ごとというのは違っていても問題ないということか尋ねました。","respondent":"齋藤子ども未来部長","answer":"保育課長がさらっと言ってしまったというか、わかりにくかったのですけれども、公定価格というと、保育園の運営費になります。特別支援の加算を何人とかというと、基本的に運営費についてはお渡しできておりますので、運営については支障はないかと考えています。","id":"exchange-043"},{"speaker":"あべ委員","kind":"質問・要望","question":"賛成ですが、宿舎借り上げについては、いろいろと運用にある程度目を光らせたほうがいい面もあるのではないかと。これはいろいろできそうな仕組みである以上、ぜひ調べながらの運用にしていただきたいということを踏まえて、賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"賛成ですけれども、今、あべ委員がおっしゃったのですけれども、そういった課題の点をクリアしながら、使い勝手といいますか、保育士たちがぜひこの支援を使えるように、スキームが区のものではないとすると、先ほどもお話ししたのですけれども、保育士たちの声を聞いていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２番の方というのは、返還済額というのは０で、３８万２０００円が訴訟の金額で、確定違約金という１万７,１００円というのが、これが払うことになっている金額だと考えてよろしいのか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"２番の方につきましては、提訴になった場合については判決として出てしまうので、ここまではお支払いいただくということで和解が成立しています。","id":"exchange-046"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、２番の方というのは、実際、この人が支払う金額というのは、１万７,１００円だということになるのか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"訴額になっている元本の残り３８万２,０００円と確定違約金の１万７,１００円で、合わせて３９万９,１００円が分納する金額となります。","id":"exchange-047"},{"speaker":"あべ委員","kind":"質問","question":"違約金の額なのですけれども、これ、今後の分割での返還に対して遅れたらということで理解してよろしいでしょうか。１０％とか１０.９５％とか、人によって若干の違いがあるのですが、これは何か根拠があっての利率というのか、割合なのか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"２カ月以上滞納せずに払っていただければ、それ以後についてはいただかないということができます。率については条例から規則に途中から変わってしまっているのですが、この方々が借り受けしたときの条文に沿った形の率になっています。","id":"exchange-048"},{"speaker":"あべ委員","kind":"質問","question":"それとも、和解内容がそうなってしまったら、何が起きてもこのとおりで、１０％というのが適用されていくということなのでしょうか。どのようにお考えか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"１番の方のように、文書で対応が触れられるので、連絡を途切らさないようなアプローチをしていこうと思っています。そういうことではなくて、払える状況になくなった場合については、そのときにまた相談に乗るということは可能かと思います。","id":"exchange-049"},{"speaker":"新妻委員","kind":"質問","question":"まだこういう払っていない人がいて、訴訟までしなければいけないというような方がいらっしゃるのか、教えていただけますか。","respondent":"廣田子ども家庭支援課長","answer":"７０件というふうに委任していたものが、平成２７年度で３３件の委任でしたが、委任する案件はかなり減ってきております。数が減ってくれば比較的一件一件丁寧にできるので、提訴まで行かないという可能性は高くなってきておりますが、全くいないとまでは現時点では……。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問","question":"なるべく早い時点で困っている様子を相談できたり、いろいろな手立てがあることを知らせていけば、もっと裁判にならなくて済むのではないか。いろいろご努力されているのはわかるのですけれども、早期に区が対応できるような方法はないのかといつも思っているのですが、いかがか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"だんだん扱う件数が少なくなってきていますので、さらにきめ細かくというところでは努力していこうと思っているところです。この５件に関してはみんな提訴になってしまったけれども、提訴した結果、早目に対処していくということは努力していこうと思ってあります。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問","question":"何回も伺っているのでわかっていますけれども、ぜひ話し合いに来てほしいというところの思いが伝わっていくようにしてほしいと思います。前に委託に出しているような話も聞いたのですが、訪問はどなたがされているのか、説明を求めました。","respondent":"廣田子ども家庭支援課長","answer":"訪問につきましては、品川区内と近隣につきましては、シルバー人材センターに委託をしておりまして、かつてＮＨＫの受信料を徴収した経験がある方にお願いしていて、自分では振込みがなかなか難しい方を集金してくれたりとかというところで、訪問していただいているところです。","id":"exchange-052"}]},{"id":"topic-04","title":"平成２８年度請願第１４号 品川区私立幼稚園児保護者負担教育費軽減の為の請願","agenda":"平成２８年度請願第１４号 品川区私立幼稚園児保護者負担教育費軽減の為の請願","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"保護者補助金についてお伺いしたいと思います。対象割合というのは広がっているのか尋ねました。","respondent":"竹田保育課長","answer":"対象割合は、緩和するごとに拡大しています。平成２４年度には６５％、平成２６年度には７０％、平成２８年度予算では８０％まで拡大してきたところです。","id":"exchange-053"},{"speaker":"あべ委員","kind":"質問","question":"補助金の所得制限の意味といいますか、どういうところからこの数字をはじき出していらっしゃるのかを教えてください。根拠といいますか、考え方を教えてほしいと求めました。","respondent":"竹田保育課長","answer":"所得割額から推定年収というのも勘案しまして拡大しています。ちなみに、現在の８０％は年収約１,３００万円までの方が対象となっているというところで、推定年収をにらみながら決めているところです。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問","question":"それから格差が拡大しているというところで、導入されたのはいつで、なぜ導入されたのか伺いたいと思います。そして、先ほど入園補助金を１,２００人ぐらい受けていらっしゃるというところで、ほかに要件とかがあるということなのか尋ねました。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"所得制限が導入されたのが平成８年度と聞いております。制限なく申請者の方々全てに補助をしていますが、場合によっては、対象者全員の方が申請していないという現実もあろうかと思います。 入園補助金は、入園した年だけもらうので少ないということでございまして、ほかは４歳児、５歳児もいるので、数が減ってしまうのはそういうことです。いわゆる入園料ということになります。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１点目は、やはり生活の中で重く位置をしていると思うのですが、教育費の負担増に対しての認識をお伺いしたいのが１点です。こういった考えでは、なくしていく方向で考えていらっしゃるのか、あと、２割を今後どうしていくのかという考えを聞かせてほしいと求めました。","respondent":"竹田保育課長","answer":"現状の８０％というところですが、今後につきましては、状況を見ながら決めていきたいと考えております。今は幼稚園のことについて申し上げますけれども、それぞれ所得割合に応じて、適切な補助ができていると考えております。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は、子育て支援の水準がＯＥＣＤ３カ国の中で最低だというデータがしょっちゅう出ているわけなのですけれども、その辺をお伺いしたいと思います。ぜひ進めていただきたいと思うのと、なくしてほしいと思っているのですが、いかがか尋ねました。","respondent":"竹田保育課長","answer":"さらに区の補助とを加味して、３者を合わせたもので補助しているものですので、３者の合計額は適切に補助されていると考えております。それから、今後の所得制限の考えですが、物価上昇等、社会情勢を見ながら判断していきたいと考えております。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"自治体が支援できるのかということにおいて、ぜひ困難を抱えている方への手立てをとってほしいと求めましたが、いかがでしょうか。その辺が進んでいるのか、ぜひここの支援は大事であると思っているのですが、いかがか尋ねました。","respondent":"齋藤子ども未来部長、竹田保育課長","answer":"今回、お話しさせてもらったとおり、モデル世帯で世帯年収１,３００万円までの方をカバーしているというこの現実は大変大きいものだと考えています。過大な支援になってしまうと、これは議員の皆様からも十分ご議論を頂戴しながら… 預かり保育の件ですが、こちらが補助しているものの園数ですが、平成２５年度は７園でしたが、平成２８年度は８園に増えてあります。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"意見","question":"自治体で手厚くしているという、やはりこれが子育てを社会で支えていく基本だと思うのです。私はぜひこういう姿勢に立ったら、子どもにかかわる費用、所得制限は要らないと強く思っておりますので、意見として述べておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"あべ委員","kind":"質問・要望","question":"数字を確認させていただきたいのですけれども、園によってばらつきはあるとは思うのですが、どのくらいの金額になっているのか。預かり保育を使っている方々の割合が分かれば、教えて下さい。","respondent":"竹田保育課長","answer":"所得に応じて異なりますが、ちなみに非課税世帯ですと、区の加算も入れた補助金額が年間４３万２００円となっております。申しわけございません。","id":"exchange-060"},{"speaker":"あべ委員","kind":"質問","question":"すみません、区立幼稚園の年間支払い額は、この委員会で分からないものなのですか。多分、そんなに難しい質問ではないと思いますので、説明を求めました。","respondent":"齋藤子ども未来部長","answer":"ご質問の趣旨は、おっしゃっていたのは年間の私立幼稚園の公費負担という意味ですか。","id":"exchange-061"},{"speaker":"あべ委員","kind":"質問","question":"それと、公立の年間の保護者負担額というのは、多分、わかると思うので、教えてほしいと求めました。これはそんなに複雑なものではないと思いますので。","respondent":"竹田保育課長","answer":"私立の最も低い負担額ということですが、１,３００万円以上の所得等については、１５万４,０００円となっております。最も高い方が１万２,０００円になっておりますので、１万２,０００円掛ける１２カ月で、１４万４,０００円となっております。","id":"exchange-062"},{"speaker":"あべ委員","kind":"質問","question":"あるいは、やはり今の制度ではしんどいという方も多いのではないかと感じているのですが、区としての認識はいかがでしょうか。これでもう十分と感じていらっしゃるのか尋ねました。","respondent":"竹田保育課長","answer":"年々拡大してきて、現在、１,３００万円の年収の方、おおむね全体の８割までカバーしているところでございまして、今後につきましては、保育料の推移等をしっかり調査しながら決めていきたいと考えております。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"意見","question":"毎年この請願が出されているということをやはり重く受けとめていかなければいけないと思っています。所得制限はなくしていくべきであると考えていますので、賛成で採択を主張いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"}]},{"id":"topic-05","title":"平成２８年請願第１７号 一人ひとりの子どもが大切にされる品川区を求める請願","agenda":"平成２８年請願第１７号 一人ひとりの子どもが大切にされる品川区を求める請願","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"荏原地区が１.２８m2で、それはわかるかどうかわからないのですけれども、児童１人当たりの児童遊園の面積とかというのはわかるでしょうか。そして、今、園庭のない保育園というのは、何園あるか伺いたいと思います。","respondent":"溝口公園課長、大澤待機児童対策担当課長","answer":"特に荏原地域におきましては、木造密集地域の解消、そういったものをあわせながら、防災広場という形ですが、整備を着実に進めてきているところです。今後につきましても… 園庭のない保育園についてのお尋ねですけれども、園庭が全くないという園は２５園あります。園庭はあるけれども、既定の面積が足りずに、公園等とあわせて確保しているという園が３３園です。","id":"exchange-065"},{"speaker":"のだて委員","kind":"質問","question":"そういった中で、実際にこういった運動能力の発達というのも確保できているのでしょうか。伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"体操ですとか、ダンスですとか、取り入れて活動している園が多うあります。平成２９年開設の園も、当初の予定よりも定員を１０名減らして、それぞれ工夫をしていただいているところです。","id":"exchange-066"},{"speaker":"のだて委員","kind":"質問","question":"室内では、体操とかダンスなどできるようにしているということですけれども、やはり外で元気いっぱい遊ぶということは、それとはまた１つ違うものがあると思うのですけれども、その違いについて、どういった認識なのか伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"もちろん広い場所があればそれに越したことはありませんけれども、そういうことはございませんので、それは園の中でいろいろ工夫してやっていただいているところです。","id":"exchange-067"},{"speaker":"のだて委員","kind":"質問・要望","question":"園の中でもやっているということですけれども、やはり外で元気よく走り回るということも、相当子どもの体の成長、発達に寄与することだと思いますので、ぜひ整備に向けて進めていってほしいと求めましたけれども、改めて伺いたいと思います。","respondent":"溝口公園課長","answer":"都市部の中でなかなか公園用地を確保していくというのが難しい状況にあります。引き続き公園につきましては、安全に安心して誰もがご利用いただけるような公園を目指して、整備に取り組んでいきたいと考えているものです。","id":"exchange-068"},{"speaker":"のだて委員","kind":"質問・要望","question":"品川区では、いろいろ公有地など、あると思います。ぜひ進めて、積極的に、子どもが遊べるような公園を増やしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"あべ委員","kind":"質問・要望","question":"しかもそれが１日２日ではなくて、そういう運営面での外遊びというのは、区はどこまで把握していらっしゃるのでしょうか。もちろんぶつからない時間帯にですけれども、活用するということは行われているのかどうか、教えてほしいと求めました。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"お散歩をしていない園ということですが、各保育園には、年度当初に事業計画、運営方針を出していただいております。夏休みは、近くのプール等もお借りするようなこともありますが、園庭については、今後、検討していきたいと考えていま… 月に１回お邪魔して、あいているときはどうぞという言い方もなかなか難しいですけれども、うちの保育園で使わせていただくということもあります。","id":"exchange-070"},{"speaker":"あべ委員","kind":"質問・要望","question":"ですので、どうなのでしょうか。実際のところ、改築等を除いたところでの運営費の差というのは、公立と民間と同規模であると、大体何対何ぐらいの割合になっているのか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"公営の保育園と民設民営の保育園の運営費なのですけれども、８月の文教委員会でもご説明させていただいたのですが、１００名定員規模で大体どちらも１億７,０００万円ずつということで、大体１対１、同じ金額です。","id":"exchange-071"},{"speaker":"あべ委員","kind":"質問・要望","question":"公立認可園の質というのも、私はある程度チェックといったらいいのですか、強めていかなければいけないのではないかと感じております。基準というか、そういったものというのは、改めて他の私立と比べながらでも見る機会というのはあるのか尋ねました。","respondent":"竹田保育課長","answer":"定期的に巡回したり、新人保育士には公開保育という場を設けまして、大勢で保育内容をチェックするなどの取り組みをしております。今後も、保育の質をしっかり今まで以上に向上できるように、そういった研修を充実させていきたいと考えております。","id":"exchange-072"},{"speaker":"あべ委員","kind":"意見","question":"その辺は区としては大分公立認可園の体制が変わってくる中で、危機感といったら何ですけれども、ちょっと以前と違うと感じるところはありますかとの意見を述べました。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"今まで培ってきたノウハウが、新しく入ってきた者たちに確実に受け継がれるように、引き継がれるように考えているところです。特段、大きく変わったというところは、認識してございません。 自分もうちへ持って帰って子どもにやらなければいけないのを、親としての対応は果たさないで、行政に求めるというのはやはりあります。２０年と、国家百年の教育の大計で考えていくと、保育士にも指導していきたいと考えています。","id":"exchange-073"},{"speaker":"あべ委員","kind":"質問・要望","question":"逆に親の側でも求めるし、保育士の側でも求めるけれども、ぜひそこから入らないでいただきたいと。多分、そこはまずは一緒にやって、子どもを育てていくというところからスタートするようなご発言から入っていかれてほしいと。","respondent":"齋藤子ども未来部長","answer":"プラス、集団保育ですので、自分の子だけ特別にしてほしいと言われてもなかなか難しいのだという意識も持っていただける。ぜひとも取り組んでいきたいと考えています。","id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問・要望","question":"９割の保護者の皆さんが認可保育園を求めていますという数字が出ていたので、この辺も受けとめながら、ぜひ聞かせてほしいと求めました。ちょっとでも大きい子が来ると、０歳から１歳、２歳の小さい子どもたちが近くで安心して遊べる公園が圧倒的に足りないという認識があるのか尋ねました。","respondent":"大澤待機児童対策担当課長、溝口公園課長","answer":"２点目ですけれども、先ほども申し上げたとおり、認可保育園の開設を中心に待機児童対策は進めてまいりたいと思います。利用者８００人中、直接認証だけをご希望される方々というのは５００人ほどいらっしゃいますので… これまでも長年にわたり、極端に言いますと、昭和４６年頃から比べると公園数自体は４倍に増えている。","id":"exchange-075"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひご努力をしていただきたいというのと、私は認証保育園の園長先生にお伺いしたのですけれども、わからないでしょうか。では、とりあえず公園のところはそこまでにしておきます。","respondent":"溝口公園課長","answer":"さまざまな取り組みをしていく、遊具を改修することによって、さらに利用者が増えるとかそういったところもあります。そういった取り組みをしていく中で、しっかり安全で快適な皆様のご利用が確保できるように、そういったものに努めていきたいと考えているところです。","id":"exchange-076"},{"speaker":"新妻委員","kind":"質問","question":"すみません、公園課長、公園の件で１点だけお伺いしたいのですが、今後のまちづくりの中で公園づくりを進めていくというご答弁ですが、今、具体的に検討されている公園ですとか、こういうところができる予定なのだというのが具体的にありましたらお答えいただけますか尋ねました。","respondent":"溝口公園課長","answer":"今年度もそうなのですけれども、木造密集地域、荏原地域において、２園ほど防災広場を整備していく予定にしております。公園という形ではありませんけれども、地域の方々が利用できるオープンスペースができていく、そういったふうに考えているものです。","id":"exchange-077"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大丈夫ですか。その辺をお聞きしたいのと、これの対策をしていかなければいけないと思っていますが、いかがか尋ねました。","respondent":"大澤待機児童対策担当課長、佐藤保育施設調整担当課長","answer":"保護者の方のニーズが、認可保育園に一番多いということは認識していますので、認可保育園の開設を中心に今後も進めてまいります。来年度より１年に一度は必ず指導検査に入るということで、それに合わせまして… 築５０年を超えているのが５園、４５年を超えている園が１５園ございまして、老朽化は喫緊の課題だと考えております。","id":"exchange-078"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本当に認可保育園で考えていただきたいし、質問でもいたしましたけれども、どれだけ認可をしていけるだけの支援をしていくのかということ。保育園をつくることの効果をしっかりと見据えて、先を見通して支援をしていくことが大事であると思いますが、これはいかがか尋ねました。","respondent":"大澤待機児童対策担当課長、齋藤子ども未来部長","answer":"新規開設に当たりましては、良質な保育をしていただける事業者にできるだけ品川区に来ていただけるように、私どもも努力してまいります。新規開設の事業者に対して… １.５倍ぐらいに増えていまして、今度は８,８３４人とニーズに合わせる形で私どもは保育園の開設を進めてきているところです。","id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひこれからも頑張ってほしいのですが、国にも求めていますとよく回答をいただくのですが、やはり国のところの責任もしっかりと求めていきながら。この根拠をしっかりと今日はお伺いしたいと思っているのですが、１１月頭の集計でどれだけになっているのかというところと、いかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"申し込み、４００人ぐらい増えるのではないかと見込んでいたところですが、１１月の数を見て思っているところです。新規の定員拡大が４９２人、絶対にということではないですけれども、限りなくゼロに近くなるのではないかというふうに見込んでおります。","id":"exchange-080"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味でぜひ願いをかなえてほしいと求めました。意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"ただし、認可外の保育園の整備も並行してやってほしいという希望と要望を出しておりまして、これに関しては若干意見が違うと思っているわけです。２番目の、しっかりとそのままやってくださいというのが我々の見解なので、若干ニュアンスが違うと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"新妻委員","kind":"質問・要望","question":"これを進めていただく中で、一般の利用者に対しても公園等の整備は必要でありますので、これはぜひ進めていただきたいという要望もします。会派といたしましては、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"飯沼委員","kind":"質問・要望","question":"国に求めているというところですけれども、インフラの整備を行っていくこと、これも当然であると思っています。以上、賛成で採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"あべ委員","kind":"質問・要望","question":"３番、ここは私たちの意見と少し違うところなのですけれども、先ほども申し上げたように、民間が行うことが私は悪いとは思っておりません。というところから、特に３番の民間委託に反対というところがひっかかるところもありまして、私どもとしては不採択としたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"一般質問でもさせていただいたのですが、そういったことも含めて、待機児童の対策を全庁挙げてという体制づくりを要望していきたいと思います。こちらの請願の項目については、それらの意見から、願意に添いがたいということで、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"}]},{"id":"topic-06","title":"その他の(1)委員長報告","agenda":"その他の(1)委員長報告","exchanges":[{"speaker":"のだて委員","kind":"提案","question":"質問１のところで謝罪について伺ったのですけれども、何についての謝罪なのか、はっきりと答弁ほしいと求めました。質問６番目の、改善策の提案とか、提出しない理由を伺いたいと思いますとの意見を述べました。","respondent":"齋藤子ども未来部長","answer":"再度事業者を変更しなくてはいけない、それについて謝罪したと認識しておりますが、それを繰り返して説明してよろしいのですか。これしか言えませんけれども。","id":"exchange-087"},{"speaker":"飯沼委員","kind":"質問","question":"質問２のところで、待機児童が解消しない理由を伺ったら、もう一回その辺をお伺いしたい。","respondent":"齋藤子ども未来部長","answer":"お母さん、どういう点で待機児童が解消されていないかというのをきちんと説明してもらわないと、うちも答えられないというのが正直なところです。私としては、公の立場で責任ある立場で、そういう物の聞き取り方はありえるかということを問いたいぐらいです。","id":"exchange-088"},{"speaker":"飯沼委員","kind":"質問","question":"だから、そちらから発した言葉に対して、これでいいのですかという質問であったわけなのです。こういう聞き方をしていいのかと、今、質問が来たので、それの質問はそちらから答えられた言葉をこうやって表現したものなので。","respondent":"齋藤子ども未来部長","answer":"前のほうの、「子どもを産む母親のせいですか」と言われて、「そうだ」と思う人はいらっしゃるのですか。（「いないでしょう」と呼ぶ者あり）ということなので、丁寧にご説明したつもりです。","id":"exchange-089"},{"speaker":"飯沼委員","kind":"質問","question":"では、もう一回質問の中身を、どうしてこういうことになったのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"飯沼委員","kind":"質問","question":"まだあったのですが、今、話が途中で紛糾してしまったのですが、まだ他にあるのですけれども、いいですか、具体的に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"飯沼委員","kind":"質問・要望","question":"地域と年齢ごとの認可保育園の需要調査を求めたのですけれども、ぜひそういうのをみんな求めているので、どこかで報告していただきたい。４番目の質問で、そこのところにぜひ保育園をと求めたので、そこが視野に入っていらっしゃったのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"飯沼委員","kind":"確認","question":"ごめんなさい、検討したときに、今まで林試の森の国家公務員の宿舎の話ばかり出ていたのですが、その横のところの都有地まで視野に入っているのかというところで、確認したかったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/462438?Template=document&Id=4900#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":64787,"voices":296}},{"id":"h28-20161128-5","meetingId":"h28-cm11","date":"2016年11月28日","dateIso":"2016-11-28","committee":"総務委員会","time":"午前１０時００分～午後 ２時３０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を60件整理しています。","topics":[{"id":"topic-01","title":"会議の運営上、順番を入れ替えて、契約議案の審査を先に行います。 まず、(4) 第１０３号議案 中延一丁目区営住宅および従前居住者用住宅新築工事請負契約","agenda":"会議の運営上、順番を入れ替えて、契約議案の審査を先に行います。 まず、(4) 第１０３号議案 中延一丁目区営住宅および従前居住者用住宅新築工事請負契約","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ちょっと今の委員長の発言と外れる部分があるかもしれませんけれども、幾つか伺っていきたいと思います。広くなったのかどうか、大体３ＤＫとか２ＤＫというのは、そのあたりを具体的に教えてほしいと求めました。","respondent":"小林施設整備課長","answer":"従前居住者住宅のＣタイプにつきましては、２ＤＫ、５０.１４m2。Ｄタイプ、１ＤＫ、３０.３６m2となっております。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"平米単価、割り返すとというお話なのですけれども、全体をひっくるめてですから、電気設備だとか空調だとか等々いろいろありますね。５０m2を超えているというファミリータイプ、それは伺っておくということでいいと思いますけれども、そのあたりを説明を求めました。","respondent":"小林施設整備課長","answer":"例えば、今回みたいな中延一丁目は単品でこれをつくるのですけれども、地盤面からそのまま作っていく。２１戸そのまま、区営住宅についても２１戸です。","id":"exchange-002"},{"speaker":"南委員","kind":"意見","question":"不勉強も不勉強だと思うのですけれども、だから、そういうところを……。〔「だから入札をやっているじゃない、入札制度だよ」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"そんなにでたらめな金額だということはもちろん全然思っていないです。そういう質問をさせていただいたのですが、そういう説明を受けとめていきたいと、そういうふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"従来の建物は、耐震補強はもう済んでいるかと思うのですが、これは何年前に実施したのですか。そういういろいろなものを考えた上で、今回、新築というところに走ったと思うのですが、その辺を説明を求めました。","respondent":"立川経理課長","answer":"区営住宅なのですけれども、昭和５０年に建築されたということで、築後約４１年たっていると。耐震工事が必要ということで考えていたところですけれども、築後４０年以上たっておりますので、建替えをするということになったところです。","id":"exchange-005"},{"speaker":"須貝委員","kind":"意見","question":"財政的に今やるべきだという決断だとは思うのですが、どうなのかなと、何とか耐震補強等をやって維持していくのが筋ではないかと思います。意見だけ言わせてくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"容積率と建ぺい率を教えていただきたいのと、もし両方とも結構余裕があるならば、なぜめいっぱいにしなかったのかなと。そうすると、政策的な判断になってくるのだろうけれども、そこら辺のところをまず教えていただければ。","respondent":"小林施設整備課長","answer":"計画説明会などでご意見をもらったところですが、なかなかめいっぱい建てるところが難しかったところは事実としてあります。なかなかこの上に建てるということが非常に難しかったというところで、計画の段階ではこれが一番容積率的にはいっぱいとったです。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"今の４０万円の部分についても、例えば区営住宅を一方では増やしていけという政党というかお考えの方も議会でもいらっしゃるわけではないですか。そこら辺の物事の説明の仕方というのか、考え方というところは、どういうふうにお考えなのかということを聞きたいだけです。","respondent":"小林施設整備課長","answer":"ただ、近隣の住民からのご意見を頂戴するときには、ご理解がかなり難しいところがあります。非常に難しい質問ですけれども、そういうところでまずは事業を進めていくというのが大前提でありますので、非常に難しい課題だと考えています。","id":"exchange-008"}]},{"id":"topic-02","title":"第１０４号議案 浜川雨水排水管建設工事その２（浜川公園人孔等整備）請負契約の変更","agenda":"第１０４号議案 浜川雨水排水管建設工事その２（浜川公園人孔等整備）請負契約の変更","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"こういう工事を行うのにあたって、関係諸官庁といろいろ打ち合わせをして、それでこの見積もりを出していくのではないですか。見積もりをとって、入札にかけると思うのですが、それはしなかったのか尋ねました。","respondent":"和田河川下水道課長","answer":"ただ、この詳しい管の位置とか、それから施工できる立孔の位置とかは、やはり現場に入ってから測量しないとわからないところがあります。基本的に区役所が積算するのは、図面上はできると判断して、設計上は地上からの地盤改良工法ということで積算をしたものです。","id":"exchange-009"}]},{"id":"topic-03","title":"第９５号議案 品川区災害復旧基金条例、および(2) 第９６号議案 品川区災害復旧特別会計条例","agenda":"第９５号議案 品川区災害復旧基金条例、および(2) 第９６号議案 品川区災害復旧特別会計条例","exchanges":[{"speaker":"南委員","kind":"確認","question":"改めてこの基金の目的をはっきり明記しなかったのは、何かお考えがあるのかということを、その辺を確認をしたいと思います。そういう点で、なぜ予防を入れないのか、仕分けをしたそこのところの趣旨がどうなのかをまず伺っておきたいと思います。","respondent":"秋山財政課長","answer":"そういう今まで進めてきた施策の中に、防災に対する備え、施策の中に位置づけられているものだというふうに考えております。１つは、今回、ご提案をさせていただいたものです。","id":"exchange-010"},{"speaker":"南委員","kind":"提案","question":"しかし、やはり書いておいたほうがいいのではないかと思ったので、そのあたりのことを１つ伺います。それともう１つ、何年も前から、議会の場でも防災に関する基金をつくる必要があるのではないかという提案がいろいろな方々からありましたとの意見を述べました。","respondent":"秋山財政課長","answer":"若干難しいだろうというふうに考えておりますし、災害の後の状況を考えますと、目的というところが書いていないというものです。今回、こういう特別会計を設置したというふうに考えておりますので、そのようなお答えをさせていただければと思います。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"どんなことを想定しているのですか。困ったということは、どんなことが困ったと聞いているのか尋ねました。","respondent":"秋山財政課長","answer":"特別会計を設置するということは、説明のときには若干説明も薄かったかもしれませんが、設置の条例をご議決いただいた以降は。より対応を十分なものにしておく、そういう考えで、特別会計を設置したと考えています。","id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"なぜそういうふうにやれてきたのに、こういうふうに変えようとしているのかという趣旨が、あまり根拠がないかなと思いました。改めて伺って、ほかの方に譲りたいと思います。","respondent":"秋山財政課長","answer":"それは想定ができないということと、どんな復興が行われるかというのは、その時点でわからないということがありますので。それに対応する予算は、この特別会計の中で使っていきたいというふうに考えていることもあり、条例の中に復興という言葉を入れさせていただいたです。","id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"そして、品川区でこのように基金を、とりあえず基金のほうですが、つくるということで、急に１５億円という話が出てきました。もうこれは一定でとめてしまうのですと、名前だけですということなのか、その辺について説明を求めました。","respondent":"秋山財政課長","answer":"それが必要なのだというふうに区が考えを変えたというか、そういうふうに考えたので、特別会計をつくったというふうにご理解いただければと思います。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"では、これが本来なら、予算が出たときに、そのときに明示すべき話ではないのですか。これだけ立派な、世間にも公表をもちろんしているわけだし、その辺についてどうお考えか尋ねました。","respondent":"秋山財政課長","answer":"そう考えると、特別会計がつくっていないと当初の議案は提出できないと思っています。平成２９年の第１回定例会の中で特別会計の予算をご審議いただく、この手続が必要だというふうに考えたので、提案するということになりました。","id":"exchange-015"},{"speaker":"須貝委員","kind":"提案","question":"せっかくこんな立派なものを提案されてくるならば、提案をすべきだったのではないかと、去年もいきなり文化スポーツ振興基金が出ました。意見だけ言っておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"確認させていただきたいのですが、その内容について教えていただきたいのと、どういうふうにしているのかをまず説明を求めました。","respondent":"秋山財政課長","answer":"災害の救助と災害の復旧というふうに今考えているところですので、応急仮設住宅の設置等、災害救助法に定められたものがあります。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"１５億円についての見通し、１,２００億円とかではないということでしたが、わかりました。お金の管理ということで言うと、どうやってお金を、この１５億円については管理していくのかについて教えてほしいと求めました。","respondent":"秋山財政課長","answer":"１５億円の見通しですけれども、今、検討しています。基金に１５億円を入れますので、基金として１５億円を持っていますので、使わなければ基金として管理をするということになります。","id":"exchange-018"},{"speaker":"大倉委員","kind":"質問・要望","question":"お金の管理とあわせて、イメージが少しつかないので、教えてほしいと求めました。","respondent":"秋山財政課長、中山企画部長","answer":"その１５億円があって、もう予算案がありますので、タイムラグがなくなりますというお話をさせていただいています。基金を使うには予算案が必要なので、そのための議決をいただいている、そういうふうにお考えいただければと思います。実際のスピード感を持って執行するというときの持ち方等で、片や数十億円の基金を持つというところの運用の話とのバランスかと思います。","id":"exchange-019"},{"speaker":"吉田委員","kind":"確認","question":"こういうつくり方で問題がないのでしょうかということが１個と、また、そういうことを審議しながら今後進んでいくということなのでしょうか。とりあえずそこまで教えていただけますか。","respondent":"秋山財政課長","answer":"その中で、やはり想定される災害を何にするかというところが非常に難しいというのが１つあります。状況、それから基金のほうに積める原資がどの時点で出てくるかという話もありますので、その時点で予算案として提出するという予定にしております。","id":"exchange-020"},{"speaker":"吉田委員","kind":"確認","question":"これから例えば具体的にどういうものに使っていくということが、その都度、議会の中で議論されていくというふうに考えてよろしいのでしょうか。今この漠とした感じで決めてしまっていいのか不安なものですから、その辺を確認させてください。","respondent":"秋山財政課長","answer":"発災から短期間の間にというものは現金としてのものというご説明をしますけれども、当初予算の中でご議論をいただくということを考えておるものです。","id":"exchange-021"},{"speaker":"吉田委員","kind":"確認","question":"最後に確認なのですが、最初の予算規模の１５億円というのは、補正予算の議論のときにもう１回これをやるということでよろしいのでしょうか。確認です。","respondent":"秋山財政課長","answer":"今回ご議決いただくのは条例の２案でございまして、繰越金を原資とした１５億円を基金に積むということの審議でありまして、それも含めてつくっていくものです。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"確認","question":"私の理解している確認と、そういう特別会計を設置するということは、いいことだと思っている。私は０－０だろうと思っているけれども、それぐらいの気でいるのかどうかというだけは聞きたくなってしまった。","respondent":"桑村副区長","answer":"この特別会計を設置するのは、１つは、これは議会の中でご議論いただきたいというのも１つあります。例えば１５億円で組めば、１４億円ぐらいはそのまま何も使わないという、提案させていただいているというようなことです。","id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"意見","question":"よく言う３日間という話とか、２日間という人もいる、食料については。その後どうするのだという話があるけれども、それは予防というか、私はこの特別会計については０－０で十分との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"南委員","kind":"質問","question":"それこそ発災したときはすぐに引き出して使える、そういうふうになると思うので、有価証券についての考え方を１つ伺いたいと思います。やはり区民１人当たり３日分の食料とか水とかのそういう備蓄はしているわけですから、そういうことには私はあたらないというふうに思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"賛成していいのか、反対していいのか判断ができないから言っているわけですから、それはそれでご自分の意見として黙って聞いていてください。〔「理解していないから、説明を聞いていないから言っているんだよ」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"南委員","kind":"意見","question":"石田秀男委員、ちょっと静かにして聞いてください。〔「どうぞしゃべってください」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"ずっと今まで主張してこられたタイムラグの部分をどうするかというのだったら、私は納得、理解はできません。改めてそこのところについて伺いたいと思います。","respondent":"秋山財政課長","answer":"幾つかご質問いただいていますけれども、まずは有価証券の件でありますけれども、これは基金の通常の、ほかの基金も同じような文言を……。〔「違うのです、趣旨が」と呼ぶ者あり〕 お金を持つ、現金を持つということと同等というふうに考えていただいて結構だと考えています。ただし、その間のお金を十分に用意しておくという意味で、今回、特別会計をつくらせていただきますです。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"質問としては伺ってこなかったのですけれども、法人住民税ですか、そういうふうに思ってしまいがちであります。どんな大災害が起きても、そういう対策こそ求められて、積み上げようとする１５億円プラスアルファをそういうところにこそ使うべきだと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"つる副委員長","kind":"質問・要望","question":"最後に確認も含めて、また自分自身の理解の部分も含めて教えていただきたい部分が幾つかありますが、各委員から何度も確認があったとおり。それが特別会計条例のほうにある経理状況を明確というところになるわけですから、そういう理解でいいかどうかという確認をお願いしたいと思います。","respondent":"中山企画部長","answer":"それから、都道府県を通じて歳入されるまで２カ月ぐらいかかる。冒頭ありましたような、区として迅速な体制を基金と会計という形で執行までしっかりとっていきたいということをお諮りしているものです。","id":"exchange-030"},{"speaker":"南委員","kind":"意見","question":"こういう基金を、あるいは特別会計はこれからですけれども、会計をつくっていなくても十分に大災害には対応してきていると。やはりそれは改めてこういうふうにしなくても、私はいいのではないかと思っていますので、そういうことも含めて反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"南委員","kind":"質問","question":"復興まで広げていて、これは議決を先にしてしまうわけですから、そういう点で非常に問題があるのではないかと思っています。復旧、復興まで拡大していくというのは、やはり賛成できせん。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]},{"id":"topic-04","title":"第１１３号議案 職員の給与に関する条例の一部を改正する条例","agenda":"第１１３号議案 職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"３年連続職員の給与に関する条例、国税庁の民間給与実態統計調査だと、１人の勤労者の平均給与は４２０万円だと。平均がこういうふうに４２０万円というふうに出ていますが、その辺についてどのようにお考えなのか、説明を求めました。","respondent":"米田人事課長","answer":"ここ３年ばかり、わずかではありますが、そのときには値下げというようなことでマイナスということでの給料表の引き下げも図っているものです。ですので、職員の給与の比較といたしましては、いわゆる公務員比較の対象としては正しいものではないかというふうに考えてあります。","id":"exchange-033"},{"speaker":"須貝委員","kind":"意見","question":"５０人以上の規模の方の勤労者所得も含めてということですが、給与所得者数５,６４６万人を対象にして、給与総額をこの人数で割っている。対象が５,６４６万人という方を対象にした平均給与と、あまりにもかけ離れていると思うのですが、そこについてもう１回説明を求めました。","respondent":"米田人事課長","answer":"実際にそこにいる職員の方の勤務形態等もいろいろ違いますし、役職や年齢、そういうものも全て積み上げた上で平均的に数字が出ているものです。役職、それをきちんと民間の５０人以上の従業員の方と対比した上で計算しているものですので、ご理解いただければと思います。","id":"exchange-034"},{"speaker":"須貝委員","kind":"意見","question":"私はきちんと意見を申して、今はとどまるべきだろうというような、そういう意見もしっかり言っていくべきではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"教えていただきたいのですが、特別区人事委員会の勧告、これはこれで、５０人以上、前は１００人だったところを５０人までしてやってきた。所得を合わせますというようなことがあわせて出てきたと思うのだけれども、こういうことはこれからも起きてしまう可能性はあるのか尋ねました。","respondent":"米田人事課長","answer":"２３区必ずしも横並びの必要があるかといいますと、特別区の区長会と都区連等が妥結したものは、ある程度意味があると思ってあります。特別区においても大体１００円未満ですと改定は行わないということですので、それでこういうような結果になったものとご理解いただければです。","id":"exchange-036"}]},{"id":"topic-05","title":"平成２８年請願第１５号 「不調」となった入札結果を踏まえ、八潮６９号棟（雇用促進住宅八潮宿舎）の購入","agenda":"平成２８年請願第１５号 「不調」となった入札結果を踏まえ、八潮６９号棟（雇用促進住宅八潮宿舎）の購入","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"国としてはこの住宅は廃止というふうになるわけですから、そうなったら住民はどういうふうになるのか、その辺が非常に不安だと思うのです。そのあたりは、区が「教えてください」というようなことを問い合わせしたときには、一定の見解は出してくれるのか尋ねました。","respondent":"柏原企画調整課長","answer":"方針につきましては、国、機構の責任においてきめ細かな対応をしていくといったところが主であるというふうに考えてありますので。ただ、それはまちづくり全体という形では検討は引き続きしていきたいというふうに思ってありますけれども、それぞれの目的になりますので。","id":"exchange-037"},{"speaker":"南委員","kind":"質問","question":"ぜひ品川区にすがるしかないのではないかという思いで請願を出されてきているわけですから、そういう点について、あまりにも冷た過ぎると思うのです。その辺の認識、どういうふうに見ているのかをまず伺いたいと思います。","respondent":"柏原企画調整課長","answer":"検証しているといったところですので、不調前提のところでの検討をしているわけではありませんので、まずはそこに向けてやっていくです。","id":"exchange-038"},{"speaker":"南委員","kind":"質問・要望","question":"比較的低廉な家賃の６９号棟の存続というのは重要ではないかと、それについて答弁をもう１回求めたいと思います。ＳＰＣに売却されていったらどうなるのかというのは、どういう問題が出てくるのかというところは、わかる範囲で教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"１つの企業体では、幾つかの会社が合同で運営するというようなところも入札条件でよろしいということで、機構のほうで判断したものです。今後１０年間につきましては、区といたしましては、特にコメントを持っているものではないというものです。","id":"exchange-039"},{"speaker":"南委員","kind":"質問・要望","question":"１桁の極めて低いほうの、そういう状況、私が見たときはそうでした。そういう状況に歯どめはかけられないわけですから、改めて伺いますけれども、その点についてはいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"国の方針等々で、機構、国が責任を持った対応をしていくというのが大前提だろうというふうに思ってあります。売却方法等々を検証して、それが今後の流れとして区の対応といいますか、考え方は今までどおり変わらないです。","id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"民間ですから利益が上がらなければ、そんなものは反故にされてしまう可能性もないわけではないわけですから、非常に不安。私が説明したことを質して、きちんと向こうに申し入れなりをしていただきたいと思っていますけれども、それについてはどうか尋ねました。","respondent":"柏原企画調整課長","answer":"そういった形で住んでいる方たちの不安が大きくならないような形で、区からもそういったことは述べさせていただきたいと思ってあります。どういう形になっているかというのは、個々の部分があろうかと思いますので、ここでコメントするのは控えさせていただきたいと思います。","id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、そこはしっかりと調べていただいて、とんでもないと言って訂正をさせるように働きかけはしていただきたいと思っています。その点について最後に伺って終わりたいと思います。","respondent":"柏原企画調整課長","answer":"その後について、双方の合意でもう１回契約するのかしないのかというところがあります。こちらの物件に関して、個別の状態で私も知り得ない部分がありますので、それについては確認をさせていただきたいというふうに思ってあります。","id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"２月の段階で不安に思っていらっしゃるわけですから、それから約１年たって、もうおしりがあと５年という感じで決まってきてしまうわけですね。２月の時点の議論の中でも、もう少し機構に対して見通しというのでしょうか、その辺についてはどのように進んでいるのか教えていただけますか。","respondent":"柏原企画調整課長","answer":"検討はしていくということで、スムーズな形の手続に入るようにということで、我々も再三この間につきましては申し入れております。今の段階では明確にお話はできないという回答ですので、これにつきましては、引き続き働きかけていきたいというふうに思ってあります。","id":"exchange-043"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ急いで進めていただきたいというのが１点と、やはりもうあと５年しかないので、やはり住民の方にとっては当然の不安なのではないかと思うのです。区としてはどういうフォローをするとか、機構としてはどういうフォローをするつもりがあるというか、その辺はいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"それは十分認識はしておりますので、今後の対応ということで進めていただきたいということは、引き続き申し入れをさせていただきたいというふうに思ってあります。","id":"exchange-044"},{"speaker":"吉田委員","kind":"意見","question":"私がお話ししているのは、この八潮住宅のこのことについては、今年の第２回定例会にも確かに出ておりますけれども、その前の２月というと第１回定例会のときも、その前段階の請願が出ていると思うのですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"吉田委員","kind":"確認","question":"ほかの会派からも、区民のあれは守るのだねというような確認の結果、やはり不採択だったのですけれども、そのときの……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"吉田委員","kind":"意見","question":"すみません、ちょっと待って、どうしよう。少し休憩」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"大倉委員","kind":"質問・要望","question":"入札結果について、東ブロック応札なしということで参加資格者１９社というところに、品川区は入るのでしょうか。その辺を教えていただきたいのと、先ほどから２月の話もありますが、どの辺までいろいろな話ができるのかという確認をさせてください。","respondent":"柏原企画調整課長","answer":"それから、どういう対応をとるかといったところの間に入っての調整であったりとか、そういったところを個別にはさせていただいているところです。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問・要望","question":"第１回定例会の、２月の段階で、フォローというところまで保証すべきではないか。品川区としてももう少し主体的に機構に積極的に働きかけていただきたいというふうに思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"でも、それに対して明確な回答があるということではありませんし、そこを前提の話ではないというところでありますので。個別の対応も含めて、どういった形ができるのかというのは、ご相談に応じたいといったことは引き続きさせていただきたと考えています。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問・要望","question":"今度、いわゆる民間の私対私の契約の住まいについてのものと、ちょっと違うのではないかという気はいたします。話し合うということでは、区民の住宅をきちんと確保すべきというところについては、もう少し強く申し入れをしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"石田（秀）委員","kind":"確認","question":"そこも確認はとれていないのだけれども、南委員が言って、最初に決まったときにはこういうふうに言ったという方もいらっしゃるのかもしれない。改めてそこは区も確認をして、そこはもう１回確認を、どういうお考えでいらっしゃるかということを確認をしたいと思います。","respondent":"柏原企画調整課長","answer":"我々も１０年間という数字が出ているのは認識しています。もし誤解があるような説明をされているのであれば、それはもう少し丁寧な対応をとるべきだというふうに思っています。","id":"exchange-051"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひそこの２番目の確認はしていただきたいと、区民の方も品川区民であるし、そこら辺の誤解がある説明であってはいけないのかと思っています。そこの対応は１０年なのか、５年なのか、私はいい方向性だと思う。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"須貝委員","kind":"質問","question":"そしていろいろ相談に応じてそれなりのきちんとした回答またアドバイスをしているわけですから、私は介入するというのはいかがなものかなと思います。これからも住民のために支援していくということですから、契約書、法の下に進めていくというのが区の立場であるべきではないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"廃止するということですから、その後の５年間の全体で今から言って売れたときの１０年間ということだから、改めて確認をしておきたいと思っています。そんなところはどんなふうに見ておられるのかということを伺っておきたいと思います。","respondent":"柏原企画調整課長","answer":"持っている方々が、まず責任ある態度といいますか、考えを持って行動すべきものであるというような見解です。今後の入札等々に向けて、今後についても真摯に対応していただけるようにということで申し入れはさせていただきたいというふうに思ってあります。","id":"exchange-054"},{"speaker":"石田（秀）委員","kind":"意見","question":"購入については、先ほども言ったけれども、私はするべきではないと思っていますので、不採択。不採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"つる副委員長","kind":"確認","question":"態度については不採択です。今もこの６９号棟の自治会の皆さんは、これも会派の中で確認したときにされているというふうに伺っておりますし、この請願については不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"南委員","kind":"質問","question":"態度賛成の理由は、先ほどの質疑で述べたとおりです。あるいは、どういう状況かというところをどういうふうに認識しておられるのかというのは、ちょっと伺っておきたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"大倉委員","kind":"質問・要望","question":"てきるだけそうした不安の払拭に努めていただきながら、これについて連携、機構等としっかりとお話をしてほしいと求めました。購入については、購入については支持しておりませんので、これについても願意に沿い難いということで不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですが、やはり法治国家ですから、そこをやはりきちんと理解していただいてやってほしいと求めました。請願の趣旨に対しては反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"吉田委員","kind":"意見","question":"どうなるかわからない段階での結論というのは、ちょっと難しいのではないかと思って、一巡目は継続を主張しました。機構と真剣に話し合ってほしいということについては、話し合った結果の結論はまたどうかということはあると思うのですけれども、採択を主張しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701406?Template=document&Id=2062#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":64235,"voices":193}},{"id":"h28-20161129-6","meetingId":"h28-cm11","date":"2016年11月29日","dateIso":"2016-11-29","committee":"区民委員会","time":"午前１０時００分～午後 ２時４７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"本日は、都市型観光","agenda":"本日は、都市型観光","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"この品川区観光振興協議会というのが設立されて、今後の都市型観光を品川区で確立というのですか、期待をするところです。だからその辺をどうお考えかというところを、とりあえず説明を求めました。","respondent":"鈴木文化観光課長","answer":"先ほどご説明しましたように、それから個人ではありますけれども、観光協会というＩＤをとって情報発信しているというのが１つのパターンです。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"協議会というのは集合体ですから。私の一般質問で聞いたかもしれませんけれど、こういうもので今、品川区に来訪される外国人は何を求めて来ているのか尋ねました。","respondent":"鈴木文化観光課長","answer":"これは外国人の対応を主にしている方ですが、案内をした外国人の方から出された要望とか意見、こういうものも入っております。じゃあ、品川の観光の外国人対応はどうしたらよいかというのを考えているというところで、国や都の統計的な情報ということになります。","id":"exchange-002"},{"speaker":"いながわ委員","kind":"質問・要望","question":"誰かが外国人のデータはどうなのか出してくださいということで、すぐ出せるような状況にはしてほしいと求めましたので、よろしくお願いします。一言あれば、一言で構わないのでお願いします。","respondent":"鈴木文化観光課長","answer":"ご指摘のとおり、確かに根拠を統計的な資料としてしっかりとお示しできる必要があるというのは、区としても認識しております。説明が不足していたかもしれませんが、まず区の保健所とかで把握しているデータの照会が、国からまいります。","id":"exchange-003"},{"speaker":"いながわ委員","kind":"質問","question":"１年間どんどん積み重ねて、２年、３年とできるわけですよね。そういうものが出せるようにしてくださいという質問をしているので、そこがほしいので。","respondent":"鈴木文化観光課長","answer":"失礼いたしました。ご指摘のとおり、しっかりとデータを積み上げて、傾向とか推移とかも見られるような形で、情報の分析も続けていきたいと考えております。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜ品川は観光かという思いについては、区としてはどういうふうに考えていらっしゃるのか、伺いたいと思います。３つ目は、どうしてそこまで力を入れるのか、改めてそこの説明も伺いたいと思います。","respondent":"鈴木文化観光課長","answer":"それは確かにいろいろな対応をしなければならない課題も一緒に来るとは思うのですが、品川のことを知っていただくというチャンスです。文化観光課が実施するものと、平成２８年度、今年度予算で約１億７,０００万円の予算を計上しております。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"その辺について、区の見解を伺いたいと思います。その点についてはどのようにお考えなのか、伺いたいと思います。","respondent":"鈴木文化観光課長","answer":"もちろん１００％、一定程度しっかりと、暮らしの部分の施策は行われているというふうに認識はしております。しかし、それのために観光をやるということは、考えとしては持っておりません。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"最後にもう１点、別のことで。品川の上を通過する飛行ルートに期待をしているのか、計画を容認しているのか、そこを伺いたいと思います。","respondent":"鈴木文化観光課長","answer":"私は所管ではございませんので詳しい情報やそれに関する区の考え方を私が申し上げるものではございませんが、羽田空港の機能が強化されるということは、観光にとってプラスだというふうには考えております。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"品川の上を通るかどうかでなくてといっても、議論されているわけであって、そこは切り離せない問題だと思うのです。上を通る問題は切り離せないと私は思いますけれども、先ほど視野に入れてというお話がありましたので、そこにかかって伺いたいと思います。","respondent":"鈴木文化観光課長","answer":"区の考え方を見聞きしている上での答弁になりますが、していないという話ではなくて、必要だからやらなければならないということは認められると。いろいろな危険性というのは区としても認識しているので、いろいろな要望を出しているというふうに、認識しています。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"はじめに、副会長の方ですけれど、跡見学園女子大学の教授ですけれども、都市観光といえば立教大学だと思うのですけれど、その辺はいかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"数年前に跡見学園女子大学のほうで観光の学科を設置して、入っていただいたというふうに聞いております。たしかその前に、立教大学で観光の研究をされていたというふうに聞いております。","id":"exchange-009"},{"speaker":"藤原委員","kind":"確認","question":"はじめに、都市観光と都市型、「型」が入っているのですけれども、そもそも論ですが、都市観光と都市型観光というのは違うのでしょうか。いいのかということの確認と、なぜそこまで観光に力を入れなくてはいけないのか、改めてお伺いします。","respondent":"鈴木文化観光課長","answer":"１点目の都市観光と都市型観光の違いというご質問ですが、区としては都市型観光という名称、概念で観光事業に取り組んでおります。それに関する観光というのが一つのカテゴリーというか分野として連携することで、効果が出せるという発想からだというふうに認識しております。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"とても細かいことで１点あるのですけれど、出ているのであえて伺いますが、踏切。あそこに伊藤公のお骨はあるのか尋ねました。","respondent":"鈴木文化観光課長","answer":"そういう視点でより効果的な連携ができるような体制に組みかえるということをやっておりますので、改正される可能性はあるかと考えております。ただ、先ほど申し上げましたように以前の１０年間のアクションプランについては、当時のそういう考え方で進めていたのだと思います。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"という思いがあって、あえて最後にお伺いしますけれども、課長はどういうふうに思っていらっしゃるのかというのを最後にお伺いしたいと思います。どのぐらいなのか、行政がどのぐらいかかわっていくのか、改めて観光の重要性も含めてお話ししていただけますか。","respondent":"鈴木文化観光課長","answer":"それぞれの所管が連携して、より品川区をよくしていくというのが、区の考え方だと考えています。福祉が先とか、状況によって重点的に取り組むという位置づけはありますけれども、全部しっかりとやらなければいけないことであると考えております。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問・要望","question":"昨日もこの委員会で、その他のところでビーチバレーのパネルのことを伺ってしまったのですけれども、少し気がかりなニュースを見ました。ちょっと情報があれば教えていただきたいです。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"実は昨日付で、都議会自民党が東京都に対して緊急提言をされています。具体的にビーチバレーボール会場について、抜本的に見直したほうがいいということが書かれていたということで、その点は認識しているです。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"第１回定例会のときに、そしてブラインドサッカーが予定と出てきて、正式にはブラインドサッカーはならないわけです。どういう対策をしていくか、現時点でいいですから、お考えを教えていただけますか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"早くから機運醸成の事業をしてまいりましたので、引き続き区で、当初の予定どおりやっていただきたいという気持ちです。都議会の自民党ということでお考えがあって提言されていると思うのですけれども、引き続きアプローチしていきたいと考えています。","id":"exchange-014"},{"speaker":"本多委員","kind":"質問","question":"はこれを述べまして、質問に入ります。事務局はどういうふうな位置づけになるのか、平成２８年１１月１日現在で８５という数ですが、その辺を説明を求めました。","respondent":"鈴木文化観光課長","answer":"それから今後の拡大について、もともとの趣旨が区内で観光にかかわる多くの方に入っていただきたいということでお声がけしております。協議会でいろいろ検討している中でも、参加いただけるという意思表示をいただければ、入ることは可能です。","id":"exchange-015"},{"speaker":"本多委員","kind":"質問・要望","question":"今現在進めていることですから、あるべき姿だと思うのですけれども、何かもっと展開が足りないように思うのです。品川区の発展になると思いますので、その辺の目線をお願いしたいと思いますが、いかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"基本的な方針や情報の共有、新しい方も、あまり取組みについての制約があるわけではないというふうに考えております。連携を支援することで促進するという考え方でおりますので、当然新しい方もどんどん参入いただいて、拡大したいと考えております。","id":"exchange-016"},{"speaker":"本多委員","kind":"質問・要望","question":"花海道などの自然と、自然のものと人の手を加えたものとメリハリをつけてやってほしいと求めましたので、水辺も充実していただきたい。それは個別の話ですけれど、一つ一つ要望を区からも申し入れてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"田中委員","kind":"意見","question":"新しいものをつくる、つくるではなくて、もう少し区内のそういう本当に資源に目を向けてほしいということと。来るわけですけれども、大井町駅前のイルミネーションは、明るいところに明るいものというのはどうなのでしょうとの意見を述べました。","respondent":"鈴木文化観光課長","answer":"住民の方に知っていただくことで品川区の魅力を再認識したり、今回は４回連続のコースで品川の観光を取り上げて、お知らせをしています。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"そういうところに目を向けてほしいと思います。２０２０年の後のこと、それがこのプランでは読み取れなかったと思うので、そこの部分を教えていただきたいです。","respondent":"鈴木文化観光課長、濱田生活安全担当課長","answer":"対応が必要だというふうには考えておりまして、マナーのお知らせというのも、情報発信の中で取り組んでいるところです。平成３２年までと、平成３３年以降ということで、考えているところです。 こういったことで考えておりますので、ここが三位一体となって対策を行うのが、一番効果的だと考えます。区では今１６団体ありますが、そういった方たちと区と警察が情報を共有しながら、治安対策を進めていきたいと思います。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"そのことは中小企業の方たちもとても気にしているのですけれど、オリンピックが終わってからというのがとても重要だと思うので、考えてほしいです。今、一都六県で工事計画承認処分の取り消しを求める行政訴訟が起きていることを、ご存じか尋ねました。","respondent":"鈴木文化観光課長","answer":"方針と戦略を立てた計画でございまして、今から５年後以降の計画を細かく記載することは、適切ではないというのが一つあります。申し訳ありません、品川区の観光にどう取り組むかということを考えますという意味で、ご理解いただければと思います。","id":"exchange-020"},{"speaker":"田中委員","kind":"質問","question":"区が推進していますよというふうに捉えられると思うのですが、この辺に関しても伺いたいというのと。終わってからどうなったかという話はあるので、今から考えておかなければいけないと思うので、見解を伺います。","respondent":"鈴木文化観光課長","answer":"さまざま視野に入れなければ、もしくは考慮しなければならない項目について、大きな動きがあるものであるから載せているという認識です。それから５年後を今から考える必要があるですが、区としても５年たったら考えるということではありません。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問","question":"最後に伺います。治安のこともそうですし、五輪後のことなども、本当にきちんと計画を立てて、それを示してほしいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"こんの委員","kind":"質問","question":"いいねと言ってもらえる気分はとてもいいですし、住んでいる私たちが、そのいいと言ってもらえるところに住んでいる優越感というのでしょうか。私たちの日常茶飯事、そうしたものを拾うというか発掘する意味でも、在住の外国人の方の調査というのはどういうふうにされるか尋ねました。","respondent":"鈴木文化観光課長","answer":"調査の方法につきましては、お答えしたところですけれども、観光地としてのマーケティング調査というのは手法として有効だという認識はしております。","id":"exchange-023"},{"speaker":"こんの委員","kind":"提案","question":"提案なり、ただ一方で、先ほどのほかの委員の声もなくはないと承知しています。いろいろなイベントのときも、限られた予算の中で精一杯頑張っていただきたいと、エールを送りたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"伊藤副委員長","kind":"質問","question":"もう具体策はなかなか出てこないのですけれど、どうなのかということと、それからこの後ですね。５年、１０年たってしまう気がするのですが、いかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"それからホームページ、区でも観光協会でもそうですけれども、そういう情報発信も取組みが少し始まったというのは、やはり成果だと考えております。","id":"exchange-025"},{"speaker":"伊藤副委員長","kind":"質問","question":"私が危惧したのが、平成１８年から平成２７年の１０年間で計画をつくった、これは新しいことなのでしょうけれど、時間をかけすぎではないでしょうか。それを例えば２年、３年のプランの中で具体化していくとか、いかがでしょう。","respondent":"鈴木文化観光課長","answer":"ご指摘のとおりだと思います。新たな展開のフェーズに移ったと認識しておりますので、効果なりが出るような取組みを、しっかりしていきたいと考えております。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/294647?Template=document&Id=2770#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":33547,"voices":61}},{"id":"h28-20161129-7","meetingId":"h28-cm11","date":"2016年11月29日","dateIso":"2016-11-29","committee":"厚生委員会","time":"午前１０時００分～午後 ０時０１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"西大井四丁目障害者グループホーム整備","agenda":"西大井四丁目障害者グループホーム整備","exchanges":[{"speaker":"松永委員","kind":"質問","question":"いつもだと、資料に図面で大体屋上がどうなっているか記載があったと思うのですけれども、この場合の屋上はどのような形になっているのか説明を求めました。","respondent":"中山障害者福祉課長","answer":"これは木造の通常の家のような形になります。ただ、一部２階の上にロフトは設けさせていただいて、屋上は特になく普通の屋根という形状になってあります。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"なぜ区立で指定管理者という形にせずに、福栄会に土地を貸し付けるという形になったのかということを、１点お聞かせください。わかったら教えていただきたいのと、東京都とか国からの仕組みがどうなっているのか、補助金の仕組みについてもお聞かせほしいと求めました。","respondent":"中山障害者福祉課長","answer":"それから、区からも東京都で出ない部分の建設費の補助金とかがありますので、区からは三百五、六十万円ぐらいの補助金が入るかと考えています。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは本当に求められている施設ですし、区としても今後、今どれぐらいということで捉えられているのかということについてもお聞かせください。それと、どういう資格のある方が職員となるのかということについても教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"皆さん入りたい方の希望を募る予定ではありますが、今、２４名ということにはなっています。世話人が各フロアにそれぞれ１人ずつ配置になるのと、朝ご飯の時間帯ですとか、そういうところは２人体制みたいな形で支援に入る予定です。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今相談を受けていて２４名で、何を基準に１０人を選んでいくのか、そこら辺をどう考えるのかということをお聞かせください。１２月に今度は建設計画の近隣説明会があるということで、地域の受けとめというのはどういう状況だったのかということについても説明を求めました。","respondent":"中山障害者福祉課長","answer":"選考に当たりましては、福栄会と区と一緒に入って、あるいは相談支援センターのケアマネジャーにも入っていただいて、行う予定になっています。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問・要望","question":"今回、定員１０名のグループホームということで伺いました。その用途について教えていただきたいのと、あと２階に居室がある方は、ここら辺のレイアウトも含めた環境を教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"２階は、完全に玄関を切り分ける必要もありますので、階段で２階に上がっていただいて、そこからが入り口ということになっております。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問","question":"４ｍ道路なのかなというふうに見えるのですけれども、グーグルでしか見ていないのですが、そんなに幅広くないのかなという気がします。そのような会合というのでしょうか、定期的にやられるとか、そういうことは考えておられるのか説明を求めました。","respondent":"中山障害者福祉課長","answer":"前面の区道ですけれども、今私の手元にあると、４ｍ以上はあるのですけれども、４ｍ５０cm程度の確かに狭い道路ということになっております。そういった中で、また事故や危険のないように生活をしていくよう、福栄会とも相談していきたいと考えています。","id":"exchange-006"},{"speaker":"安藤副委員長","kind":"質問","question":"１点目が２階ということで、あと駐輪場がない点について、どのように区は評価しているのかというのをお伺いします。３点目として、知的障害者のご家族の方々から伺うのですが、以上３点お伺いします。","respondent":"中山障害者福祉課長","answer":"外部の方が来るときのちょっとした移動の関係であれば、車のところの横にとめてという対応はあるかと思います。そういったところも活用しながらイメージをつくような形を通じて、安心して次のステップに入れるように、そこは気をかけていきたいと考えております。","id":"exchange-007"}]},{"id":"topic-02","title":"猫の不妊・去勢手術費助成事業の実施状況","agenda":"猫の不妊・去勢手術費助成事業の実施状況","exchanges":[{"speaker":"松永委員","kind":"質問・要望","question":"伺いたいことは、現在は区内１１町会認定とあるのですが、ほかの町会はどうなっているのかという現状を教えてください。その捕まえた野良猫を持っていくと、その分は個人で負担しないといけないのか、その辺を詳しく教えてほしいと求めました。","respondent":"井浦生活衛生課長","answer":"ちなみに平成２８年度につきましては、１３地区全ての全域につきまして、各町会長の会議でこの事業の説明をしたところです。地域に働きかけて募金を募ったり、寄附を募ったりいたしまして、自己負担分については賄っていると聞いてあります。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"（３）のモデル事業ですけれども、どんどん受け入れて、これを拡大していくという考えなのでしょうか。だからそこのところが、何がクリアできればモデル事業として認定されるのかというところも説明を求めました。","respondent":"井浦生活衛生課長","answer":"拡大をしていきたいと考えています。１人ではなかなか実施することが難しいという事業ですので、町会でご協力いただく、このあたりのところもクリアする必要があるかなです。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"どんどんモデル地区、モデル事業を増やして、地域猫とする活動をどんどん拡大していきたいという考えでやっていられるのかというところを説明を求めました。","respondent":"井浦生活衛生課長","answer":"飼い主のいない猫の頭数は、４００頭という形で規模が大きくなってありますので、こちらの数字がモデル地区の数字に移行していけば、かなり地域猫の減少と、不幸な猫の減少ということで、動物愛護にもつながると考えているところです。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問","question":"１万円だと町会の負担が結構重くなるという部分で、平成２８年度から助成を増やしたということでいいのか、お伺いします。","respondent":"井浦生活衛生課長","answer":"１点目のモデル事業の助成につきましては、猫のコアワクチンということで、不妊・去勢手術にプラスアルファして助成するものです。","id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問","question":"個人で熱烈にやっている方、いろいろいらっしゃるのですが、特にグループですね。うまく区でマッチング的なこととか、そういうのはできる場合とできない場合があるでしょうけれども、やっていらっしゃるのか尋ねました。","respondent":"井浦生活衛生課長","answer":"このような担い手不足というところが、このモデル事業についてクリアすべき課題です。アンケートの実施等、成功事例の情報提供させていただきまして、猫の不妊・去勢の取り組みの成功というところを区として支援しています。","id":"exchange-012"},{"speaker":"たけうち委員","kind":"確認","question":"きちんとした場所といっても区道とかになってしまう場合もありますものですから、時にはすごく命の危険を感じるぐらいのこともあるのです。今後ご希望があるかどうかというのも確認してもらいたいのですけれども、ぜひ今後考えてもらいたいと思うのですが、一応ご意見だけいただけますか。","respondent":"井浦生活衛生課長","answer":"委員ご指摘のこのような献身的に行われている方が、餌を不法にやっている方と勘違いされるという声は寄せられてあります。あるいは会員証のようなものを工夫できないかということで検討してございまして、腕章のようなものであれば可能であると考えているところです。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１０分間ぐらいで終わってしまうということなのですけれども、猫の習慣からもなかなか大変だとお聞きしたのですけれども、そういう点ではいかがか尋ねました。","respondent":"井浦生活衛生課長","answer":"これは個々の公園の利用調整という中で公園課として受けとめて、支援してくださっているです。都立公園につきましても、同様の協力や支援をしているところがあるということを聞いてあります。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"朝の６時ぐらい、１０分間ぐらいで、迷惑がかからないようにもしているということでした。このモデル事業が大きく広がっていくと、もっとスムーズにいくのかなと思いますので、そういうところでぜひ今後も努力いただけたらなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]},{"id":"topic-03","title":"健康大学しながわの状況","agenda":"健康大学しながわの状況","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１つは、１つお聞かせいただきたいのと、健康推進委員というのがあります。関係ですとか、そういうことがあるのか、そこら辺の関係についてもお聞かせほしいと求めました。","respondent":"榎本荏原保健センター所長","answer":"１点目は民間委託のところですけれども、基礎編につきましてはルネサンスという会社に委託をしているところです。ふれあい健康塾を実施しておりますが、いい形で連携できると思うのですが、そういった関係になっております。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"健康チャレンジコースのところでは３０代、４０代、大学の受講をするというのは昼間ですよね。３０代、どういう人を担い手として、こういうところに応募されている方がどういう方なのかということについてもお聞かせいただけたらと思いますとの意見を述べました。","respondent":"榎本荏原保健センター所長","answer":"担い手として区が想定している人材についてですが、まずは健康に関心があることが大切だと考えています。活動していくということのやりがいといいますか、そういったところも徐々に見出していっていただいて、活動をしていただくという形で考えております。","id":"exchange-017"},{"speaker":"たけうち委員","kind":"質問","question":"１,１３８名の区民に健康教育を実施していただいたということなのですが、どういった場でそういう実施をされるのかということと、それを区民にもやっていただけるということなのかどうかということをお聞きしたいと思います。","respondent":"榎本荏原保健センター所長","answer":"ほっと・サロンでも実施しております。余暇的なグループの中のつながりということで、グループのメンバーの中で、例えばウオーキングなどを行っているグループもあります。","id":"exchange-018"},{"speaker":"安藤副委員長","kind":"質問","question":"公開講座のところでお伺いしたいのですけれども、テーマを選んでおられるのかなというのが１点と、直近の６月と９月と１２月のテーマがわかれば説明を求めました。","respondent":"榎本荏原保健センター所長","answer":"どんな健康のテーマで講演会をしたほうがいいかということを、そこでテーマを出し合って検討するというのもあります。第３回目が「バランス健康法」、今募集中なのですが、「がん死１０分の１を目指して」というがん予防のテーマです。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ケアパスは今年の１２月ぐらいにつくられるというふうな、できたら、ご報告いただける時期はいつぐらいになるかを教えてほしいと求めました。とりあえずそんなところで、また後で続けて伺います。","respondent":"永尾高齢者福祉課長","answer":"その第２稿の時点で、厚生委員会にご報告をしようかと考えておりまして、厚生委員会でのご報告は１月を予定しております。そのサポート医よりもさらに難しいことについて連携支援をお願いしたいということであれば、地域連携型認知症疾患医療センターとして。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのことをお聞かせいただきたいのと、サポート医が２８人ということなのですけれども、その点についてもお聞かせほしいと求めました。どういう方をどういうふうに選んで、どこら辺くらいまでされていくという計画で考えているのかについてもお聞かせほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"チーム員のメンバーについて、法律で決まっているのですけれども、誰にしようかとか、そういう細かいところについて検討会議の中で検討しています。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回学校も８回されているということなので、どういう学校に行かれたのかというのも教えていただきたいのですけれども、認知症とはというところを。銀行だったり、この品川の職域の１７回というのはどういうところでおこなわれているのかということについてもお聞かせほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"警察の件ですけれども、警察は昨年度に全部の警察の署員についてのサポーター養成研修が終了しておりますので、今年度は予定はございません。テレビ等でもいろいろ報道があり、関心が強いところですけれども、認知症ケアパスをうまく活用しながら広げていきたいと考えています。","id":"exchange-022"},{"speaker":"渡辺委員","kind":"質問","question":"上の整理表の４本立て、２８年度に入りまして、事例などを教えてほしいと求めました。これだったら私もできるなとか、そういう仕組みづくりを具現化していったらどうかなと思うのですが、その辺の考え方を説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"違和感なく普通に対応し、そういう対応ができるような地域にしていきたいと、まず第一の目標として考えております。区民の中にも、区のほうでいろいろな方法についての支援をしていくというのが自然な形かと考えていますので、まずはサポーター養成講座の人数を。","id":"exchange-023"},{"speaker":"渡辺委員","kind":"質問","question":"まだ道半ばというか、１０年間のスパンの中で、いろいろなそれこそチャレンジで進められるべきだと思っています。今後のこの辺の情報的なものというのでしょうか、まとめの時期だとか、大まかなスケジュールの目安を教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"アンケートの件ですけれども、結構厚さのあるアンケートでございましたが、回収率はその割にはよかったのかなと考えております。アンケートの結果ですけれども、できれば今年度中の委員会で報告をしたいと考えております。","id":"exchange-024"},{"speaker":"たけうち委員","kind":"質問","question":"真ん中あたりの徘徊高齢者探索システム（ＧＰＳ）ですけれども、さきほどご説明がありましたがちょうど９月末で２０件が登録されていると。その中で実際に徘徊されてしまって、ＧＰＳを使って見つかったというか、そういうケースが何件かあったかどうかというのを説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"そのうちオペレーターによる電話で検索をお願いした方が２８件、インターネットで接続をした方が８件という状況になっています。ただ、同じ方が何回もやっている傾向があるところです。","id":"exchange-025"},{"speaker":"たけうち委員","kind":"提案","question":"本会議とかでもご提案したかもしれないのですけれども、一回そういう訓練を品川でも考えてみたらどうかという提案をたしかしたと思うのですが、何か今後考えられるかどうかという方向性がありましたら説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"日本でもいろいろなところで模擬訓練をやっているというものを聞いております。ただ、認知症の検討会議等をこれからも続ける予定ですので、どういう方法でやるのが適切かということも検討していきたいと考えております。","id":"exchange-026"},{"speaker":"松永委員","kind":"確認","question":"何点か確認です、まず１点ですけれども、伺いたいと思います。これは１セットでお渡ししているのかという確認と、どういった場所につけたほうがいいですよというような、伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"は時間、何時から何時まではその在宅介護支援センターにご連絡してくださいということと、プラスチックの中に入っているものになります。どういうものをいつも持ち歩いているかとか、そういうことも相談の上、アドバイスはしています。","id":"exchange-027"},{"speaker":"安藤副委員長","kind":"質問","question":"当事者であれば、周りのご家族とかがまず悩まれたりとか、ちょっとあれはおかしいなというケースが多いと思うのです。現状がどうなのかということとあわせて、そこがどう変わるのか、そこら辺がどう表示されるのかなどをお伺いします。","respondent":"永尾高齢者福祉課長","answer":"今検討しているのは、どういうところに行った方がいいのかというようなチャートを、今つくっているところです。ただ、区として一番最初にＰＲするのであれば、在宅介護支援センターということになります。","id":"exchange-028"},{"speaker":"安藤副委員長","kind":"意見","question":"まだまだ介護保険そのものとか、そういった仕組みもご存じない方もいらっしゃったりしますので、そうしたところが、最初にここに相談できるというところをわかるように工夫してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その３職種がそろっていませんので、ここに相談すれば安心してというか、適切なアドバイスを受けられるという窓口をつくるべきだと思うのです。地域の方からも何人かから伺っていまして、在宅支援センターのところに３職種を配置していただきたいし、いかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"というのは、本当に多職種でチームで動かないと、なかなか対応が難しいところがあります。それを、この広い地域の中で、１つのところで何カ所もつくるというのは、かなり現実的には難しいかなと考えています。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"品川の区の中にある地域包括の中ででも、きちんと認知症のことで相談をしたいというところでの窓口というのはつくるべきなのではないかなと思うのですけれども、その点について伺います。","respondent":"永尾高齢者福祉課長","answer":"サービスを受けるためには在宅介護支援センターで相談してくださいという形で、最初のまず第一歩が在宅介護支援センターと考えているところです。その方の状況だとか悩み事をお聞きした上で、より適切な専門機関につながるような仕組みを、今考えているところです。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"すごく保健師の数が、うちは保健師が少ないのですといっても、品川よりもすごく多い数だったのです。地域包括を１カ所しかつくっていないというのも、そういう点でいえば、ぜひ検討していただきたいということで要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/540863?Template=document&Id=3464#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":35805,"voices":85}}]);
